window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s3-343","number":343,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"لماذا قابل الاعتصام بقوله ﴿ولا تفرقوا﴾ ولم يقل: واتحدوا؟","answer":"الأمر بالاعتصام يبين الأصل الإيجابي الجامع، والنهي عن التفرق يسد ضده وطرقه؛ فليس المطلوب اتحادًا على أي شيء بل اجتماع على حبل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص519–520، تحت «الاستعارة وأثرها في إثراء المعنى».","url":""}]},{"id":"s3-344","number":344,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"لماذا ذُكرت نعمة الله في تحويل الأعداء إلى إخوان؟","answer":"ذُكرت حال عداوتهم السابقة ليعرفوا عظم نعمة الله بالإسلام؛ فقد نقلهم من التباغض والتفرق إلى أخوة مؤتلفة، فيلزمون سبب اجتماعهم ولا يعودون إلى الفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص520–521، تحت «وجوه الإعراب، وأثرها في جلاء المعنى وإثرائه».","url":""}]},{"id":"s3-345","number":345,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فألف بين قلوبكم﴾، دون أن يقال: فألف بينكم؟","answer":"خص القلوب لأنها موضع العداوة والمحبة؛ فالتأليف الإلهي أصلح باطنهم حتى نشأت الأخوة، ولم يكن مجرد جمع للأبدان في ظاهر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص521–523، تحت «الاستعارة والإشارة وأثرهما في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-346","number":346,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فأصبحتم بنعمته إخوانًا﴾ مع أن التحول لم يقع في صباح واحد؟","answer":"ليست الإشارة إلى صباح مخصوص؛ فـ﴿أصبحتم﴾ هنا بمعنى صرتم ودخلتم بنعمة الله في حال الأخوة بعد العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص521، تحت «الاستعارة، والإشارة، وأثرهما في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-347","number":347,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"لماذا صوّر حالهم قبل الإسلام بأنهم ﴿على شفا حفرة من النار﴾؟","answer":"يصوّر حالهم قبل الإسلام واقفين على حافة هلاك لا يفصلهم عنه إلا خطوة، فتصير نعمة الإنقاذ مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص524، تحت «شفا وحرف».","url":""}]},{"id":"s3-348","number":348,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنقذكم منها﴾، دون أن يقال: فأبعدكم عنها؟","answer":"اختير ﴿فأنقذكم﴾ لأنهم كانوا مشرفين على السقوط في الهلاك، فالنعمة تخليص من مهلكة وشيكة، وهو أبلغ من مجرد الإبعاد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص524–527، تحت «(أنقذكم) و(خلّصكم) و(نجّاكم)».","url":""}]},{"id":"s3-350","number":350,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]},{"surah":22,"verses":[78]}],"verseLabel":"آل عمران: 103؛ الحج: 78","question":"ما الفرق بين ﴿واعتصموا بحبل الله جميعًا﴾ في آل عمران و﴿واعتصموا بالله﴾ في الحج؟","answer":"الاعتصام بالله لجوء مباشر إلى الحافظ والناصر وهو الأعم، أما الاعتصام بحبل الله فتصوير للوسيلة الجامعة من وحي وعهد وجماعة؛ فالأول يبرز الملجأ، والثاني يبرز سبب الوحدة الموصل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص392–393، تحت «الفرق بين الاعتصام بالله والاعتصام بحبل الله».","url":""}]},{"id":"s3-351","number":351,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتكن منكم أمة﴾، وهل المطلوب بعض الأمة أم جميعها؟","answer":"الأمر متوجه إلى الأمة، لكن مباشرة الدعوة والأمر والنهي فرض كفاية يقوم به المؤهلون؛ فإذا أداه بعضهم على الوجه المطلوب سقط الإثم عن الباقين، وإلا أثم القادرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص528–529، تحت «قوله تعالى: ﴿ولتكن منكم أمة يدعون﴾، و﴿ولتكن﴾ فيها وجهان».","url":""}]},{"id":"s3-352","number":352,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"لماذا قدّم الدعوة إلى الخير على الأمر بالمعروف والنهي عن المنكر؟","answer":"الدعوة إلى الخير أصل إيجابي جامع، ثم فُصلت حراسة المجتمع بإقامة المعروف ومنع المنكر؛ فانتقل من البناء العام إلى وظيفتيه العمليتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص529–530، تحت «عطف الخاص على العام، وحذف المفعول، والإشارة، والقصر، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-353","number":353,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"لماذا عرّف ﴿الخير﴾ و﴿المعروف﴾ و﴿المنكر﴾؟","answer":"عُرّفت الألفاظ للدلالة على المعاني المعلومة المقررة في ميزان الشرع: الخير الجامع، وما عُرف حسنه، وما عُرف إنكاره، لا على أفراد مبهمة يختارها الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص529–530، تحت «عطف الخاص على العام، وحذف المفعول، والإشارة، والقصر، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-354","number":354,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"لماذا حصر الفلاح في قوله ﴿وأولئك هم المفلحون﴾؟","answer":"اجتمع اسم الإشارة وضمير الفصل وتعريف ﴿المفلحون﴾ لقصر الفلاح الكامل على هذه الجماعة باعتبار قيامها بالدعوة والأمر والنهي، مع تعظيم شأنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص529–530، تحت «عطف الخاص على العام، وحذف المفعول، والإشارة، والقصر، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-355","number":355,"surah":3,"verses":[105],"references":[{"surah":3,"verses":[105]}],"verseLabel":"آل عمران: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكونوا كالذين تفرقوا واختلفوا﴾، وما الفرق بين التفرق والاختلاف؟","answer":"الاختلاف هنا اتخاذ كل فريق قولًا يناقض الآخر في أصول الحق، وهذا يفضي إلى تفرق الجماعة؛ فجمع بين فساد الاعتقاد ونتيجته الاجتماعية، وقدم التفرق لأنه العاقبة الظاهرة المحذر منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص533–534، تحت «النهي، والصلة، والتأكيد، والقصر، وأثرها جميعها في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-356","number":356,"surah":3,"verses":[105],"references":[{"surah":3,"verses":[105]}],"verseLabel":"آل عمران: 105","question":"ما دلالة البينات والدلائل في قوله تعالى: ﴿من بعد ما جاءهم البينات﴾؟","answer":"قُيد تفرقهم بما بعد مجيء البينات لأن الدلائل الواضحة كانت كفيلة بجمعهم على الحق؛ فاختلافهم بعدها عناد بعد قيام الحجة لا خطأ ناشئًا عن خفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص535، تحت «البينات والدلائل».","url":""}]},{"id":"s3-357","number":357,"surah":3,"verses":[105],"references":[{"surah":3,"verses":[105]}],"verseLabel":"آل عمران: 105","question":"لماذا وصف العذاب هنا بـ﴿عظيم﴾ لا ﴿أليم﴾ أو ﴿شديد﴾؟","answer":"وصف بالعظيم لتضخيم قدر العذاب وشموله، بما يناسب عظم الجناية: تفرقهم واختلافهم بعد قيام البينات؛ أما ﴿أليم﴾ فيركز الألم و﴿شديد﴾ القوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص556–557، تحت «(أليم) و(شديد) و(عظيم)».","url":""}]},{"id":"s3-358","number":358,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿يوم تبيض وجوه وتسود وجوه﴾، وما سر تحويل المعنى إلى لون الوجه؟","answer":"يظهر أثر المصير على أشرف ما يواجه به الإنسان، فيكون البياض علامة النعيم والسواد علامة الخزي؛ ويجوز أن يكونا حقيقيين مع دلالتهما على السرور والكآبة، وهو الأصل ما لم يصرفه دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص537–539، تحت «النشر، والاستفهام، والمجاز، وأثر ذلك في تجلية المعنى».","url":""}]},{"id":"s3-359","number":359,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"لماذا قدّم بياض الوجوه على سوادها؟","answer":"قدم البياض في الإجمال تشريفًا لأهل النعيم وإظهارًا لسبق الرحمة، ثم بدأ في التفصيل بأصحاب الوجوه السوداء لتعجيل توبيخهم، وختم بالمؤمنين ليكون الختام بالرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص537، تحت «النشر، والاستفهام، والمجاز، وأثر ذلك في تجلية المعنى».","url":""}]},{"id":"s3-360","number":360,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"لماذا نُكرت ﴿وجوه﴾ في الموضعين؟","answer":"يفيد التنكير كثرة الوجوه أو عموم الفريقين، ويحتمل تفريقًا مناسبًا للمصير: تعظيم الوجوه المبيضة وتحقير الوجوه المسودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص537، تحت «بلاغة تنكير ﴿وجوه﴾».","url":""}]},{"id":"s3-361","number":361,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير بقوله تعالى: لأصحاب الوجوه السوداء ﴿أكفرتم بعد إيمانكم﴾ في صورة سؤال؟","answer":"صيغ توبيخهم سؤالًا ليواجهوا فداحة انتقالهم من الإيمان إلى الكفر، فيجمع التعجيب من حالهم والتقريع عليها؛ ويجوز حمله على الاستفهام الإنكاري التوبيخي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص537–539، تحت «النشر، والاستفهام، والمجاز، وأثر ذلك في تجلية المعنى».","url":""}]},{"id":"s3-362","number":362,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿فذوقوا العذاب﴾، وهل العذاب يُذاق؟","answer":"الذوق إحساس مباشر لا واسطة فيه، فاستعير لمباشرة العذاب ومعاناته؛ وفي الأمر ﴿فَذُوقُوا﴾ توبيخ يربط الجزاء بالكفر بعد الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص539–542، تحت «الذوق والإحساس».","url":""}]},{"id":"s3-363","number":363,"surah":3,"verses":[107],"references":[{"surah":3,"verses":[107]}],"verseLabel":"آل عمران: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿ففي رحمة الله هم فيها خالدون﴾ فجعل الرحمة مكانًا؟","answer":"عبر عن الجنة برحمة الله لأنها أجلى آثار رحمته، وجعلهم «فيها» لتصوير إحاطة النعيم بهم واستقرارهم داخله خالدين، لا نيلهم أثرًا عابرًا من الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص542–543، تحت «تفصيل ما أُجمل، والصلة، وتقديم ما حقه التأخير، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-364","number":364,"surah":3,"verses":[107],"references":[{"surah":3,"verses":[107]}],"verseLabel":"آل عمران: 107","question":"لماذا كرر الضمير في ﴿هم فيها خالدون﴾؟","answer":"أبرز الضمير ﴿هم﴾ لتأكيد اختصاص هؤلاء بالخبر واستئناف بيان مصيرهم، ومع تقديم ﴿فيها﴾ يثبت أنهم فيها خالدون لا يظعنون ولا يموتون.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص543–545، تحت «الموقع البياني لقوله: ﴿هم فيها خالدون﴾».","url":""}]},{"id":"s3-365","number":365,"surah":3,"verses":[108],"references":[{"surah":3,"verses":[108]}],"verseLabel":"آل عمران: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك آيات الله نتلوها عليك بالحق﴾ بالإشارة إلى البعيد؟","answer":"أشير إليها بـ﴿تلك﴾ تعظيمًا لبعد منزلتها وعلو شأنها؛ فهي آيات الله المتضمنة الحكم الحق في مصير الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص545–546، تحت «الإشارة، ووجوه الإعراب، والتعريض، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-366","number":366,"surah":3,"verses":[108],"references":[{"surah":3,"verses":[108]}],"verseLabel":"آل عمران: 108","question":"لماذا نفى إرادة الظلم عن الله بقوله ﴿وما الله يريد ظلمًا للعالمين﴾؟","answer":"ذُيل خبر الجزاء بنفي إرادة أي ظلم أصلًا، ليقرر أن الثواب والعقاب حق وعدل؛ فنفي الإرادة أبلغ، والمضارع للاستمرار، والتنكير ينفي جنس الظلم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص546–547، تحت «الدلالات البلاغية في قوله: ﴿وما الله يريد ظلمًا للعالمين﴾».","url":""}]},{"id":"s3-367","number":367,"surah":3,"verses":[108],"references":[{"surah":3,"verses":[108]}],"verseLabel":"آل عمران: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿للعالمين﴾ لا: لأحد؟","answer":"قال ﴿للعالمين﴾ ليستغرق جميع الخلق؛ فلا تتعلق إرادته بظلم فرد منهم في أي وقت، وهو الغني المالك لهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص546–547، تحت «الدلالات البلاغية في قوله: ﴿وما الله يريد ظلمًا للعالمين﴾».","url":""}]},{"id":"s3-368","number":368,"surah":3,"verses":[109],"references":[{"surah":3,"verses":[109]}],"verseLabel":"آل عمران: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾ وكرر الموصول؟","answer":"كرر ﴿ما﴾ لتأكيد شمول الملك لكل من المجالين على الاجتماع والانفراد، ولا سيما الأرض التي قد يتوهم الناس بسبب تصرفهم فيها أنهم يملكون منها شيئًا استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص552–553، تحت «نكتة تكرير ﴿ما﴾».","url":""}]},{"id":"s3-370","number":370,"surah":3,"verses":[109],"references":[{"surah":3,"verses":[109]}],"verseLabel":"آل عمران: 109","question":"لماذا ختم بـ﴿وإلى الله ترجع الأمور﴾ ولم يقل: يرجع الناس؟","answer":"اختيرت ﴿الأمور﴾ لأنها أعم من الناس؛ فذوات الخلق وأحوالهم وشؤونهم ومصائرهم كلها تنتهي إلى الله، وفي ذلك تقرير لملكه وتعريض بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص555، تحت «دلالة (الـ) في ﴿الأمور﴾».","url":""}]},{"id":"s3-372","number":372,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿كنتم خير أمة﴾ بالماضي، دون أن يقال: أنتم خير أمة؟","answer":"الماضي يقرر الخيرية كحقيقة ثابتة في علم الله وكتبه، أو يذكّر بتحققها حين قامت الأمة بشروطها، لا أنه يمنحها امتيازًا بلا عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص558، تحت «دلالة (كان) بين النقصان والتمام».","url":""}]},{"id":"s3-373","number":373,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿أخرجت للناس﴾ بالبناء للمجهول؟","answer":"البناء للمجهول يصرف النظر إلى إخراجها الرباني للقيام برسالة، و﴿للناس﴾ يجعل خيريتها وظيفة نفع وهداية لا تفوقًا ذاتيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص559–560، تحت «سبب إيثار التعبير بصيغة المبني للمفعول».","url":""}]},{"id":"s3-374","number":374,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"لماذا قدّم الأمر بالمعروف والنهي عن المنكر على الإيمان بالله هنا؟","answer":"لأن الخيرية التي امتازت بها الأمة في علاقتها بالناس تظهر بهاتين الوظيفتين، ثم ذُكر الإيمان أصلًا يصححهما؛ وليس الترتيب ترتيب فضل مطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص563–564، تحت «سبب تقديم الأمر بالمعروف والنهي عن المنكر على الإيمان بالله».","url":""}]},{"id":"s3-375","number":375,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"لماذا عُلّقت خيرية الأمة بنفع ﴿الناس﴾ لا بنفسها؟","answer":"عُلّقت الخيرية بالناس لأن الأمة أُخرجت لنفعهم بدعوتهم وإقامة المعروف وكف المنكر؛ ففضلها وظيفة وهداية بقدر وفائها بهذه الأوصاف، لا تفوقًا ذاتيًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص560، تحت «دلالة كلمة ﴿أُخرجت﴾».","url":""}]},{"id":"s3-376","number":376,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو آمن أهل الكتاب لكان خيرًا لهم﴾ مع أن فيهم مؤمنين؟","answer":"الحكم موجه إلى جمهور أهل الكتاب الذين لم يؤمنوا الإيمان التام بمحمد ﷺ، ثم احتُرز بقوله ﴿منهم المؤمنون﴾ لئلا يعمم الذم؛ فوجود قلة مؤمنة لا يناقض توبيخ الجماعة الغالبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص565، تحت «فوائد التعبير بالشرط في قوله: ﴿ولو آمن أهل الكتاب﴾».","url":""}]},{"id":"s3-377","number":377,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"لماذا خُتمت الآية بـ﴿منهم المؤمنون وأكثرهم الفاسقون﴾؟","answer":"خُتمت بذلك إنصافًا للقلة المؤمنة ومنعًا لتعميم الذم، مع بيان أن الأكثرية فاسقة خارجة عن الطاعة، ولذلك لم يتحقق الإيمان الذي هو خير لهم في جماعتهم عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص567، تحت «قوله تعالى: ﴿منهم المؤمنون وأكثرهم الفاسقون﴾ بين الاحتراس والاستئناف البياني».","url":""}]},{"id":"s3-378","number":378,"surah":3,"verses":[111],"references":[{"surah":3,"verses":[111]}],"verseLabel":"آل عمران: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿لن يضروكم إلا أذى﴾، وكيف استثنى الأذى من الضرر؟","answer":"الأذى ضرر يسير لا يبلغ استئصال الدين أو الجماعة؛ فالاستثناء يطمئن المؤمنين مع عدم إنكار ما يصيبهم من قول أو مشقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص572–573، تحت «دلالة الاستثناء بين الاتصال والانقطاع».","url":""}]},{"id":"s3-379","number":379,"surah":3,"verses":[111],"references":[{"surah":3,"verses":[111]}],"verseLabel":"آل عمران: 111","question":"لماذا صوّر هزيمتهم بقوله ﴿يولوكم الأدبار﴾؟","answer":"لأن المهزوم يعرض عن خصمه ويوليه ظهره فارًا، فاختيرت الصورة الحركية لتجعل انكسارهم وهربهم مشاهدًا لا مجرد خبر عن الهزيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص574، تحت «نكتة التعبير بقوله: ﴿الأدبار﴾».","url":""}]},{"id":"s3-380","number":380,"surah":3,"verses":[111],"references":[{"surah":3,"verses":[111]}],"verseLabel":"آل عمران: 111","question":"ما مناسبة قوله تعالى بعد ذكر الإدبار: ﴿ثم لا ينصرون﴾؟","answer":"لأن تولية الأدبار قد تكون تحرفًا يعقبه كر أو نصر، فاحترس بنفي النصر، و﴿ثم﴾ ترتقي من هزيمتهم في القتال إلى خذلان أعم وأدوم ما دام المؤمنون قائمين بخيريتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص574–575، تحت «بلاغة الاحتراس في قوله: ﴿ثم لا ينصرون﴾».","url":""}]},{"id":"s3-381","number":381,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ضربت عليهم الذلة﴾، وكيف تُضرب الذلة؟","answer":"استعير الضرب لإلزام الذلة بهم وإحاطتها، كقبة أو خيمة تضرب فوق قوم فتغشاهم ولا تفارقهم؛ فليست ذلة عارضة بل حال ثابتة عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص578–579، تحت «بلاغة الاستعارة في قوله: ﴿ضربت عليهم الذلة﴾».","url":""}]},{"id":"s3-382","number":382,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿أين ما ثقفوا﴾، دون أن يقال: أينما وجدوا؟","answer":"﴿ثقفوا﴾ تفيد الظفر بهم والتمكن منهم، لا مجرد العثور المحايد؛ فهي أنسب بسياق الذلة والحماية التي لا تقوم إلا بعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص580، تحت «مناسبة التعبير بكلمة ﴿ثقفوا﴾».","url":""}]},{"id":"s3-383","number":383,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"لماذا استثنى ﴿إلا بحبل من الله وحبل من الناس﴾، وما صورة الحبلين؟","answer":"استثنيت حال أمنهم بعهد وذمة؛ فشبه العهد بالحبل الذي يتعلق به المهدد فيمنعه من السقوط: حبل من الله بشرعه وعهده، وحبل من الناس بأمانهم وحمايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص582، تحت «بلاغة الاستعارة في قوله: ﴿بحبل من الله وحبل من الناس﴾».","url":""}]},{"id":"s3-384","number":384,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"لماذا كرر لفظ ﴿حبل﴾ ولم يقل: بحبل من الله والناس؟","answer":"كرر ﴿حبل﴾ لأنهما سببان مستقلان لا حبل واحد مشترك النسبة: عهد من الله، وعهد من الناس؛ وفي التكرار توكيد أن الأمن لا يقوم إلا بأحدهما مع تقديم حبل الله لشرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص582، تحت «بلاغة الاستعارة في قوله: ﴿بحبل من الله وحبل من الناس﴾».","url":""}]},{"id":"s3-385","number":385,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿وباءوا بغضب من الله﴾، وكيف يرجع الإنسان بغضب؟","answer":"﴿باءوا﴾ أي رجعوا مستقرين فيما كسبوه، فكأن غضب الله منزل صار مآبهم الملازم جزاء أعمالهم، واللفظ يغلب في الرجوع بعاقبة الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص583، تحت «بلاغة الاستعارة التهكمية في قوله: ﴿وباءوا﴾».","url":""}]},{"id":"s3-386","number":386,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"لماذا عُطف ضرب المسكنة على ضرب الذلة؟","answer":"الذلة قهر ظاهر وفقد للعزة، والمسكنة فقر وانكسار باطن وحاجة؛ فجمع العقوبة في الحال الخارجية والنفسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص583–584، تحت «مناسبة الوصل في قوله: ﴿وضربت عليهم المسكنة﴾».","url":""}]},{"id":"s3-387","number":387,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"لماذا كرر ﴿ذلك بأنهم﴾ مرتين في تعليل حالهم؟","answer":"جاء التعليل الأول بالكفر وقتل الأنبياء سببًا للذلة والغضب والمسكنة، ثم كشف الثاني الجذر المتكرر لذلك: العصيان وتجاوز الحدود؛ فليس تكرارًا لفظيًا بل بيان لسلسلة الجريمة وسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص584–587، تحت «بلاغة الاستئناف البياني في قوله: ﴿ذلك بأنهم كانوا﴾».","url":""}]},{"id":"s3-388","number":388,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ويقتلون الأنبياء بغير حق﴾ مع أن قتل الأنبياء لا يكون بحق أصلًا؟","answer":"قُيد القتل بـ﴿بغير حق﴾ للتسجيل عليهم بأنه لم يستند إلى أدنى سبب أو شبهة، لا في الشرع ولا حتى في دعواهم؛ فالقيد للتشنيع وكشف العمد لا لاحتمال قتل نبي بحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص585، تحت «دلالة الحال في قوله: ﴿بغير حق﴾».","url":""}]},{"id":"s3-391","number":391,"surah":3,"verses":[113],"references":[{"surah":3,"verses":[113]}],"verseLabel":"آل عمران: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿ليسوا سواء﴾ بعد الأحكام على أهل الكتاب؟","answer":"جاء ﴿ليسوا سواء﴾ احتراسًا وإنصافًا بعد ذم الأكثرين؛ فليس أهل الكتاب في الكفر والفسق درجة واحدة، بل منهم أمة قائمة مؤمنة تتلو آيات الله وتعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص592–593، تحت «سر العدول عن (متساوين) إلى ﴿سواء﴾ في حيز النفي».","url":""}]},{"id":"s3-392","number":392,"surah":3,"verses":[113],"references":[{"surah":3,"verses":[113]}],"verseLabel":"آل عمران: 113","question":"لماذا وصف طائفة منهم بأنها ﴿أمة قائمة﴾؟","answer":"وصفت بالقائمة لأنها مستقيمة ثابتة على الحق، قائمة بأمر الله وعبادته، في مقابل من انحرف من أهل الكتاب؛ فالقيام هنا قيام دين وعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص595، تحت «بلاغة المجاز في قوله تعالى: ﴿أمة قائمة﴾».","url":""}]},{"id":"s3-394","number":394,"surah":3,"verses":[113],"references":[{"surah":3,"verses":[113]}],"verseLabel":"آل عمران: 113","question":"لماذا عطف السجود على تلاوة الآيات بجملة حالية؟","answer":"ليصور اجتماع العلم بالعبادة في الوقت نفسه: يتلون كتاب الله في حال خضوع وسجود، فلا تكون تلاوتهم معرفة مجردة بلا أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص596، تحت «نكتة مجيء ﴿وهم يسجدون﴾ حالًا بعد نعت التلاوة».","url":""}]},{"id":"s3-395","number":395,"surah":3,"verses":[114],"references":[{"surah":3,"verses":[114]}],"verseLabel":"آل عمران: 114","question":"لماذا أعيد الإيمان بالله واليوم الآخر بعد وصفهم بتلاوة الكتاب؟","answer":"لأن التلاوة وحدها قد تقع بلا تصديق أو عمل، فأثبت لهم الإيمان الذي يميز تلاوتهم من تلاوة المحرفين ويصلها بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص597، تحت «نكتة تقديم نعت التلاوة على نعت الإيمان بالله».","url":""}]},{"id":"s3-396","number":396,"surah":3,"verses":[114],"references":[{"surah":3,"verses":[114]}],"verseLabel":"آل عمران: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿ويسارعون في الخيرات﴾، دون أن يقال: إلى الخيرات؟","answer":"قيل ﴿في الخيرات﴾ لتصويرهم منغمسين داخل أعمال الخير يتسابقون في أنواعها، أما «إلى» فتدل على مجرد الاتجاه نحو الغاية قبل بلوغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص597–598، تحت «بلاغة الاستعارة في قوله: ﴿ويسارعون في الخيرات﴾».","url":""}]},{"id":"s3-397","number":397,"surah":3,"verses":[114],"references":[{"surah":3,"verses":[114]}],"verseLabel":"آل عمران: 114","question":"لماذا ختم بـ﴿وأولئك من الصالحين﴾ لا: هم الصالحون؟","answer":"قال ﴿من الصالحين﴾ لإدخالهم في جماعة الصالحين الممتدة من هذه الأمة وغيرها، إثباتًا لاستحقاقهم الوصف من غير حصر الصلاح فيهم وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص599–600، تحت «دلالة اسم الإشارة ﴿وأولئك﴾».","url":""}]},{"id":"s3-398","number":398,"surah":3,"verses":[115],"references":[{"surah":3,"verses":[115]}],"verseLabel":"آل عمران: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يفعلوا من خير فلن يكفروه﴾، وكيف يُكفر الخير؟","answer":"استعمل الكفر في أصل معنى الستر والجحود؛ أي لن يُستر خيرهم أو يُجحد، بل يحفظ لهم ويجازون عليه مهما كان، ولذلك عمم بـ﴿من خير﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص605، تحت «مجاز التعبير بـ﴿يكفروه﴾».","url":""}]},{"id":"s3-399","number":399,"surah":3,"verses":[115],"references":[{"surah":3,"verses":[115]}],"verseLabel":"آل عمران: 115","question":"لماذا بُني ﴿فلن يكفروه﴾ للمجهول؟","answer":"بني للمجهول لأن من لا يكفر الخير معلوم وهو الله، ولتتجه العناية إلى الخير نفسه وضمان حفظه وجزائه، لا إلى ذكر الفاعل الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص605–606، تحت «مناسبة التعبير بصيغة المبني للمفعول في ﴿يكفروه﴾».","url":""}]},{"id":"s3-400","number":400,"surah":3,"verses":[115],"references":[{"surah":3,"verses":[115]}],"verseLabel":"آل عمران: 115","question":"لماذا ختم بـ﴿والله عليم بالمتقين﴾ لا بالمحسنين؟","answer":"لأن قبول العمل مردّه إلى باعث التقوى الخفي الذي يشمل الإحسان المذكور وغيره؛ فختم بالوصف الأعم والأصل الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص607–610، تحت «حسن التذييل في قوله: ﴿والله عليم بالمتقين﴾».","url":""}]},{"id":"s3-401","number":401,"surah":3,"verses":[116],"references":[{"surah":3,"verses":[116]}],"verseLabel":"آل عمران: 116","question":"لماذا قدّم الأموال على الأولاد في نفي الإغناء؟","answer":"المال هو أول ما يُبذل عادة لدفع الضرر والفداء، ثم تأتي قوة الأولاد والنسب؛ فنفى القرآن أقرب وسيلتي الاعتماد عندهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص615، تحت «نكتة جمع الأولاد إلى الأموال، وسر تقديم الأموال على الأولاد».","url":""}]},{"id":"s3-402","number":402,"surah":3,"verses":[116],"references":[{"surah":3,"verses":[116]}],"verseLabel":"آل عمران: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تغني عنهم أموالهم ولا أولادهم من الله شيئًا﴾؟","answer":"ينفي التركيب نفيًا مؤكدًا أن تدفع الأموال أو الأولاد عنهم أي شيء من عذاب الله أو حكمه؛ فلا فداء بالمال ولا نصرة بالولد، ولو بأدنى قدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص611–612، تحت «بلاغة المجاز في قوله: ﴿لن تغني عنهم أموالهم ولا أولادهم﴾».","url":""}]},{"id":"s3-403","number":403,"surah":3,"verses":[116],"references":[{"surah":3,"verses":[116]}],"verseLabel":"آل عمران: 116","question":"ما دلالة الجملة المستقلة في قوله تعالى: ﴿وأولئك أصحاب النار هم فيها خالدون﴾؟","answer":"جيء بـ﴿هم﴾ لتوكيد الحكم وتقوية اختصاصهم به، ومع تقديم ﴿فيها﴾ يقرر أنهم ملازمو النار خالدون فيها لا يخرجون منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص618–619، تحت «نكتة ذكر المسند إليه ﴿هم﴾ في قوله: ﴿هم فيها خالدون﴾».","url":""}]},{"id":"s3-404","number":404,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"لماذا شُبّه إنفاق الكافرين بريح فيها صر أصابت حرثًا؟","answer":"لأن الإنفاق يبدو كحرث يرجى ثمره، لكن الكفر يسلط عليه بردًا مهلكًا فيذهب أصله وثمرته؛ فالصورة تجمع العمل والرجاء ثم الخيبة المفاجئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص624–626، تحت «بلاغة التشبيه التمثيلي في قوله: ﴿مثل ما ينفقون﴾».","url":""}]},{"id":"s3-405","number":405,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"لماذا اختيرت ﴿ريح﴾ مفردة لا ﴿رياح﴾؟","answer":"أفردت لأنها ريح عذاب واحدة متجهة بقوتها إلى الحرث فتهلكه، بخلاف الرياح المتفرقة التي يكثر ورودها في سياق الرحمة وتلقيح السحاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص636–640، تحت «الريح والرياح».","url":""}]},{"id":"s3-406","number":406,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿فيها صر﴾، دون أن يقال: باردة أو شديدة؟","answer":"﴿الصر﴾ برد شديد نافذ يحرق النبات وييبسه، وفي جرس اللفظ إيحاء بالصرير والعنف؛ فهو أبلغ من وصف الريح بأنها باردة أو شديدة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص629–630، تحت «دلالة ﴿صر﴾ في قوله: ﴿فيها صر﴾».","url":""}]},{"id":"s3-407","number":407,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿أصابت حرث قوم ظلموا أنفسهم﴾، وما أثر وصفهم بالظلم؟","answer":"وصفوا بظلم النفس ليظهر أن هلاك الحرث لم يقع اعتباطًا، بل وافق استحقاقهم، وليهيئ للمقابلة: ما ظلمهم الله ولكنهم هم الذين جلبوا الخسران لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص630–631، تحت «بلاغة الإدماج في قوله: ﴿قوم ظلموا أنفسهم﴾».","url":""}]},{"id":"s3-408","number":408,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿فأهلكته﴾ بعد أن صوّر الإصابة؟","answer":"عُقب الإصابة بالفاء لتصوير الإهلاك نتيجة سريعة مباشرة، ولفظ الإهلاك يدل على ذهاب الحرث وثمرته كلها، كما يحبط الكفر أثر النفقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص632، تحت «براعة الإطناب بالتتميم في قوله: ﴿فأهلكته﴾».","url":""}]},{"id":"s3-409","number":409,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"لماذا نفى ظلم الله ثم قال ﴿ولكن أنفسهم يظلمون﴾؟","answer":"نُفي الظلم عن الله لأن إحباط أعمالهم جزاء عادل، ثم استدرك بإثبات ظلمهم لأنفسهم؛ فهم الذين أفسدوا عملهم بالكفر وجلبوا عليها الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص632، تحت «دلالة حذف متعلق الظلم في قوله: ﴿ظلموا أنفسهم﴾».","url":""}]},{"id":"s3-410","number":410,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تتخذوا بطانة من دونكم﴾، وما صورة البطانة؟","answer":"شُبه القريب المطلع على السر ببطانة الثوب لملاصقتها باطنه وخفائها عن الناس؛ فالنهي عن إدخال من دون المؤمنين إلى موضع الثقة والسر الذي يكشف مواطن القوة والضعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص641–642، تحت «بلاغة الاستعارة في قوله: ﴿لا تتخذوا بطانة من دونكم﴾».","url":""}]},{"id":"s3-411","number":411,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يألونكم خبالًا﴾، دون أن يقال: لا يقصرون في إفسادكم؟","answer":"أي لا يدخرون وسعًا في إيقاع الخبال بكم؛ والخبال فساد واضطراب شامل للرأي والحال، فالتعبير يجمع استفراغ الجهد واتساع أثر الإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص645، تحت «وجه نصب ﴿خبالًا﴾ في قوله: ﴿لا يألونكم خبالًا﴾».","url":""}]},{"id":"s3-412","number":412,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ودوا ما عنتم﴾، فجعل مشقتهم أمنية؟","answer":"لم يقتصروا على إيقاع الخبال، بل استقرت محبتهم لكل مشقة تصيب المؤمنين؛ فالتعبير يكشف أن عنتكم غاية يتمنونها لا أثرًا عارضًا لأفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص646، تحت «دلالة الأفعال الماضية: ﴿ودوا﴾ و﴿عنتم﴾ و﴿بدت﴾».","url":""}]},{"id":"s3-413","number":413,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿قد بدت البغضاء من أفواههم﴾ لا من ألسنتهم؟","answer":"اختيرت الأفواه لأنها منفذ الكلام كله، فكأن البغضاء امتلأت بها حتى فاضت، وما بقي في الصدور أعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص649–651، تحت «أفواههم وألسنتهم».","url":""}]},{"id":"s3-414","number":414,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تخفي صدورهم أكبر﴾، دون أن يقال: قلوبهم؟","answer":"اختيرت الصدور لأنها الحيز الذي يضم القلوب وما تستكنه من أسرار، فكأن بغضاء عظيمة مخزونة فيها لا تفصح الأفواه إلا عن طرف منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص647–648، تحت «بلاغة المجاز المرسل في قوله: ﴿وما تخفي صدورهم أكبر﴾».","url":""}]},{"id":"s3-415","number":415,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"لماذا خُتمت الآية بـ﴿إن كنتم تعقلون﴾؟","answer":"لأن الآيات كشفت ظاهر عداوتهم وباطنها، فالعقل السليم يقتضي ألا يُتخذوا بطانة؛ والشرط يحث المؤمنين على إعمال العقل ويعرض بمن يخالف هذا البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص648، تحت «مناسبة الفاصلة ﴿تعقلون﴾ لمضمون الآية».","url":""}]},{"id":"s3-416","number":416,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"ما وجه البلاغة في الاكتفاء في قوله: ﴿ها أنتم أولاء تحبونهم ولا يحبونكم﴾؟","answer":"جيء بالتنبيه والإشارة كأن حالهم حاضرة تُرى: أنتم هؤلاء تحبون قومًا لا يبادلونكم الحب؛ وفيه تعجيب وتوبيخ يدعوان إلى مراجعة هذه الثقة غير المتكافئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص652، تحت «بلاغة الاكتفاء في قوله: ﴿ها أنتم أولاء تحبونهم ولا يحبونكم﴾».","url":""}]},{"id":"s3-417","number":417,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿وتؤمنون بالكتاب كله﴾ بالإفراد مع تعدد الكتب؟","answer":"أُفرد ﴿الْكِتَابِ﴾ والمراد جنس الكتب المنزلة؛ للدلالة على وحدة مصدرها وتوافق أصولها، فالمؤمنون يؤمنون بها كلها، بخلاف من يقبل بعض الوحي ويرد بعضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص652–653، تحت «بلاغة الاكتفاء في قوله: ﴿هاأنتم أولاء تحبونهم ولا يحبونكم وتؤمنون بالكتاب كله﴾».","url":""}]},{"id":"s3-418","number":418,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"ما سرّ قولهم عند اللقاء ﴿آمَنَّا﴾، ثم عضِّهم الأنامل إذا خلوا؟","answer":"يقولون ﴿آمنا﴾ في حضور المؤمنين مداراةً ونفاقًا، فإذا خلوا ظهر ما يكتمونه من شدة الغيظ؛ فالمقابلة تكشف انفصال ظاهرهم المصطنع عن باطنهم المعادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص653–655، تحت «بلاغة التورية في قوله: ﴿وإذا لقوكم قالوا آمنا﴾».","url":""}]},{"id":"s3-419","number":419,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿عضوا عليكم الأنامل من الغيظ﴾ لا الأصابع؟","answer":"خُصت الأنامل لأنها موضع العض من الأصابع، وصورة ضغط الأسنان على أطرافها تجسد غيظًا شديدًا مكظومًا لا يجد صاحبه سبيلًا إلى الإضرار بمن يغتاظ منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص655–656، تحت «براعة التمثيل في قوله: ﴿عضوا عليكم الأنامل من الغيظ﴾».","url":""}]},{"id":"s3-420","number":420,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"لماذا أُمر النبي أن يقول ﴿موتوا بغيظكم﴾؟","answer":"ليس أمرًا مقدورًا يراد امتثاله، بل تهديد وتبكيت: ابقوا في غيظكم حتى تموتوا به، فلن تنالوا ما تتمنونه للمؤمنين ولن يغير حقدكم وعد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص656، تحت «دلالة الأمر في قوله: ﴿موتوا بغيظكم﴾».","url":""}]},{"id":"s3-421","number":421,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"لماذا ختم بـ﴿إن الله عليم بذات الصدور﴾؟","answer":"السياق يكشف بغضًا يخفونه وراء الكلام، فناسبه العلم الملازم لما استقر في الصدور قبل أن يظهر على الألسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص658–659، تحت «بلاغة التذييل في قوله: ﴿إن الله عليم بذات الصدور﴾».","url":""}]},{"id":"s3-422","number":422,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تمسسكم حسنة تسؤهم﴾، فجعل الحسنة تمس؟","answer":"عبر بالمس لأن المس أدنى اتصال، فالمعنى أن أقل حسنة تصل إليكم وتلامس حالكم تكفي لإساءتهم؛ وهذا أبلغ في كشف شدة حسدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص662–663، تحت «دلالة الاستعارة في قوله: ﴿إن تمسسكم حسنة تسؤهم وإن تصبكم سيئة يفرحوا بها﴾».","url":""}]},{"id":"s3-423","number":423,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"لماذا قابل ﴿حسنة﴾ بـ﴿سيئة﴾ مع أن المراد نعمة ومصيبة؟","answer":"سميت النعمة حسنة لحسن أثرها، والمصيبة سيئة لسوء أثرها على من تنزل به؛ وبهذين اللفظين يعم التقابل كل ما يسر المؤمنين أو يسوؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص663، تحت «نكتة الاستعارة في التعبير بالحسنة والسيئة».","url":""}]},{"id":"s3-424","number":424,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى في الحسنة ﴿تسؤهم﴾ وفي السيئة ﴿يفرحوا بها﴾؟","answer":"نسبت الحسنة إلى سوء يقع في نفوسهم فورًا، أما السيئة فجعلت متعلق فرحهم تصريحًا؛ فاجتمع تألمهم بخير المؤمنين وابتهاجهم بشرهم، وهو أقصى انقلاب العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص663، تحت «دلالة المقابلة في قوله: ﴿إن تمسسكم حسنة تسؤهم وإن تصبكم سيئة يفرحوا بها﴾».","url":""}]},{"id":"s3-425","number":425,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"لماذا جُمع الصبر والتقوى في شرط بطلان كيدهم؟","answer":"الصبر يمنع الانهيار أمام الأذى، والتقوى تمنع مجاوزة الحق في الرد؛ وباجتماعهما تحفظ القوة من الضعف ومن الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص665، تحت «دلالة حذف متعلَّقَي الصبر والتقوى في قوله: ﴿وإن تصبروا وتتقوا﴾».","url":""}]},{"id":"s3-426","number":426,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يضركم كيدهم شيئًا﴾ فنكّر شيئًا؟","answer":"نكرت في سياق النفي لتعم؛ أي لا يصيبكم من كيدهم أي ضرر، ولو أقل شيء، مع تحقق شرط الصبر والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص664–665، تحت «دلالة نفي الضر دون نفي الأذى في قوله: ﴿لا يضركم كيدهم شيئًا﴾».","url":""}]},{"id":"s3-427","number":427,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"ما دلالة وصف الله تعالى بأنه ﴿بما يعملون محيط﴾ في ختام الآية؟","answer":"الإحاطة هنا كناية عن شمول علم الله وقدرته لأعمالهم وكيدهم، فلا يفوته منها ظاهر ولا خفي. وخاتمتها تطمئن المؤمنين أن ما أُمروا بالصبر والتقوى في مواجهته واقع تحت علم الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص665–666، تحت «دلالة قوله تعالى: ﴿بما يعملون محيط﴾».","url":""}]},{"id":"s3-428","number":428,"surah":3,"verses":[121],"references":[{"surah":3,"verses":[121]}],"verseLabel":"آل عمران: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ غدوت من أهلك﴾، دون أن يقال: خرجت؟","answer":"﴿غدوت﴾ لا تدل على مطلق الخروج، بل على الخروج في أول النهار؛ فترسم بدء الحدث من بيت النبي ﷺ باكرًا لتبوئة المؤمنين مواقع القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص506، تحت «الغدو والإصباح».","url":""}]},{"id":"s3-429","number":429,"surah":3,"verses":[121],"references":[{"surah":3,"verses":[121]}],"verseLabel":"آل عمران: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿تبوئ المؤمنين مقاعد للقتال﴾، وما صورة التبوئة والمقاعد؟","answer":"التبوئة تهيئة المكان وإنزال صاحبه فيه، والمقاعد هي المواقع التي يثبت فيها المقاتلون؛ فالصورة تجعل توزيع الصفوف كإسكان كل جماعة في موضعها المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص670–671، تحت «دلالة التعبير بالمقاعد دون المواقف في قوله: ﴿مقاعد للقتال﴾».","url":""}]},{"id":"s3-430","number":430,"surah":3,"verses":[121],"references":[{"surah":3,"verses":[121]}],"verseLabel":"آل عمران: 121","question":"لماذا ختمت الآية بـ﴿والله سميع عليم﴾؟","answer":"يسمع ما دار من المشاورة والأقوال عند الخروج، ويعلم النيات والتدبير؛ فخاتمتها إحاطة بما ظهر وما بطن في موقف أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص671، تحت «بلاغة التذييل في قوله: ﴿والله سميع عليم﴾».","url":""}]},{"id":"s3-431","number":431,"surah":3,"verses":[122],"references":[{"surah":3,"verses":[122]}],"verseLabel":"آل عمران: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ همت طائفتان منكم أن تفشلا﴾، دون أن يقال: عزمتا؟","answer":"اختير الهم لأنه ميل وقصد أولي إلى الفشل لم يستقر عزمًا ولا يتحول فعلًا؛ فأنقذتهما ولاية الله وثبتهما قبل أن تمضيا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص675–676، تحت «سر التعبير بالهم دون العزم».","url":""}]},{"id":"s3-433","number":433,"surah":3,"verses":[122],"references":[{"surah":3,"verses":[122]}],"verseLabel":"آل عمران: 122","question":"لماذا جاء بعد الهمّ بالفشل قوله ﴿والله وليهما﴾؟","answer":"عُقب الهم بالولاية لبيان أن الله تولاهما بالتثبيت فلم يتحول ميلهما العارض إلى فشل، وفي ذلك تطمين بأن الحفظ والنصر من مقتضى ولايته للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص677، تحت «دلالة الاعتراض بعد ذكر الصفة».","url":""}]},{"id":"s3-434","number":434,"surah":3,"verses":[122],"references":[{"surah":3,"verses":[122]},{"surah":9,"verses":[51]}],"verseLabel":"آل عمران: 122؛ التوبة: 51","question":"لماذا ختم بـ﴿وعلى الله فليتوكل المؤمنون﴾ بتقديم الجار والمجرور؟","answer":"في آل عمران: 122: قُدم ﴿على الله﴾ لقصر التوكل عليه؛ فمن كان الله وليه وجب أن يعتمد عليه وحده في الثبات والنصر، لا على العدد والعدة.\n\nفي التوبة: 51: تقديم ﴿على الله﴾ يفيد القصر: على الله وحده يعتمد المؤمنون، لا على عدة أو حذر مستقل عن مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص678، تحت «السر في تقديم الجار والمجرور».","url":""}]},{"id":"s3-435","number":435,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"ما دلالة الاستئناف بعد ذكر الأحداث الواقعة يوم أُحد في قوله تعالى: ﴿ولقد نصركم الله ببدر وأنتم أذلة﴾؟","answer":"ذُكر بدر شاهدًا واقعًا على ثمرة التوكل وولاية الله؛ فقد نصرهم مع ضعفهم، فكان تذكيرًا يمنع الفشل ويجدد الثقة بعد ما أصابهم في أُحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص682، تحت «دلالة الاستئناف بعد ذكر الأحداث الواقعة يوم أُحد».","url":""}]},{"id":"s3-436","number":436,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"لماذا وصف المؤمنين يوم بدر بـ﴿أذلة﴾ لا: قليلين؟","answer":"﴿أذلة﴾ تصف مجموع ضعفهم الظاهر يوم بدر: قلة العدد والسلاح والمال أمام عدو قوي، فهي أوسع من «قليلين» ولا تعني المهانة في الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص683–685، تحت «دلالة الكناية في التعبير عن الضعف بجمع القلة بلفظة ﴿أذلة﴾».","url":""}]},{"id":"s3-437","number":437,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"لماذا أُتبع النصر بالأمر ﴿فاتقوا الله لعلكم تشكرون﴾؟","answer":"لما كان النصر نعمة من الله أُمروا بتقواه ليلزموا طاعته ولا يغتروا بالأسباب، وبذلك يتحقق شكر النعمة قولًا وعملًا وتدوم آثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص686، تحت «نكتة التعبير بـ﴿لعلكم﴾ في مقام الشكر».","url":""}]},{"id":"s3-438","number":438,"surah":3,"verses":[124],"references":[{"surah":3,"verses":[124]}],"verseLabel":"آل عمران: 124","question":"ما دلالة عرض كفاية المدد في صورة السؤال: ﴿ألن يكفيكم﴾؟","answer":"التقرير يحملهم على الإقرار بأن مدد الله كافٍ، فينشأ الاطمئنان من جواب تستحضره نفوسهم لا من خبر يلقى عليهم فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص693، تحت «دلالة دخول همزة الاستفهام على أداة النفي».","url":""}]},{"id":"s3-439","number":439,"surah":3,"verses":[124],"references":[{"surah":3,"verses":[124]}],"verseLabel":"آل عمران: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يمدكم ربكم﴾، دون أن يقال: ينصركم؟","answer":"اختير الإمداد لأنه رفد القوة بملائكة يتتابعون إلى المؤمنين، وهو سبب للتثبيت والبشارة، أما النصر فهو الغلبة النهائية التي قررت الآيات أنها من عند الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص699، تحت «المدد والإمداد».","url":""}]},{"id":"s3-440","number":440,"surah":3,"verses":[124],"references":[{"surah":3,"verses":[124]}],"verseLabel":"آل عمران: 124","question":"لماذا كان الإمداد بـ﴿ثلاثة آلاف من الملائكة منزلين﴾؟","answer":"حُددت الثلاثة آلاف لتقوية البشرى ومقابلة ما خيف من زيادة العدو، ووصفوا بالمنزلين لبيان أن المدد يُنزل من عند الله إلى ساحة القتال تثبيتًا للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص695، تحت «نكتة وصف الملائكة بالتنزل».","url":""}]},{"id":"s3-441","number":441,"surah":3,"verses":[124],"references":[{"surah":3,"verses":[124]},{"surah":8,"verses":[9]}],"verseLabel":"آل عمران: 124؛ الأنفال: 9","question":"لماذا كان الإمداد في الأنفال بألف من الملائكة، وفي آل عمران بثلاثة آلاف ثم خمسة آلاف؟","answer":"آية الأنفال تحكي أصل الاستجابة يوم بدر فذكرت الألف ابتداءً، أما آل عمران فتستعيد الموقف لتثبيت المؤمنين بعد أحد وتعرض تدرج البشارة بحسب الصبر والتقوى وفور العدو؛ فالأعداد مراحل إمداد وبشارة لا تعارض بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص698، تحت «الحكمة من تدرج ذكر المدد بين سورتي الأنفال وآل عمران».","url":""}]},{"id":"s3-442","number":442,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"لماذا ارتفع العدد من ثلاثة آلاف إلى خمسة آلاف؟","answer":"البشارة الثانية معلقة بصبرهم وتقواهم ومجيء العدو من فوره، فزاد العدد مع اشتداد الظرف وثبات المؤمنين؛ وهو تدرج في التطمين لا اضطراب في الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص694، تحت «سر التكثير بذكر العدد مع جمع لفظة الملائكة».","url":""}]},{"id":"s3-443","number":443,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"لماذا عُلّق الإمداد بشرطي الصبر والتقوى؟","answer":"ليتعلق القلب بالطاعة لا بالعدد: الصبر ثبات أمام العدو، والتقوى حفظ لأمر الله؛ وهما سبب الأهلية للتأييد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص697، تحت «دلالة اقتران لفظ ﴿الفور﴾ وعطفه على ذكر الصبر والتقوى».","url":""}]},{"id":"s3-444","number":444,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"ما سرّ الكناية بالفور على العجلة في قوله تعالى: ﴿ويأتوكم من فورهم هذا﴾؟","answer":"أي يأتيكم العدو عاجلًا من ساعته بلا إمهال؛ واسم الإشارة يقرب هذا الفور ويستحضره، فتناسب زيادة المدد مباغتة الخطر وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص697، تحت «سر الكناية بالفور على العجلة».","url":""}]},{"id":"s3-445","number":445,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"لماذا وُصف الملائكة بـ﴿مسوّمين﴾؟","answer":"أي ذوي علامات ظاهرة تميزهم وتطمئن المؤمنين، أو مرسلين مسلطين في القتال بحسب القراءة؛ فاللفظ يصور مددًا منظمًا معروف السمة لا حضورًا مبهمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص698–699، تحت «سر الكناية عن الشدة بالتسويم».","url":""}]},{"id":"s3-446","number":446,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]}],"verseLabel":"آل عمران: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به﴾، مع أن النصر حاصل؟","answer":"قصر وظيفة المدد على البشارة والطمأنينة حتى لا تتعلق القلوب بالملائكة أو العدد؛ فالنصر في حقيقته من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص704–705، تحت «بلاغة القصر بالاستثناء في الإخبار عن البشرى وطمأنة القلوب».","url":""}]},{"id":"s3-447","number":447,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]}],"verseLabel":"آل عمران: 126","question":"لماذا نُسب الاطمئنان إلى القلوب؟","answer":"لأن القلب موطن الخوف والثبات والنية، والمقصود من المدد تسكين الاضطراب الباطن قبل أثره العسكري؛ أما النصر فمن عند الله لا من العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص704، تحت «بلاغة القصر بالاستثناء في الإخبار عن البشرى وطمأنة القلوب».","url":""}]},{"id":"s3-448","number":448,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]}],"verseLabel":"آل عمران: 126","question":"لماذا ختم بـ﴿العزيز الحكيم﴾؟","answer":"العزة تثبت نفاذ القدرة، والحكمة تثبت أن هذا النفاذ موضوع في موضعه بلا عبث ولا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص706، تحت «دلالة ختم التذييل بوصف العزة والحكمة للرب الجليل».","url":""}]},{"id":"s3-449","number":449,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]},{"surah":8,"verses":[10]}],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"لماذا زادت آل عمران ﴿بشرى لكم﴾، بينما قالت الأنفال ﴿إلا بشرى﴾؟","answer":"آل عمران تحكي بدرًا للمواساة بعد جرح أحد فخصت البشرى بالمؤمنين تصريحًا: ﴿لكم﴾؛ أما الأنفال فنزلت في قلب الحدث وكان كون البشرى لهم معلومًا من الخطاب، فاستغنى السياق عن المتعلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص706–708، تحت «بلاغة اختلاف النظم في المتشابه اللفظي بين سورتي آل عمران والأنفال».","url":""}]},{"id":"s3-450","number":450,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]},{"surah":8,"verses":[10]}],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"ما سرّ اختلاف الترتيب بين قوله تعالى في آل عمران ﴿ولتطمئن قلوبكم به﴾، وفي الأنفال ﴿ولتطمئن به قلوبكم﴾؟","answer":"في آل عمران: 126؛ الأنفال: 10: مقام آل عمران مقام جبر القلوب بعد أحد، فقدم القلوب لتكون موضع العناية والمواساة؛ أما الأنفال فالمقام مقام الإمداد في بدر، فقدم ﴿به﴾ لربط الطمأنينة بسبب البشرى والإمداد ولإفادة الاختصاص.\n\nفي الأنفال: 10: قُدّم ﴿به﴾ للعناية بسبب الطمأنينة، ولربطها بالمدد المذكور مع التأكيد أن أثره نفسي لا أنه مصدر النصر استقلالًا.\n\nفي الأنفال: 10: قُدّم ﴿به﴾ في الأنفال لقرب ذكر المدد والعناية بكونه سبب الطمأنينة، وأُخر في آل عمران لأن العناية هناك بطمأنينة القلوب المخاطبة عقب ﴿بشرى لكم﴾.","sources":[{"label":"[آل عمران: 126؛ الأنفال: 10] موسوعة التفسير البلاغي، ج5، ص707–708","url":""},{"label":"[الأنفال: 10] موسوعة التفسير البلاغي، ج15، ص634–636","url":""},{"label":"[الأنفال: 10] موسوعة التفسير البلاغي، ج5، ص706–707، تحت آل عمران 126","url":""}]},{"id":"s3-451","number":451,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]},{"surah":8,"verses":[10]}],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"لماذا ختمت آل عمران بـ﴿الله العزيز الحكيم﴾، وختمت الأنفال بـ﴿إن الله عزيز حكيم﴾؟","answer":"الأنفال نزلت وقت المواجهة والوعد لمّا يتحقق بعد، فناسبها توكيد العزة والحكمة بـ﴿إن﴾؛ أما آل عمران فتحكي نصرًا شوهد أثره، فتكفي الصفتان معرفتين بلا توكيد جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص708، تحت «تعريف الفاصلة وتنكيرها مع التوكيد في ﴿العزيز الحكيم﴾ و﴿إن الله عزيز حكيم﴾».","url":""}]},{"id":"s3-452","number":452,"surah":3,"verses":[127],"references":[{"surah":3,"verses":[127]}],"verseLabel":"آل عمران: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿ليقطع طرفًا من الذين كفروا﴾، وما صورة قطع الطرف؟","answer":"صوّر جماعة العدو جسمًا يُقطع طرف منه بالقتل والأسر، فيضعف باقيه؛ والتبعيض يطابق ما وقع من إصابة فريق لا استئصال الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص709، تحت «دلالة تخصيص قطع الطرف».","url":""}]},{"id":"s3-453","number":453,"surah":3,"verses":[127],"references":[{"surah":3,"verses":[127]}],"verseLabel":"آل عمران: 127","question":"لماذا عطف ﴿أو يكبتهم﴾ على قطع الطرف؟","answer":"عطف الكبت لأنه مآل آخر غير قطع الطرف: فقد يهلك الله طائفة منهم بالقتل، أو يصرعهم ويذلهم ويغيظهم ويردهم مهزومين؛ فـ﴿أو﴾ تفصل بين وجهي النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص709، تحت «دلالة تخصيص قطع الطرف».","url":""}]},{"id":"s3-454","number":454,"surah":3,"verses":[127],"references":[{"surah":3,"verses":[127]}],"verseLabel":"آل عمران: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿فينقلبوا خائبين﴾، فجعل رجوعهم انقلابًا؟","answer":"﴿ينقلبوا﴾ تصور رجوعهم القهقرى وقد تحولت حالهم من الطمع في الغلبة إلى الهزيمة، و﴿خائبين﴾ أي محرومين لم ينالوا ما طلبوا؛ فليس رجوعًا مكانيًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص711، تحت «سر التناسب بين ذكر الكبت والانقلاب بالخيبة».","url":""}]},{"id":"s3-455","number":455,"surah":3,"verses":[128],"references":[{"surah":3,"verses":[128]}],"verseLabel":"آل عمران: 128","question":"لماذا اعترض السياق بقوله ﴿ليس لك من الأمر شيء﴾ مخاطبًا النبي ﷺ؟","answer":"الاعتراض يردّ أمر الهداية والجزاء إلى الله، ويعلّم أن وظيفة الرسول البلاغ والجهاد لا التحكم في مصائر القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص715، تحت «بديع الالتفات بتوجيه الخطاب لرسول الله ﷺ وتخصيصه به».","url":""}]},{"id":"s3-456","number":456,"surah":3,"verses":[128],"references":[{"surah":3,"verses":[128]}],"verseLabel":"آل عمران: 128","question":"لماذا سوّى في الاحتمال بين ﴿يتوب عليهم﴾ و﴿يعذبهم﴾؟","answer":"ذُكرت التوبة والعذاب احتمالين لأن الحكم لله وحده لا لرغبة بشر: إن رجعوا وفقهم وقبل توبتهم، وإن أصروا عذبهم بظلمهم؛ وفي ذلك إبقاء لباب الهداية مع إثبات العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص716، تحت «سر إدراج ذكر التوبة والتعذيب في معرض ذكر علل النصر وغاياته».","url":""}]},{"id":"s3-457","number":457,"surah":3,"verses":[128],"references":[{"surah":3,"verses":[128]}],"verseLabel":"آل عمران: 128","question":"لماذا ختم بـ﴿فإنهم ظالمون﴾ لا: كافرون؟","answer":"وصفهم بالظلم لبيان سبب العذاب: فقد ظلموا أنفسهم بالكفر والعدوان ووضعوا الحق في غير موضعه؛ واللفظ أعم في تصوير الجناية، ولا يغلق باب التوبة الذي ذكر قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص716، تحت «سر إدراج ذكر التوبة والتعذيب في معرض ذكر علل النصر وغاياته».","url":""}]},{"id":"s3-458","number":458,"surah":3,"verses":[129],"references":[{"surah":3,"verses":[129]}],"verseLabel":"آل عمران: 129","question":"لماذا قدّم المغفرة على العذاب؟","answer":"لأن الآية جاءت بعد فتح باب التوبة والدعاء على الظالمين، فقدم ما يلائم سعة الرحمة وإمكان الرجوع، ثم ذكر العذاب عدلًا لمن أصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص724، تحت «دلالة التذييل بذكر وصفي المغفرة والرحمة وتأكيده».","url":""}]},{"id":"s3-459","number":459,"surah":3,"verses":[129],"references":[{"surah":3,"verses":[129]}],"verseLabel":"آل عمران: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿يغفر لمن يشاء ويعذب من يشاء﴾ ثم ختم بـ﴿غفور رحيم﴾ دون اسم يدل على العقاب؟","answer":"الخاتمة تفتح باب الرجاء، وتبين أن المغفرة أثر الرحمة لا مجرد إسقاط العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص724، تحت «دلالة التذييل بذكر وصف المغفرة والرحمة وتأكيده».","url":""}]},{"id":"s3-460","number":460,"surah":3,"verses":[130],"references":[{"surah":3,"verses":[130]}],"verseLabel":"آل عمران: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تأكلوا الربا﴾ مع أن التعامل به ليس أكلًا فقط؟","answer":"عبّر بالأكل عن أخذ مال الربا والانتفاع به لأن الأكل أشهر وجوه استهلاك المال وأظهر مقاصده؛ فالنهي يعم تملكه والتصرف فيه، لا المضغ الحسي وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص729، تحت «دلالة المجاز في التعبير بالأكل عن التعاطي».","url":""}]},{"id":"s3-461","number":461,"surah":3,"verses":[130],"references":[{"surah":3,"verses":[130]}],"verseLabel":"آل عمران: 130","question":"لماذا وصف الربا بـ﴿أضعافًا مضاعفة﴾؟","answer":"الوصف يصور ربا الجاهلية: إذا حل الدين زيد في المال مقابل التأجيل، فتتكرر الزيادة حتى يصير أضعافًا؛ وهو تشنيع لصورة الاستغلال الشائعة لا قيد يجيز الربا القليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص730، تحت «دلالة وصف الربا المنهي عنه في كونه أضعافًا مضاعفة».","url":""}]},{"id":"s3-462","number":462,"surah":3,"verses":[130,200],"references":[{"surah":3,"verses":[130,200]}],"verseLabel":"آل عمران: 130؛ آل عمران: 200","question":"لماذا خُتم النهي عن الربا وخُتمت السورة معًا بـ﴿واتقوا الله لعلكم تفلحون﴾؟","answer":"في آل عمران: 130: لما كان الربا يغري بربح عاجل، أمرهم بتقوى الله وترك ما حرم، وربط الفلاح الحقيقي بالطاعة لا بتكثير المال؛ فسلامة الدين والمآل هي الربح الباقي.\n\nفي آل عمران: 130؛ آل عمران: 200: في آية الربا تربط الخاتمة الفلاح بتقوى الطمع المالي، وفي آخر السورة تجمع التقوى الصبر والمصابرة والرباط؛ فتكرارها يجعل التقوى أصل الفلاح في مجاهدة المال وفي مجاهدة العدو والنفس.","sources":[{"label":"[آل عمران: 130] موسوعة التفسير البلاغي، ج5، ص726–738","url":""},{"label":"[آل عمران: 130؛ آل عمران: 200] موسوعة التفسير البلاغي، ج5، ص726–738؛ ج6، ص543–564","url":""}]},{"id":"s3-464","number":464,"surah":3,"verses":[131],"references":[{"surah":3,"verses":[131]}],"verseLabel":"آل عمران: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿واتقوا النار التي أعدت للكافرين﴾ للمؤمنين؟","answer":"حُذر المؤمنون من نار أعدت للكافرين كي لا يسلكوا سبيلهم في الربا والعصيان، وليشتد زجرهم عن المعصية؛ ولا يلزم من الوعيد أن كل من وقع في ذنب الربا صار كافرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص732–733، تحت «دلالة تعريف لفظة ﴿النار﴾ باللام والصلة».","url":""}]},{"id":"s3-465","number":465,"surah":3,"verses":[131],"references":[{"surah":3,"verses":[131]}],"verseLabel":"آل عمران: 131","question":"لماذا بُني ﴿أعدت﴾ للمجهول؟","answer":"حُذف الفاعل لأنه معلوم من العقيدة والسياق، ووجه الاهتمام إلى النار نفسها وإلى كونها قد أعدت وفرغ من إعدادها؛ فيشتد الإحساس بيقين الوعيد وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص733، تحت «سر بناء الفعل للمفعول في وصف النار».","url":""}]},{"id":"s3-466","number":466,"surah":3,"verses":[132],"references":[{"surah":3,"verses":[132]}],"verseLabel":"آل عمران: 132","question":"لماذا جمع بين طاعة الله وطاعة الرسول بعد النهي عن الربا؟","answer":"طاعة الله امتثال أصل التحريم، وطاعة الرسول قبول بيانه وتطبيقه؛ فسد الطريق على من يدعي الإيمان ثم يرد الحكم العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص733–734، تحت «فائدة عطف طاعة الرسول ﷺ على طاعة الله سبحانه وتعالى».","url":""}]},{"id":"s3-468","number":468,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿وسارعوا إلى مغفرة من ربكم وجنة﴾، وكيف يُسارَع إلى المغفرة؟","answer":"لا تكون المسارعة إلى المغفرة ذاتها حركة مكانية، بل إلى أسبابها من التوبة والطاعات؛ وصورت الأعمال سباقًا إلى غاية عظيمة لتحض على المبادرة والتنافس وعدم التسويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص738، تحت «سر التعبير بصيغة المفاعلة في ﴿وسارعوا﴾».","url":""}]},{"id":"s3-469","number":469,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"لماذا قدّم المغفرة على الجنة؟","answer":"المغفرة تزيل مانع الدخول أولًا، ثم تأتي الجنة غايةً بعد السلامة من الذنب؛ فرتب النظم التخلية قبل التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص741، تحت «نكتة تقديم المغفرة على الجنة»","url":""}]},{"id":"s3-470","number":470,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"لماذا وصف الجنة بأن عرضها السماوات والأرض ولم يذكر طولها؟","answer":"لأن العرض أقصر البعدين عادة؛ فإذا بلغ هذا الاتساع كان الطول أعظم، والمقصود تقريب سعة لا يحيط بها القياس البشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص741، تحت «براعة اصطفاء لفظ ﴿العرض﴾ وصفًا للجنة».","url":""}]},{"id":"s3-471","number":471,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿أعدت للمتقين﴾ في مقابل ﴿أعدت للكافرين﴾؟","answer":"قابل إعداد الجنة للمتقين بإعداد النار للكافرين لتمييز مآل الطريقين؛ وخص المتقين تشريفًا لأن صفاتهم الآتية جعلتهم أهل الجنة، كما أن مشابهة الكافرين تقرب صاحبها من نصيب وعيدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص743، تحت «بلاغة الفصل بالاستئناف في الفاصلة».","url":""}]},{"id":"s3-472","number":472,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]},{"surah":57,"verses":[21]}],"verseLabel":"آل عمران: 133؛ الحديد: 21","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿وسارعوا﴾، وقوله تعالى في الحديد ﴿سابقوا﴾؟","answer":"المسارعة تركز على مبادرة الإنسان إلى أسباب المغفرة عقب أوامر التقوى والإنفاق، أما المسابقة فتضيف وجود متنافسين وطلب السبق، وهو أنسب بسياق الحديد الذي يعالج التفاوت في الإيمان والإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص177–178، تحت «دلالة صيغة المفاعلة في قوله: ﴿سابقوا﴾».","url":""}]},{"id":"s3-473","number":473,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]},{"surah":57,"verses":[21]}],"verseLabel":"آل عمران: 133؛ الحديد: 21","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿جنة عرضها السماوات والأرض﴾، وفي الحديد ﴿جنة عرضها كعرض السماء والأرض﴾؟","answer":"آل عمران في مقام الحث المباشر فأثبتت السعة للجنة إبلاغًا في التعظيم، أما الحديد فجاءت بكاف التشبيه لتقريب ما لا يحيط به الحس إلى أوسع مشهود يعرفه المخاطب؛ والعبارتان تدلان على سعة خارجة عن القياس المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص192–193، تحت «بلاغة الاتفاق والاختلاف بين آية الحديد وآية آل عمران».","url":""}]},{"id":"s3-474","number":474,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"لماذا قدّم الإنفاق في السراء والضراء على كظم الغيظ والعفو؟","answer":"بدأ ببذل المال في الحالين لأنه علامة عملية ظاهرة للتقوى، ثم ارتقى إلى ضبط النفس والعفو وهما أشق باطنًا؛ فجمع الإحسان بالمال والإحسان إلى المسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص750–751، تحت «بلاغة الافتتاح بذكر الإنفاق».","url":""}]},{"id":"s3-475","number":475,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿الكاظمين الغيظ﴾، وما صورة كظم الغيظ؟","answer":"أصل الكظم ملء السقاء وشد فمه حتى لا يفيض؛ فصور الغيظ شيئًا ملأ النفس ثم حبسه صاحبه ومنع آثاره من الخروج، مع قدرته على الانتقام، وذلك أبلغ من مجرد عدم الغضب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص753، تحت «حسن اختيار لفظ الغيظ دون الغضب».","url":""}]},{"id":"s3-476","number":476,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"لماذا عطف ﴿العافين عن الناس﴾ على كظم الغيظ؟","answer":"كظم الغيظ يمنع فوران الغضب وآثاره، أما العفو فيترك مؤاخذة المسيء وعقوبته؛ فعطفه يرفع الخلق من ضبط النفس عن الانتقام إلى محو حق المؤاخذة والإحسان إلى الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص754، تحت «توجيه التعبير عن العفو باسم الفاعل».","url":""}]},{"id":"s3-477","number":477,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"لماذا ختم الصفات بـ﴿والله يحب المحسنين﴾ مع أن أولها في المتقين؟","answer":"بدأ بوصفهم المتقين لأن التقوى تؤهل للجنة، ثم سماهم محسنين لأن الإنفاق والكظم والعفو إتيان للأعمال على وجهها الحسن؛ فجمعت الآية ترك المنكر وفعل الخير وختمت بمحبة الله جزاء الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص754–755، تحت «علة الجمع بين صفتي التقوى والإحسان».","url":""}]},{"id":"s3-478","number":478,"surah":3,"verses":[135],"references":[{"surah":3,"verses":[135]}],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿فعلوا فاحشة أو ظلموا أنفسهم﴾، وما الفرق بينهما؟","answer":"الفاحشة ذنب عظيم بالغ القبح، أما ظلم النفس فأعم من كل معصية يؤاخذ بها الإنسان، وقيل هو ما دون الكبيرة؛ فعطف العام على الخاص ليشمل وقوع المتقين في الذنب على تفاوت درجاته ثم مبادرتهم للتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص761، تحت «الفرق بين الفاحشة وبين ظلم النفس».","url":""}]},{"id":"s3-479","number":479,"surah":3,"verses":[135],"references":[{"surah":3,"verses":[135]}],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ذكروا الله فاستغفروا لذنوبهم﴾، وما أثر الفاء؟","answer":"لما استحضروا جلال الله وحقه ووعيده عقب الذنب نشأ عن هذا الذكر الاستغفار مباشرة؛ فالفاء تفيد سرعة التعقيب، وتصور أن الذكر الصادق لا بد أن يثمر رجوعًا عاجلًا لا تسويفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص762، تحت «نكتة العطف بالفاء في قوله: ﴿فاستغفروا﴾».","url":""}]},{"id":"s3-480","number":480,"surah":3,"verses":[135],"references":[{"surah":3,"verses":[135]}],"verseLabel":"آل عمران: 135","question":"لماذا اعترض بقوله ﴿ومن يغفر الذنوب إلا الله﴾؟","answer":"الاعتراض استفهام إنكاري يقرر انفراد الله بالمغفرة: لا ملجأ للمذنب إلا إليه ولا ذنب يتعاظم على عفوه؛ فوسط وصف التائبين تطمين لهم وحث على ألا يمنعهم عظم الذنب من الاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص763، تحت «بلاغة إظهار لفظ الذنوب في موقع الإضمار».","url":""}]},{"id":"s3-481","number":481,"surah":3,"verses":[135],"references":[{"surah":3,"verses":[135]}],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ولم يصروا على ما فعلوا وهم يعلمون﴾؟","answer":"صفة المتقين ليست العصمة من الزلل، بل ألا يلازموا الذنب بعد تذكرهم وعلمهم بقبحه ونهي الله عنه؛ فـ﴿يصروا﴾ تصور الثبات المتعمد عليه، و﴿وهم يعلمون﴾ تكشف قيام الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص763، تحت «سر تأخير نفي الإصرار على الاستغفار».","url":""}]},{"id":"s3-482","number":482,"surah":3,"verses":[136],"references":[{"surah":3,"verses":[136]}],"verseLabel":"آل عمران: 136","question":"لماذا سميت المغفرة والجنات ﴿جزاءهم﴾؟","answer":"سميت المغفرة والجنات جزاءً لأنها الثمرة التي وعدها الله لمن اتصف بالإنفاق والكظم والعفو، وإذا أذنب بادر إلى الاستغفار ولم يصر؛ فوافق الثواب عملهم مع بقائه فضلًا وتكريمًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص764–765، تحت «شرح المفردات» في بيان ﴿جزاؤهم مغفرة من ربهم وجنات﴾.","url":""}]},{"id":"s3-483","number":483,"surah":3,"verses":[136],"references":[{"surah":3,"verses":[136]},{"surah":9,"verses":[89]},{"surah":14,"verses":[23]},{"surah":16,"verses":[31]},{"surah":18,"verses":[31]}],"verseLabel":"آل عمران: 136؛ التوبة: 89؛ إبراهيم: 23؛ النحل: 31؛ الكهف: 31","question":"ما سرّ التعبير بجريان الأنهار ﴿من تحتها﴾، وما دلالة العدول إلى ﴿من تحتهم﴾ في الكهف؟","answer":"في آل عمران: 136: ﴿من تحتها﴾ ترسم الأنهار جارية تحت أشجار الجنان وقصور أهلها، ملازمةً لمواضع نعيمهم وتحت تصرفهم؛ أما «فيها» فتثبت وجودها داخل الجنة دون هذه الصورة المكانية الدقيقة.\n\nفي التوبة: 89: التعبير بالجريان من تحتها يصور الأنهار دائمة الحركة قريبة من قصورها وأشجارها وتحت تصرف أهلها، وهو أبلغ من مجرد وجودها.\n\nفي إبراهيم: 23: تقديم الجار يصور الأنهار محيطة بأسفل الجنات ملازمة لها، فيكتمل مشهد النعيم.\n\nفي النحل: 31: تصور الماء ملازمًا لأصول الجنات، لا طارئًا يحتاج إلى جلب.\n\nفي الكهف: 31: أضيف ﴿تحت﴾ إلى ضمير أهل الجنة زيادة في تقرير ملكهم للجنات واستحقاقهم للبشارة؛ فاجتمعت مؤكدات الخبر لإتمام بشارتهم والتعريض بإغاظة المشركين.","sources":[{"label":"[آل عمران: 136] موسوعة التفسير البلاغي، ج5، ص764–769","url":""},{"label":"[التوبة: 89] موسوعة التفسير البلاغي، ج18، ص35–38","url":""},{"label":"[إبراهيم: 23] موسوعة التفسير البلاغي، ج24 ص773","url":""},{"label":"[النحل: 31] موسوعة التفسير البلاغي، ج26، ص322-334","url":""},{"label":"[الكهف: 31] ج29 ص759–761","url":""}]},{"id":"s3-484","number":484,"surah":3,"verses":[136],"references":[{"surah":3,"verses":[136]}],"verseLabel":"آل عمران: 136","question":"لماذا ختم بـ﴿ونعم أجر العاملين﴾؟","answer":"﴿نعم﴾ تمدح وتعظم ما سبق من المغفرة والجنات والخلود، وتسميه أجر العاملين لتربط الوعد بالعمل وتستنهض السامع إلى صفاتهم؛ فهو خير جزاء لمن لم يقف عند التمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص767، تحت «بلاغة اختيار لفظ الأجر للجزاء».","url":""}]},{"id":"s3-485","number":485,"surah":3,"verses":[137],"references":[{"surah":3,"verses":[137]}],"verseLabel":"آل عمران: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خلت من قبلكم سنن﴾، وكيف تخلو السنن؟","answer":"السنن قواعد ثابتة لا تفنى، وإنما خلت أي مضت قبلهم وقائعها وأممها التي جرت عليها؛ فنسب المضي إلى السنن مجازًا، تذكيرًا بتكرر سنة الله في ابتلاء المؤمنين ثم نصرهم وعاقبة المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص769–770، تحت «شرح المفردات».","url":""}]},{"id":"s3-486","number":486,"surah":3,"verses":[137],"references":[{"surah":3,"verses":[137]}],"verseLabel":"آل عمران: 137","question":"لماذا أُمروا بالسير في الأرض والنظر في عاقبة المكذبين؟","answer":"لينتقل خبر السنن من السماع إلى الشاهد التاريخي، فيروا أن تداول الأيام لا يبطل عاقبة التكذيب وأن هزيمة عابرة لا تعني خذلان الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص772، تحت «بلاغة المجاز المرسل في جملة السير في الأرض».","url":""}]},{"id":"s3-488","number":488,"surah":3,"verses":[138],"references":[{"surah":3,"verses":[138]}],"verseLabel":"آل عمران: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿هذا بيان للناس وهدى وموعظة للمتقين﴾، فجعل البيان للناس والهدى للمتقين؟","answer":"البيان عام للناس، أما الهدى والموعظة فخُص بهما المتقون لأنهم ينتفعون بهما ويستجيبون؛ فالهدى هنا دلالة توصل إلى الغاية، وهذا الأثر يتحقق في المتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص778، تحت عنوان «سر تخصيص المتقين بالهدى، والموعظة»","url":""}]},{"id":"s3-489","number":489,"surah":3,"verses":[138],"references":[{"surah":3,"verses":[138]}],"verseLabel":"آل عمران: 138","question":"لماذا عطف الهدى والموعظة على البيان؟","answer":"البيان يكشف الحقيقة للعقول كلها، والهدى يدل المستجيب إلى الطريق، والموعظة تحرك القلب للعمل؛ فليست الألفاظ مترادفة بل مراحل أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص778–781، تحت «البيان، والهدى، والموعظة».","url":""}]},{"id":"s3-490","number":490,"surah":3,"verses":[139],"references":[{"surah":3,"verses":[139]}],"verseLabel":"آل عمران: 139","question":"لماذا جمع بين النهي عن الوهن والحزن؟","answer":"نُهوا عن الوهن، وهو ضعف العزيمة والإرادة المؤدي إلى العجز، وعن الحزن، وهو شدة الأسف والانكسار؛ ليعالج أثر أُحد في قوتهم العملية والنفسية معًا، فيثبتوا ولا يستسلموا للهزيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص784، تحت «الحزن والهم والبث»","url":""}]},{"id":"s3-491","number":491,"surah":3,"verses":[139],"references":[{"surah":3,"verses":[139]}],"verseLabel":"آل عمران: 139","question":"ما وجه البلاغة في إيراد الفاصلة جملة شرط في قوله تعالى: ﴿وأنتم الأعلون إن كنتم مؤمنين﴾؟","answer":"قرر علوهم بالإيمان في الحجة والعاقبة والنصر ليزيل أثر الهزيمة، وعلق بـ﴿إن كنتم مؤمنين﴾ تهييجًا لهم أن يحققوا مقتضى إيمانهم بالثبات؛ فهو شرط حث لا شك في أصل إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص783، تحت «بلاغة إيراد الفاصلة جملة شرط».","url":""}]},{"id":"s3-492","number":492,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"ما وجه البلاغة في الاستعارة في التعبير بالمس في قوله تعالى: ﴿إن يمسسكم قرح فقد مس القوم قرح مثله﴾؟","answer":"ذكّرهم أن جرح أُحد لم ينفردوا به، فقد أصاب عدوهم مثله في بدر؛ والتعبير بالمس يصور القرح إصابة طارئة لا نهاية الطريق، فيسليهم ويمنع أن يتخذوا الجولة دليل خذلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص790، تحت «بلاغة الاستعارة في التعبير بالمس».","url":""}]},{"id":"s3-493","number":493,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وتلك الأيام نداولها بين الناس﴾، وكيف تُداوَل الأيام؟","answer":"صوّر الأيام دولاً تنتقل بين الفرق؛ ليبين أن الغلبة لا تثبت لأحد، وأن تداولها ميدان لتمييز الإيمان واتخاذ الشهداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص792، تحت «وجه المجاز في لفظ التداول».","url":""}]},{"id":"s3-494","number":494,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وليعلم الله الذين آمنوا﴾ مع أن الله يعلمهم قبل الامتحان؟","answer":"ليس المراد حدوث علم بعد جهل، فعلم الله سابق؛ بل أن يظهر في الواقع من يثبت إيمانه عند الامتحان، فيتميز للناس ويتعلق به الجزاء على عمل مشهود لا على مجرد الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص793، تحت «وجه إطلاق لفظ علم الله على المعلوم».","url":""}]},{"id":"s3-495","number":495,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿ويتخذ منكم شهداء﴾، دون أن يقال: ويجعل بعضكم شهداء؟","answer":"﴿يتخذ﴾ تفيد أن الله يصطفي من المؤمنين شهداء ويكرمهم بهذه المنزلة، لا مجرد أن تقع عليهم صفة الشهادة؛ و﴿منكم﴾ تبين أن هذا الاصطفاء يقع لبعض الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص794، تحت «علة اختيار لفظ الاتخاذ».","url":""}]},{"id":"s3-496","number":496,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"لماذا خُتمت الآية بـ﴿والله لا يحب الظالمين﴾؟","answer":"لما ذكر تداول الأيام وقد يغلب الظالمون في جولة، نفى أن تكون إدالتهم دليل محبة أو رضا؛ إنما هي لحكمة الابتلاء، والله لا يحب ظلمهم ولن يجعل العاقبة الدائمة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص794، تحت «وجه نفي المحبة بالمضارع المنفي».","url":""}]},{"id":"s3-497","number":497,"surah":3,"verses":[141],"references":[{"surah":3,"verses":[141]}],"verseLabel":"آل عمران: 141","question":"ما وجه البلاغة في الاستعارة في قوله: ﴿وليمحص الله﴾، ﴿ويمحق الكافرين﴾؟","answer":"التمحيص تنقية الشيء من شوائبه، كتنقية الذهب بالنار، فناسب المؤمنين إذ تطهرهم المحنة؛ والمحق إنقاص الشيء حتى يذهب، فناسب الكافرين. وتقارب اللفظين يشدد مقابلة التطهير بالإهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص13–14، تحت «بلاغة الاستعارة في قوله: ﴿وليمحص الله﴾، ﴿ويمحق الكافرين﴾».","url":""}]},{"id":"s3-498","number":498,"surah":3,"verses":[142],"references":[{"surah":3,"verses":[142]}],"verseLabel":"آل عمران: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿أم حسبتم أن تدخلوا الجنة﴾ في صورة سؤال؟","answer":"جاء استفهامًا إنكاريًا ليبطل ظن أن الجنة تنال بالدعوى والتمني قبل اختبار الجهاد والصبر؛ وصيغة السؤال تجعل السامع يراجع حسبانه ويقر بأن الثمن عمل وثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص19، تحت «دلالة التعبير بـ(أم) في قوله تعالى: ﴿أم حسبتم﴾».","url":""}]},{"id":"s3-499","number":499,"surah":3,"verses":[142],"references":[{"surah":3,"verses":[142]}],"verseLabel":"آل عمران: 142","question":"ما النكتة البلاغية في التعبير بـ(لما) في قوله تعالى: ﴿ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين﴾؟","answer":"أي لم يظهر بعد في واقع الامتحان جهاد المجاهدين وصبر الصابرين ظهورًا يتعلق به الجزاء، مع توقع حصوله؛ فـ﴿لما﴾ تنفي الوقوع إلى الآن لا علم الله السابق، وتقرر أن الجنة لا تنال قبل تحقق العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص20، تحت «نكتة التعبير بـ(لما)».","url":""}]},{"id":"s3-500","number":500,"surah":3,"verses":[142],"references":[{"surah":3,"verses":[142]}],"verseLabel":"آل عمران: 142","question":"لماذا غُيّرت الصياغة من ﴿الذين جاهدوا﴾ إلى ﴿الصابرين﴾؟","answer":"﴿الذين جاهدوا﴾ تبرز وقوع فعل الجهاد منهم في ميدان الامتحان، أما ﴿الصابرين﴾ فاسم فاعل يصور الصبر صفة ثابتة راسخة؛ لأن الجهاد موقف، والصبر خُلُق ملازم يحتاجه في الموقف وبعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص21، تحت «مناسبة المخالفة في التعبير في قوله ﴿جاهدوا﴾ و﴿الصابرين﴾».","url":""}]},{"id":"s3-501","number":501,"surah":3,"verses":[143],"references":[{"surah":3,"verses":[143]}],"verseLabel":"آل عمران: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد كنتم تمنون الموت﴾ لا: الشهادة؟","answer":"كانوا يتمنون لقاء العدو طلبًا لما يفضي إليه من الشهادة، فعبّر بالموت لأنه الحقيقة الشديدة التي عاينوها ولأن مجرد التمني لا يثبت لصاحبه منزلة الشهيد؛ فواجههم بلازم الأمنية حين حضر الخطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص28، تحت «دلالة التمني في قوله تعالى: ﴿ولقد كنتم تمنون الموت﴾».","url":""}]},{"id":"s3-502","number":502,"surah":3,"verses":[143],"references":[{"surah":3,"verses":[143]}],"verseLabel":"آل عمران: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد رأيتموه وأنتم تنظرون﴾، وما الفرق بين الرؤية والنظر؟","answer":"النظر أول توجيه العين إلى المشهد وتأمله، والرؤية إدراك صورته والنفاذ إلى حقيقته؛ فقد عاينوا الموت في القتلى أمامهم وأدركوا رهبة حقيقته، فجمع اللفظان المشاهدة بالبصر والاعتبار بالبصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص31، تحت «النظر والرؤية».","url":""}]},{"id":"s3-503","number":503,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿وما محمد إلا رسول﴾ بالقصر؟","answer":"القصر يقرر أنه رسول بشر أدى البلاغ، لا أن الرسالة متوقفة على خلوده؛ فموته أو قتله لا يسوغ ترك الدين. وجاء باسم الرسالة لأنها المهمة الباقية التي يجب اتباعها بعد غياب حاملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص36، تحت «سر التعبير بأسلوب القصر في قوله تعالى: ﴿وما محمد إلا رسول﴾».","url":""}]},{"id":"s3-504","number":504,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خلت من قبله الرسل﴾، دون أن يقال: الأنبياء؟","answer":"اختير ﴿الرسل﴾ لأن المقام في بقاء البلاغ والدين بعد وفاة المبلّغ؛ فمحمد ﷺ واحد من رسل مضوا بعد أداء رسالاتهم، ولم تبطل رسالاتهم بموتهم. أما «الأنبياء» فلا يبرز وظيفة البلاغ بهذا الوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص37، تحت «مناسبة مجيء قوله تعالى: ﴿قد خلت من قبله الرسل﴾».","url":""}]},{"id":"s3-505","number":505,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"لماذا قدّم ﴿مات﴾ على ﴿قتل﴾ في ﴿أفإن مات أو قتل﴾؟","answer":"قدم الموت لأنه المصير المشترك الذي خلت به الرسل، مع أن إشاعة القتل هي التي أثارت الفتنة يوم أُحد؛ وفي التقديم إشعار بأن النبي ﷺ سيموت موتًا لا قتلًا، والحكمان سواء في عدم جواز الانقلاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص38، تحت «سر تقديم الموت على القتل في قوله تعالى: ﴿مات أو قتل﴾».","url":""}]},{"id":"s3-506","number":506,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"لماذا صوّر الارتداد بقوله ﴿انقلبتم على أعقابكم﴾؟","answer":"صوّر الردة رجوعًا جسديًا إلى الخلف بعد التقدم في الطريق؛ فتبدو خسارة من يربط الدين بحياة شخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص44–45، تحت «الانقلاب، والارتداد، والرجوع، والعود».","url":""}]},{"id":"s3-507","number":507,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"لماذا كرر فعل الانقلاب في ﴿ومن ينقلب على عقبيه فلن يضر الله شيئًا﴾؟","answer":"ذُكر الانقلاب أولًا في سؤال يوبخ الجماعة على ربط الدين بحياة الرسول، ثم أعيد في شرط عام يشمل كل فرد ويبين عاقبته: من يرتد لا ينقص ملك الله ولا دينه شيئًا، وإنما يخسر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص39–40، تحت «براعة التعبير في قوله: ﴿ومن ينقلب على عقبيه فلن يضر الله شيئًا﴾».","url":""}]},{"id":"s3-508","number":508,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"لماذا ختم بـ﴿وسيجزي الله الشاكرين﴾ لا الصابرين أو الثابتين؟","answer":"الثابت بعد موت الرسول يشكر الله على نعمة الإسلام باتباع الرسالة وعدم ربطها بشخص المبلّغ؛ لذلك قابل المنقلبين بالشاكرين، فالشكر هنا ثبات وطاعة وحفظ للنعمة لا مجرد قول باللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص40، تحت «حسن التذييل في قوله تعالى: ﴿وسيجزي الله الشاكرين﴾».","url":""}]},{"id":"s3-509","number":509,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"ما وجه البلاغة في أسلوب القصر بقوله: ﴿وما كان لنفس أن تموت إلا بإذن الله﴾؟","answer":"نفت الآية أن تموت أي نفس بسبب مستقل عن مشيئة الله ووقتها المقدر؛ لتثبت الفارين أن الإقدام لا يقدم الأجل والفرار لا يؤخره، فالحياة والموت بيد الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص52، تحت «بلاغة أسلوب القصر بقوله: ﴿وما كان لنفس أن تموت إلا بإذن الله﴾».","url":""}]},{"id":"s3-510","number":510,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"لماذا سمّى أجل الموت ﴿كتابًا مؤجلًا﴾؟","answer":"سمي الأجل كتابًا لأنه قدر مثبت مكتوب، ووصف بالمؤجل لأن لكل نفس وقتًا معينًا ينتهي إليه عمرها؛ فالصورة تمنح الأجل معنى الثبوت والانضباط الذي لا تغيره أسباب الخوف والقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص54، تحت «دلالة التعبير في قوله تعالى: ﴿كتابًا مؤجلًا﴾».","url":""}]},{"id":"s3-511","number":511,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"لماذا كرر ﴿نؤته منها﴾ في ثواب الدنيا وثواب الآخرة؟","answer":"أعيد ﴿نؤته منها﴾ ليستقل كل قصد بجزائه: من حصر إرادته في الدنيا أعطي نصيبًا منها، ومن أراد الآخرة أعطي من ثوابها؛ فالتكرار يبرز اختلاف الغايتين والمآلين لا مجرد وقوع العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص54، تحت «مناسبة التعبير في قوله تعالى: ﴿ومن يرد ثواب الدنيا نؤته منها ومن يرد ثواب الآخرة نؤته منها﴾».","url":""}]},{"id":"s3-512","number":512,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"لماذا خُتمت الآية مرة أخرى بـ﴿وسنجزي الشاكرين﴾؟","answer":"أعيد وعد الشاكرين ليثبت أن أصحاب القصد الأعلى هم الذين عرفوا نعمة الله فاستعملوها في طاعته ولم يبيعوا الدين بعاجل الدنيا؛ والتكرار يصل ثباتهم عند موت الرسول بحسن اختيارهم للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص55، تحت «حسن التذييل في قوله: ﴿وسنجزي الشاكرين﴾».","url":""}]},{"id":"s3-513","number":513,"surah":3,"verses":[146],"references":[{"surah":3,"verses":[146]}],"verseLabel":"آل عمران: 146","question":"ما دلالة التعبير بلفظ ﴿كأين﴾ في قوله تعالى: ﴿وكأين من نبي﴾؟","answer":"﴿كأين﴾ تفيد كثرة الوقائع: كم من نبي قاتل معه جماعات كثيرة من الربانيين فلم تكسرهم المصائب؛ فليست سابقة أُحد بدعًا، بل نموذجًا تقابله سوابق كثيرة تدعو أمة محمد إلى الاقتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص62، تحت «دلالة التعبير بلفظ ﴿كأين﴾ في قوله تعالى: ﴿وكأين من نبي﴾».","url":""}]},{"id":"s3-514","number":514,"surah":3,"verses":[146],"references":[{"surah":3,"verses":[146]}],"verseLabel":"آل عمران: 146","question":"لماذا جمع بين ﴿فما وهنوا﴾ و﴿وما ضعفوا﴾ و﴿وما استكانوا﴾؟","answer":"نفى فتور العزم، ثم ضعف القدرة، ثم الخضوع للعدو؛ فاستوعب مراحل الانكسار النفسية والعملية والظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص69، تحت «الضعف والاستكانة والوهن».","url":""}]},{"id":"s3-515","number":515,"surah":3,"verses":[146],"references":[{"surah":3,"verses":[146]}],"verseLabel":"آل عمران: 146","question":"لماذا ختم بـ﴿والله يحب الصابرين﴾؟","answer":"لأن عدم الوهن والضعف والاستكانة هو صورة الصبر عند الشدة، فسمّاهم صابرين وختم بمحبة الله لهم؛ لينقل الثبات من مجرد احتمال الألم إلى منزلة ينال بها العبد محبة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص68، تحت «في جملة التذييل فوائد لغوية وبلاغية في قوله تعالى: ﴿والله يحب الصابرين﴾».","url":""}]},{"id":"s3-516","number":516,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"لماذا حُصر قولهم في الدعاء ﴿وما كان قولهم إلا أن قالوا﴾؟","answer":"بالنفي والاستثناء حصر قول الربانيين عند الشدة في الدعاء، فلم يتكلموا بجزع أو اعتراض أو استسلام؛ فكان أول ردهم محاسبة النفس وطلب العون من الله، لا لوم القدر أو التراجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص75، تحت «مناسبة مجيء القصر بطريق النفي والاستثناء».","url":""}]},{"id":"s3-517","number":517,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"لماذا بدأوا بطلب مغفرة الذنوب قبل طلب تثبيت الأقدام والنصر؟","answer":"رأوا الذنب سببًا يحجب التأييد، فبدؤوا بإصلاح الصلة بالله، ثم سألوا الثبات، ثم ثمرة الثبات وهي النصر؛ فرتبوا الدعاء من الداخل إلى الخارج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص76، تحت «مناسبة الترتيب في الدعاء».","url":""}]},{"id":"s3-518","number":518,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"ما دلالة عطف ﴿وإسرافنا في أمرنا﴾ على ﴿ذنوبنا﴾ في دعائهم؟","answer":"طلبوا مغفرة الذنوب عامة، ثم خصوا الإسراف، وهو مجاوزة الحد والتفريط في الأمر، لعظم أثره في أسباب الهزيمة؛ فجمعوا بين تقصيرهم كله وبين ما تجاوزوا فيه حدود الصواب خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص76، تحت «نكتة عطف الخاص على العام».","url":""}]},{"id":"s3-519","number":519,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"لماذا صوّر الثبات بقوله ﴿وثبت أقدامنا﴾؟","answer":"ثبات الأقدام كناية عن ثبات القلوب والصفوف عند لقاء العدو؛ فمن اضطرب باطنه زلت قدمه وفر، ومن رسخ يقينه ثبت مكانه، فصورت القوة المعنوية في هيئة جسدية مشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص77، تحت «دلالة ﴿وثبت أقدامنا﴾ بين أن يكون مجازًا مرسلًا بغرض الكناية وأن يكون استعارة».","url":""}]},{"id":"s3-520","number":520,"surah":3,"verses":[148],"references":[{"surah":3,"verses":[148]}],"verseLabel":"آل عمران: 148","question":"ما دلالة الفاء في قوله تعالى: ﴿فآتاهم الله ثواب الدنيا وحسن ثواب الآخرة﴾؟","answer":"تدل الفاء على أن إعطاءهم ثواب الدارين مترتب على دعائهم وصبرهم وإخلاصهم لله، وفي دلالتها على التعقيب إشعار بتعجيل قبول دعائهم والاستجابة لطلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص83، تحت عنوان «دلالة الفاء في قوله: ﴿فآتاهم الله ثواب الدنيا﴾»","url":""}]},{"id":"s3-778","number":778,"surah":3,"verses":[148],"references":[{"surah":3,"verses":[148]}],"verseLabel":"آل عمران: 148","question":"ما المراد بثواب الدنيا وثواب الآخرة في جزاء الثابتين مع أنبيائهم؟","answer":"يدل سياق الثبات في القتال على أن ثواب الدنيا هو النصر والغنيمة والعز وطيب الذكر، وأن ثواب الآخرة هو الجنة والنعيم الدائم؛ فالسياق يبين نوع الجزاء في كل دار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص84، تحت عنوان «دلالة قوله تعالى: ﴿ثواب الدنيا﴾ و﴿حسن ثواب﴾»","url":""}]},{"id":"s3-521","number":521,"surah":3,"verses":[148],"references":[{"surah":3,"verses":[148]}],"verseLabel":"آل عمران: 148","question":"لماذا وصف ثواب الآخرة وحده بـ﴿حسن﴾؟","answer":"خص ثواب الآخرة بالحسن لأنه كامل باق لا يشوبه ألم ولا يعقبه زوال، أما ثواب الدنيا فعلى جلاله محدود وقد تخالطه المنغصات؛ فالتقييد يقرر تفاضل الجزاءين لا نفي الخير عن الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص84، تحت «نكتة وصف ثواب الآخرة بالحسن وتركه في وصف الدنيا».","url":""}]},{"id":"s3-522","number":522,"surah":3,"verses":[148],"references":[{"surah":3,"verses":[148]}],"verseLabel":"آل عمران: 148","question":"لماذا ختم بـ﴿والله يحب المحسنين﴾ بعد وصف الصابرين؟","answer":"وصفوا أولًا بالصابرين لثباتهم عند المصاب، ثم بالمحسنين لأنهم أحسنوا الصلة بالله والدعاء والجهاد؛ فالإحسان أوسع من الصبر، وختم بالمحبة بعد ذكر الثواب ليضيف رضا الله إلى الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص85، تحت «حسن التذييل في قوله تعالى: ﴿والله يحب المحسنين﴾».","url":""}]},{"id":"s3-523","number":523,"surah":3,"verses":[149],"references":[{"surah":3,"verses":[149]}],"verseLabel":"آل عمران: 149","question":"لماذا كرر النداء ﴿يا أيها الذين آمنوا﴾ قبل التحذير من طاعة الكافرين؟","answer":"جدد النداء لاستنفار الانتباه إلى خطر الطاعة العقدية، وناداهم بوصف الإيمان لأن مقتضاه ألا يسلموا قيادهم للكافرين الذين يردونهم عنه؛ فالصفة نفسها حجة التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص90، تحت «نكتة التعبير بالاسم الموصول وصلته في قوله: ﴿الذين آمنوا﴾».","url":""}]},{"id":"s3-524","number":524,"surah":3,"verses":[149],"references":[{"surah":3,"verses":[149]}],"verseLabel":"آل عمران: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿يردوكم على أعقابكم﴾ لا: عن دينكم؟","answer":"صوّر طاعتهم رجوعًا على الأعقاب: بعد أن تقدم المؤمن في طريق الهدى يدير ظهره ويرجع القهقرى إلى الكفر؛ فالتعبير يجسد قبح النكوص وخسارة المسافة التي قطعها، لا مجرد ترك مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص92، تحت «بلاغة قوله تعالى: ﴿يردوكم على أعقابكم﴾».","url":""}]},{"id":"s3-525","number":525,"surah":3,"verses":[149],"references":[{"surah":3,"verses":[149]}],"verseLabel":"آل عمران: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿فتنقلبوا خاسرين﴾ فجاء بالفاء؟","answer":"الفاء تفيد أن الخسران نتيجة مباشرة لطاعة الكافرين وما تسببه من الردة؛ و﴿تنقلبوا﴾ تصور تحولهم من عز الإيمان وربحه إلى حال الخاسرين، فلا فاصل بين النكوص وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص94، تحت «دلالة قوله: ﴿فتنقلبوا خاسرين﴾».","url":""}]},{"id":"s3-526","number":526,"surah":3,"verses":[150],"references":[{"surah":3,"verses":[150]}],"verseLabel":"آل عمران: 150","question":"لماذا أضرب عن طاعة الكافرين بقوله ﴿بل الله مولاكم﴾؟","answer":"أضربت ﴿بل﴾ عن طاعة الكافرين والاحتماء بهم، وأثبتت البديل الحاسم: الله هو وليكم المتكفل بأمركم ونصركم؛ فمن كانت له ولايته لم يطلب العزة عند أعدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص96، تحت «دلالة ﴿بل﴾ بين الإضراب الانتقالي والإبطالي».","url":""}]},{"id":"s3-527","number":527,"surah":3,"verses":[150],"references":[{"surah":3,"verses":[150]}],"verseLabel":"آل عمران: 150","question":"لماذا أفرد الولاية لله ثم قال ﴿وهو خير الناصرين﴾ بالجمع؟","answer":"أفرد الله بالولاية لأنه المتولي الحقيقي المستقل، ثم قال ﴿خير الناصرين﴾ فجمع جنس الناصرين باعتبار ما يجري من نصر على أيدي الملائكة والمؤمنين والأسباب؛ لكن نصرهم تابع ونصر الله أصل وخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص98، تحت «دلالة العطف في قوله: ﴿وهو خير الناصرين﴾».","url":""}]},{"id":"s3-528","number":528,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿سنلقي في قلوب الذين كفروا الرعب﴾، فجعل الرعب شيئًا يُلقى؟","answer":"جُسّم الرعب شيئًا يُلقى في مستقر الإدراك والإرادة، فيسبق انهيار القلب انهيار الصفوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص101، تحت «بلاغة الاستعارة في قوله: ﴿سنلقي في قلوب الذين كفروا الرعب﴾»","url":""}]},{"id":"s3-529","number":529,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"لماذا قُدّم ﴿في قلوب الذين كفروا﴾ على ﴿الرعب﴾ في قوله تعالى: ﴿سنلقي في قلوب الذين كفروا الرعب﴾؟","answer":"قُدّم موضع إلقاء الرعب للاهتمام به قبل ذكر ما يُلقى فيه، وللتنبيه إلى أن القلب هو محل الرعب؛ فجاء التركيز على القلوب قبل التصريح بالرعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص102–103، تحت عنوان «بلاغة التقديم والتأخير»","url":""}]},{"id":"s3-530","number":530,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"لماذا عُلّل الرعب بقوله ﴿بما أشركوا بالله ما لم ينزل به سلطانًا﴾؟","answer":"أُلقي الرعب فيهم بسبب شركهم أو جزاءً مقابله؛ إذ اعتمدوا شركاء لا سلطان على ألوهيتهم، فخلا القلب من سند الحق والأمن. وبذلك ظهر أن الهزيمة ثمرة باطلهم لا تفوق عدد المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص103، تحت «مناسبة التعبير بقوله: ﴿ما لم ينزل به سلطانًا﴾».","url":""}]},{"id":"s3-531","number":531,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"لماذا سمّى الحجة ﴿سلطانًا﴾؟","answer":"سميت الحجة سلطانًا لأنها تتسلط بقوتها على العقل وتلزم الخصم كما يلزمه صاحب السلطة؛ ونفي إنزال السلطان يقرر أن الشرك لا يملك أدنى برهان من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص103–104، تحت «مناسبة التعبير بقوله: ﴿ما لم ينزل به سلطانًا﴾».","url":""}]},{"id":"s3-532","number":532,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿ومأواهم النار﴾، فجعل النار مأوى؟","answer":"المأوى في الأصل مكان يلجأ إليه المرء ويأمن، فجعل النار مأواهم على التهكم والمفارقة: إليها يصيرون ويستقرون، لكنها بدل الحماية عذاب دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص104، تحت «دلالة الجمع بين المأوى والمثوى».","url":""}]},{"id":"s3-533","number":533,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"لماذا ختم بـ﴿وبئس مثوى الظالمين﴾ بعد ﴿مأواهم النار﴾؟","answer":"بعد أن عين النار مأوى لهم، حكم عليها بـ﴿بئس﴾ فبالغ في ذم المستقر، ووصف أهله بالظالمين لربط المصير بسببه؛ فليست إعادة للنار، بل تقبيح للمحل والحال فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص105، تحت «حسن التذييل في قوله: ﴿وبئس مثوى الظالمين﴾».","url":""}]},{"id":"s3-534","number":534,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد صدقكم الله وعده﴾ مع أن المسلمين لم ينتصروا آخر المعركة؟","answer":"صدقهم الله وعد النصر فعلًا في بداية المعركة حين استقاموا على أمر الرسول وأخذوا يحسون عدوهم؛ ثم انقلبت الجولة عند مخالفة الرماة. فالهزيمة لم تكن إخلافًا للوعد، بل أثر زوال شرط الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص111، تحت «تتابع التأكيد في قوله: ﴿ولقد صدقكم الله وعده﴾».","url":""}]},{"id":"s3-535","number":535,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"لماذا اختير ﴿تحسونهم﴾ في وصف قتل المشركين؟","answer":"﴿تحسونهم﴾ لا تصف مجرد إصابة أفراد، بل قتلًا ذريعًا مستأصلًا؛ والمضارع يصور المؤمنين يوقعونه بالعدو حالًا بعد حال بإذن الله، شاهدًا على تحقق الوعد قبل المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص111، تحت «مناسبة التعبير بقوله: ﴿تحسونهم﴾ دون ﴿تقتلونهم﴾».","url":""}]},{"id":"s3-536","number":536,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا فشلتم وتنازعتم في الأمر وعصيتم﴾، ورتب هذه الأفعال هكذا؟","answer":"بدأ الفشل في الباطن بخور العزم أمام الغنيمة، فأنتج التنازع في فهم البقاء أو النزول، ثم آل إلى العصيان العملي بترك الموقع؛ فالترتيب يكشف كيف تتحول علة نفسية إلى انقسام ثم مخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص114–115، تحت «دلالة الترتيب بين الأفعال في ﴿فشلتم وتنازعتم في الأمر وعصيتم﴾».","url":""}]},{"id":"s3-537","number":537,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما أراكم ما تحبون﴾ بدل: بعد النصر؟","answer":"لم يقل «بعد النصر» لأن الذي رأوه وشدهم كان أوسع: بوادر الغلبة والغنائم التي يحبونها؛ فالتعبير يكشف محل الاختبار، ويقرر أن المعصية وقعت بعد أن عاينوا فضل الله لا قبل ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص115، تحت «دلالة تعلق ﴿من بعد ما أراكم ما تحبون﴾ بـ﴿فشلتم﴾ وما نُسق عليه».","url":""}]},{"id":"s3-538","number":538,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما دلالة تكرار ﴿مِنْكُمْ﴾ في التفريق بين من يريد الدنيا ومن يريد الآخرة؟","answer":"كشف التنازع اختلاف المقاصد: بعضهم حمله طلب الغنيمة على النزول، وبعضهم بقي طاعةً يريد الآخرة؛ وكرر ﴿منكم﴾ إنصافًا ليفصل الفريقين، فلا ينسب إرادة الدنيا إلى الجماعة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص117، تحت «بديع التفريق في قوله: ﴿منكم من يريد الدنيا ومنكم من يريد الآخرة﴾».","url":""}]},{"id":"s3-539","number":539,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"لماذا صُوّر الانصراف عن العدو بقوله ﴿ثم صرفكم عنهم﴾؟","answer":"الصرف ردهم عن الوجه الذي كانوا ماضين فيه، فبعد الإقبال على العدو والغلبة تحولوا إلى الانكفاء والفرار؛ و﴿ثم﴾ تبين أن ذلك جاء بعد مقدمات الفشل والتنازع والعصيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص117–118، تحت «دلالة ﴿ثم﴾ في ﴿ثم صرفكم عنهم﴾».","url":""}]},{"id":"s3-540","number":540,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ليبتليكم﴾ بعد ذكر المعصية والهزيمة؟","answer":"بيّن أن الصرف والهزيمة ابتلاء يكشفان مقدار الصبر والطاعة بعد الرخاء، لا حكم خذلان دائم؛ فالمحنة عرّفتهم ضعفهم وربتهم على أن النصر مشروط بالثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص118، تحت «بلاغة الاستعارة التمثيلية في قوله: ﴿ليبتليكم﴾».","url":""}]},{"id":"s3-541","number":541,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"لماذا أعقب العتاب فورًا بقوله ﴿ولقد عفا عنكم﴾؟","answer":"بعد تفصيل الفشل والتنازع والعصيان أكد العفو فورًا حتى لا يتحول العتاب إلى قنوط؛ فقد قبل ندمهم ولم يستأصلهم بالمؤاخذة، فجمع لهم كشف الخطأ وفتح باب الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص118، تحت «مناسبة التأكيد في قوله: ﴿ولقد عفا عنكم﴾».","url":""}]},{"id":"s3-542","number":542,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"لماذا ختم بـ﴿والله ذو فضل على المؤمنين﴾ لا: غفور لهم؟","answer":"لم يقتصر إحسان الله على ستر الذنب، بل عفا عنهم وأبقاهم في جماعة المؤمنين ورباهم وأيدهم؛ لذلك جاء ﴿ذو فضل﴾ أوسع من «غفور»، جامعًا العفو وغيره من وجوه الرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص119، تحت «حسن التذييل في قوله: ﴿والله ذو فضل على المؤمنين﴾».","url":""}]},{"id":"s3-543","number":543,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ تصعدون ولا تلوون على أحد﴾، وما صورة الصعود وعدم الالتفات؟","answer":"﴿تصعدون﴾ تستحضر اندفاعهم في جهة الجبل بعيدًا عن ساحة القتال، و﴿لا تلوون﴾ تصور أنهم لا يعطفون وجوههم ولا ينتظر بعضهم بعضًا؛ مشهد فرار استولى عليه الرعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص124، تحت «نكتة التعبير بالمضارع في ﴿إذ تصعدون ولا تلوون﴾».","url":""}]},{"id":"s3-544","number":544,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿والرسول يدعوكم في أخراكم﴾؟","answer":"أي إن الرسول بقي خلف جماعتكم المنهزمة يناديكم أن ارجعوا ولا تفروا، وأنتم ماضون لا تلتفتون؛ فالمشهد يبرز ثباته وانقطاع استجابتهم في لحظة الاضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص125، تحت «مناسبة التعبير بـ﴿والرسول﴾».","url":""}]},{"id":"s3-545","number":545,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿فأثابكم غمًا بغم﴾، وسمّى الغم ثوابًا؟","answer":"سمي الغم ثوابًا على أصل معنى الجزاء وبنبرة تقريع؛ فكان جزاء المخالفة غمًا متراكبًا، إما غمًا بسبب غم أحدثوه، أو غم القتل والجراح فوق غم خبر مقتل الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص127، تحت «دلالة تنكير قوله تعالى: ﴿غمًا بغم﴾».","url":""}]},{"id":"s3-546","number":546,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"لماذا نُكّر ﴿غمًا بغم﴾؟","answer":"يفيد التنكير التكثير والتفخيم؛ أي غمومًا كثيرة شديدة يتصل بعضها ببعض. فلا يلزم أن يكون المراد غمّين فقط، بل يصوّر التعبير تراكم الغموم وتعاظمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص127، تحت عنوان «دلالة تنكير قوله تعالى ﴿غمًا بغم﴾»","url":""}]},{"id":"s3-547","number":547,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"لماذا عُلّل ذلك بقوله ﴿لكيلا تحزنوا على ما فاتكم ولا ما أصابكم﴾؟","answer":"أذاقهم الغم المتراكم ليتمرنوا على احتمال الشدائد، فلا يستولي عليهم حزن ما فاتهم من الغنيمة والنصر ولا ما أصابهم من قتل وجراح؛ فالمحنة علاج لتعلق القلب بالمكسب والسلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص128، تحت «دلالة التعبير بقوله: ﴿لكيلا﴾».","url":""}]},{"id":"s3-548","number":548,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"لماذا قدّم ما فات على ما أصاب؟","answer":"لأن حزنهم بدأ بالغنيمة أو النصر الفائت ثم اشتد بالمصاب اللاحق؛ فرتب العلاج بحسب وقوع داعيي الحزن في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص129، تحت «بديع الطباق في قوله: ﴿ما فاتكم﴾ و﴿ما أصابكم﴾».","url":""}]},{"id":"s3-549","number":549,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"لماذا ختم بـ﴿والله خبير بما تعملون﴾؟","answer":"في الختام تهديد للمخالفين وتنبيه إلى أن الله يعلم أعمالهم وسيحاسبهم عليها. وخُص العمل بالذكر للتحذير مما وقع من الفرار وتولية الأدبار، مع أن علمه يشمل الأقوال والنيات أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص129، تحت عنوان «حسن التذييل بقوله: ﴿والله خبير بما تعملون﴾»","url":""}]},{"id":"s3-550","number":550,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]},{"surah":57,"verses":[23]}],"verseLabel":"آل عمران: 153؛ الحديد: 23","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿لكيلا تحزنوا على ما فاتكم﴾، وقوله تعالى في الحديد ﴿لكيلا تأسوا على ما فاتكم﴾؟","answer":"حزن أحد كان ألمًا حيًا متصلًا بهزيمة ومصاب قريب، فناسبه ﴿تحزنوا﴾؛ أما الحديد فيقرر قاعدة عامة في القدر ومتاع الدنيا، فاختير الأسى وهو حزن يمتد على الفائت ويتعلق به القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص224–225، تحت «توجيه المتشابه اللفظي بين آية الحديد وآية آل عمران».","url":""}]},{"id":"s3-551","number":551,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]},{"surah":57,"verses":[23]}],"verseLabel":"آل عمران: 153؛ الحديد: 23","question":"لماذا لم تذكر آل عمران بعد ﴿لكيلا تحزنوا على ما فاتكم﴾ مقابل الحديد ﴿ولا تفرحوا بما آتاكم﴾؟","answer":"مقام آل عمران علاج جرح أحد، فالعناية منصبة على الحزن بالمفقود والمصاب، ولم يكن مقام زهو بالنعمة؛ أما الحديد فيربي على التوازن العام بين الفقد والعطاء، فذكر طرفي الأسى والفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص224–225، تحت «توجيه المتشابه اللفظي بين آية الحديد وآية آل عمران».","url":""}]},{"id":"s3-552","number":552,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم أنزل عليكم من بعد الغم أمنة نعاسًا﴾، فجعل النعاس أمنة منزلة؟","answer":"صوّر الأمن عطاءً ينزل من عند الله بعد تراكم الغم، وبدل منه ﴿نعاسًا﴾ لأن غلبة النوم في موطن الخوف لا تكون إلا بعد سكون القلب؛ فصار النعاس أثر الأمنة المحسوس ودليلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص143–144، تحت «سر الجمع بين لفظي الأمنة والنعاس».","url":""}]},{"id":"s3-553","number":553,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا غشي النعاس طائفة ولم يغش الطائفة الأخرى؟","answer":"الأمنة نزلت على من صدق توكله فسكنت نفسه، أما من أهمتهم أنفسهم وساء ظنهم بالله فظل القلق مستوليًا عليهم؛ فصار النعاس كاشفًا لحال القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص145–146، تحت «بيان الفرق بين الطائفتين بالواو، وباختلاف الوصفين، وحكميهما الإعرابي».","url":""}]},{"id":"s3-554","number":554,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى عن الطائفة الأخرى ﴿قد أهمتهم أنفسهم﴾؟","answer":"أي استولى عليهم الاهتمام بأنفسهم وسلامتهم وحدها، فلم يشغلهم مصير الدين ولا الرسول ولا المؤمنين؛ فتكشف العبارة أن القلق ثمرة أنانية وضعف يقين، في مقابل طائفة الأمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص145–146، تحت «بيان الفرق بين الطائفتين بالواو، وباختلاف الوصفين، وحكمهما الإعرابي».","url":""}]},{"id":"s3-555","number":555,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا وصف ظنهم بأنه ﴿غير الحق ظن الجاهلية﴾؟","answer":"﴿غير الحق﴾ تحكم ببطلان ظنهم، و﴿ظن الجاهلية﴾ تكشف أصله العقدي: سوء معرفة بالله ووعده وتدبيره، كتوهم أن الرسول سيخذل أو أن النصر خارج أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص149، تحت «غرض التعبير بلفظ ﴿الجاهلية﴾».","url":""}]},{"id":"s3-556","number":556,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا سألوا ﴿هل لنا من الأمر من شيء﴾ في صورة استفهام؟","answer":"هو استفهام اعتراض وتشكيك من أصحاب الظن، يوحي بأنهم حُرموا التدبير؛ فجاء الجواب بقصر الأمر كله على الله وكشف ما يخفونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص149، تحت «بلاغة الاستفهام في قوله تعالى: ﴿يقولون هل لنا من الأمر من شيء﴾».","url":""}]},{"id":"s3-557","number":557,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا جاء الرد ﴿قل إن الأمر كله لله﴾ بتوكيد وعموم؟","answer":"أكد بـ﴿إن﴾ لأن قولهم صادر عن شك واعتراض، وعمم بـ﴿كله﴾ حتى لا يبقى تدبير أو نصر أو أجل خارج سلطان الله؛ فالرد لا ينفي استعمال الأسباب، بل ينفي استقلالها وأهواء الناس بالأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص150–151، تحت «بلاغة حشد المؤكدات».","url":""}]},{"id":"s3-558","number":558,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير بقوله: ﴿في أنفسهم﴾ بعد ﴿يخفون﴾؟","answer":"أخفوا في قلوبهم اعتراضًا لم يجرؤوا على إظهاره للرسول: اتهام تدبير الخروج بأنه سبب القتل؛ فالجملة تكشف الفرق بين سؤالهم الظاهر وسوء ظنهم الباطن، وتقرر أن الله أطلع نبيه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص147–148، تحت «سر التعبير بقوله: ﴿في أنفسهم﴾ بعد ﴿يخفون﴾».","url":""}]},{"id":"s3-559","number":559,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا كرر سؤالهم بصيغة أخرى: ﴿لو كان لنا من الأمر شيء ما قتلنا هاهنا﴾؟","answer":"السؤال الأول اعتراض مبهم: هل لنا من التدبير شيء؟ أما الثانية فتصرح بمكنون الاعتراض: لو أخذ برأينا وبقينا في المدينة لما قتل أصحابنا. فهي تكشف النتيجة القدرية الفاسدة الكامنة وراء السؤال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص149–150، تحت «بلاغة الاستفهام في قوله تعالى: ﴿يقولون هل لنا من الأمر من شيء﴾».","url":""}]},{"id":"s3-560","number":560,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما فائدة تعليم الجواب في قوله تعالى: ﴿لبرز الذين كتب عليهم القتل إلى مضاجعهم﴾؟","answer":"حتى لو بقيتم في البيوت لخرج من كتب عليه القتل إلى المكان المقدر له؛ فـ﴿لبرز﴾ تصور قوة نفاذ القدر الذي يستخرج صاحبه إلى أجله، وتبطل وهم أن اختيار الخطة يمنع الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص152، تحت «فائدة تعليم الجواب».","url":""}]},{"id":"s3-561","number":561,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا سمّى مواضع القتل ﴿مضاجعهم﴾؟","answer":"المضجع مكان يضع فيه الإنسان جنبه للنوم، فصور موضع القتل مضجعًا يستقر فيه الجسد كالنائم؛ وإضافته إليهم توحي بأن لكل واحد موضعًا مقدرًا يبلغه عند أجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص153، تحت «نكتة الاستعارة في لفظ المضاجع».","url":""}]},{"id":"s3-562","number":562,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا جمع بين ابتلاء ما في الصدور وتمحيص ما في القلوب؟","answer":"الابتلاء يُظهر المستور ويختبره، والتمحيص ينقيه ويميز خالصه من دخيله؛ فالمحنة كاشفة ومطهرة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص154، تحت «علة إطلاق الصدور على الضمائر، والقلوب على الاعتقاد».","url":""}]},{"id":"s3-563","number":563,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا خُتمت الآية بـ﴿والله عليم بذات الصدور﴾؟","answer":"لأن الآية عرضت أقوالًا تخفي وراءها ظنونًا واعتراضات؛ فقرر أن الله يعلم السريرة التي تولد منها الكلمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص154–155، تحت «جماع المؤكدات في فاصلة الآية».","url":""}]},{"id":"s3-564","number":564,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الذين تولوا منكم يوم التقى الجمعان﴾ ولم يسمّهم؟","answer":"لم يسمهم سترًا عليهم بعد أن عفا الله عنهم، وعرّفهم بالفعل والوقت بقدر ما تقوم به العبرة: الذين أدبروا يوم أُحد؛ فثبت الخطأ للتربية من غير تخليد أسماء أصحابه بالفضيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص166، تحت «وجه التعبير بلفظ الجمع».","url":""}]},{"id":"s3-565","number":565,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما استزلهم الشيطان ببعض ما كسبوا﴾، فجعل الخطأ زلّة؟","answer":"الاستزلال طلب إيقاع القدم في الزلل بعد ثباتها، فصور الفرار عثرة جرهم إليها الشيطان بسبب بعض ما سبق من ذنوبهم؛ وفي تسميته زلة تخفيف لا تبرئة، يوافق العفو اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص166–167، تحت «الاستعارة في لفظ الزلل للتعبير عن معنى الانهزام».","url":""}]},{"id":"s3-566","number":566,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿ببعض ما كسبوا﴾، دون أن يقال: بذنوبهم؟","answer":"﴿كسبوا﴾ تنسب السبب إلى عمل اختاروه هم، لا إلى طبيعة لازمة، و﴿بعض﴾ تفيد أن بعض الذنوب فتح للشيطان مدخل الزلة؛ وفيها تخفيف ورحمة مع إثبات المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص168، تحت «معاني حرف الباء في قوله: ﴿ببعض ما كسبوا﴾».","url":""}]},{"id":"s3-567","number":567,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"لماذا كرر العفو في ﴿ولقد عفا الله عنهم﴾؟","answer":"أعيد العفو هنا ليخص الذين تولوا يوم التقى الجمعان بعد بيان سبب زلتهم، فيغلق باب التشهير والمؤاخذة بعد التوبة؛ فليس تكرارًا خاليًا، بل عفو محدد عن جماعة عُين خطؤها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص169، تحت «علة تكرار الإخبار بالعفو»","url":""}]},{"id":"s3-568","number":568,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"لماذا ختم بـ﴿إن الله غفور حليم﴾؟","answer":"﴿غفور﴾ يقرر ستر زلتهم ومحو مؤاخذتها، و﴿حليم﴾ يبين أنه لم يعاجلهم بالعقوبة حين فروا بل أمهلهم حتى تابوا؛ فاجتمعت إزالة الذنب مع الإمهال السابق لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص171، تحت «دلالة جملة التذييل».","url":""}]},{"id":"s3-569","number":569,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"لماذا نُهي المؤمنون أن يكونوا كالذين كفروا في كلامهم عن إخوانهم؟","answer":"لأن قولهم يربط الموت بالسفر والقتال ويغذي الحسرة والجبن، فأبطل القرآن منطقهم بتقرير أن الإحياء والإماتة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص185–188، تحت «قوة قوله: ﴿والله يحيي ويميت﴾ بعد النهي السابق».","url":""}]},{"id":"s3-570","number":570,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا ضربوا في الأرض﴾، وكيف يكون السفر ضربًا؟","answer":"الضرب في الأرض كناية عن السفر والسير فيها، لأن المسافر يوقع قدميه عليها ويقطع نواحيها حركةً بعد حركة؛ فاختير فعل حركي يجسد مشقة الارتحال وامتداده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص182، تحت «وجه الاستعارة في لفظة الضرب».","url":""}]},{"id":"s3-571","number":571,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"لماذا قابل بين ﴿غزّى﴾ و﴿ضربوا في الأرض﴾؟","answer":"﴿ضربوا في الأرض﴾ يشمل السفر في مصالح الدنيا، و﴿غزّى﴾ يخص الخروج للقتال؛ فجمعهما ليبطل قولهم في كل غائب مات طبيعيًا أو قتل في المعركة، لا في صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص180، تحت «علة ذكر الغزو بعد الضرب، وإفراده منه».","url":""}]},{"id":"s3-572","number":572,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"لماذا كرروا ﴿ما ماتوا وما قتلوا﴾ مع إمكان الاكتفاء بأحدهما؟","answer":"الموت يقابل السفر والقتل يقابل الغزو، فلابد من ذكرهما لاستيعاب الحالتين؛ وكررت ﴿ما﴾ حتى يكون كل نفي مستقلًا: لا ماتوا ولا قتلوا، لا أن المنفي أحدهما فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص184، تحت «فائدة تكرار حرف النفي (ما)».","url":""}]},{"id":"s3-573","number":573,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"ما معنى جعل الحسرة من فعل الله تعالى في قوله تعالى: ﴿ليجعل الله ذلك حسرة في قلوبهم﴾؟","answer":"جعل الله هذا الاعتقاد نفسه حسرة ملازمة لقلوبهم؛ لأن من ظن أن البقاء كان يمنع الموت ظل يراجع الاحتمال المستحيل ويندم، أما المؤمن فيسلم للأجل فلا تستعبده «لو».","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص185، تحت «معنى جعل الحسرة من فعل الله تعالى».","url":""}]},{"id":"s3-574","number":574,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿والله يحيي ويميت﴾ بعد نفي أثر البقاء في البيوت؟","answer":"عقب قولهم ليحسم أصل الوهم: لا البيت يحيي ولا السفر والقتال يميتان، بل الله وحده يقدر الحياة والموت بأجلهما؛ فذكر الضدين يستوعب السلطان كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص185، تحت «قوة قوله: ﴿والله يحيي ويميت﴾ بعد النهي السابق».","url":""}]},{"id":"s3-575","number":575,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"لماذا ختم بـ﴿والله بما تعملون بصير﴾؟","answer":"البصر أنسب بمقام الأعمال والمواقف المشاهدة، وفيه مراقبة ووعد أو وعيد بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص186–187، تحت «بيان المناسبة بين العمل والبصر والعلم».","url":""}]},{"id":"s3-576","number":576,"surah":3,"verses":[157],"references":[{"surah":3,"verses":[157]}],"verseLabel":"آل عمران: 157","question":"ما سرّ تقديم ﴿قتلتم﴾ على ﴿متم﴾ في الآية 157، وتقديم الموت على القتل في الآيتين 144 و158؟","answer":"في آية 157 المقام ترغيب في الجهاد فقدم القتل في سبيل الله، أما آية 144 فالمقام في مضي الرسول كسائر الرسل، فقدم الموت لأنه الوصف الجامع لمضيهم، ومعه إشعار بأن النبي ﷺ سيموت ولا يقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص199–200، تحت «توجيه المتشابه اللفظي تقديمًا وتأخيرًا في لفظتي الموت والقتل».","url":""}]},{"id":"s3-577","number":577,"surah":3,"verses":[157],"references":[{"surah":3,"verses":[157]}],"verseLabel":"آل عمران: 157","question":"ما الغرض البلاغي من تنكير مغفرة ورحمة في قوله تعالى: ﴿لمغفرة من الله ورحمة خير مما يجمعون﴾؟","answer":"أكد بالقسم واللام أن ما يناله المقتول أو الميت في سبيل الله من مغفرة تمحو الذنب ورحمة توصله إلى النعيم خير من جميع ما يكدس الناس من متاع الدنيا؛ فصحح مقياس الربح والخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص193، تحت «غرض تنكير مغفرة ورحمة».","url":""}]},{"id":"s3-578","number":578,"surah":3,"verses":[157],"references":[{"surah":3,"verses":[157]}],"verseLabel":"آل عمران: 157","question":"لماذا قدّم المغفرة على الرحمة؟","answer":"لأن المغفرة ترفع أثر الذنب أولًا، ثم تتفضل الرحمة بإيصال الخير؛ فالتطهير سابق على الإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص194–195، تحت «توجيه عطف ﴿ورحمة﴾ على المغفرة».","url":""}]},{"id":"s3-579","number":579,"surah":3,"verses":[157],"references":[{"surah":3,"verses":[157]}],"verseLabel":"آل عمران: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿مما يجمعون﴾ ولم يذكر المال؟","answer":"حذف مفعول ﴿يجمعون﴾ ليعم المال والغنائم وسائر متاع الدنيا ومكاسبها؛ فالمغفرة والرحمة خير من كل مجموع يتنافسون فيه، لا من نوع مالي واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص195، تحت «وجه احتمال خيرية ما يجمعون».","url":""}]},{"id":"s3-580","number":580,"surah":3,"verses":[158],"references":[{"surah":3,"verses":[158]}],"verseLabel":"آل عمران: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿لإلى الله تحشرون﴾ بتقديم الجار والمجرور؟","answer":"قدم ﴿إلى الله﴾ لقصر الحشر والمرجع عليه ولتعظيم الغاية: سواء متم أو قتلتم فليس المصير إلى الدنيا ولا إلى من خفتموهم، بل إليه وحده للحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص201، تحت «بلاغة تقديم متعلق الفعل عليه في قوله: ﴿لإلى الله تحشرون﴾».","url":""}]},{"id":"s3-581","number":581,"surah":3,"verses":[158],"references":[{"surah":3,"verses":[158]}],"verseLabel":"آل عمران: 158","question":"لماذا اختير ﴿تحشرون﴾ لا: ترجعون؟","answer":"الرجوع قد يكون فرديًا ومجرد عودة، أما الحشر فيصور جمع الناس من قبورهم وسوقهم جميعًا إلى موقف الحساب؛ فناسب تقرير المصير العام بعد الموت والقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص202، تحت «سر التعبير بالفعل المبني للمفعول».","url":""}]},{"id":"s3-582","number":582,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿فبما رحمة من الله لنت لهم﴾، وما سر زيادة ﴿ما﴾؟","answer":"زيدت ﴿ما﴾ لتوكيد أن لين النبي ﷺ ناشئ عن رحمة عظيمة من الله وتقوية السببية، وقيل هي نكرة تفخيمية: فبرحمةٍ ما عظيمة لنت لهم؛ وفي الوجهين تعظيم للمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص209، تحت «بلاغة ذكر (ما) في قوله تعالى: ﴿فبما﴾».","url":""}]},{"id":"s3-583","number":583,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا نُسب اللين إلى النبي في قوله ﴿لنت لهم﴾؟","answer":"نسب الفعل إليه لأن الرحمة الإلهية تجسدت في معاملته الفعلية لهم: عفا وخاطب برفق بعد أُحد؛ واستعير لين الملمس لسهولة الخلق ورفقه، مع بقاء مصدر هذا الخلق رحمةً من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص212–213، تحت «فن التكميل في قوله: ﴿فبما رحمة من الله لنت لهم﴾».","url":""}]},{"id":"s3-584","number":584,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا جمع بين ﴿فظًا﴾ و﴿غليظ القلب﴾؟","answer":"الفظاظة خشونة القول والمعاملة في الظاهر، وغلظ القلب قسوة الباطن؛ فانتفى عن الرسول السبب الداخلي ومظهره الذي ينفر الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص213، تحت «علة تقديم وصف الفظاظة على وصف الغلظة».","url":""}]},{"id":"s3-585","number":585,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا صوّر ابتعاد الناس بقوله ﴿لانفضوا من حولك﴾؟","answer":"الانفضاض تفرق الجماعة من حول مركزها؛ فشبه نفورهم وفرارهم عنه متفرقين بانفضاض قوم كانوا مجتمعين حوله، وفي ﴿من حولك﴾ إشعار بأنهم كانوا ملتفين به متبعين له.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص205–206، تتمة «شرح المفردات»، مدخلا ﴿لانفضوا﴾ و﴿حولك﴾.","url":""}]},{"id":"s3-586","number":586,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا رتب الأوامر: ﴿فاعف عنهم واستغفر لهم وشاورهم في الأمر﴾؟","answer":"بدأ بالعفو عما تعلق بحقه ﷺ، ثم بالاستغفار لهم فيما بينهم وبين الله، ثم بالمشاورة بعد إزالة أثر الذنب؛ فانتقل من محو المؤاخذة إلى طلب المغفرة ثم إعادة إشراكهم في أمر الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص216، تحت «مراعاة حسن الترتيب في الأوامر».","url":""}]},{"id":"s3-587","number":587,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا أمره بمشاورتهم بعد ما وقع بسبب بعضهم في أُحد؟","answer":"أمره أن يشاورهم بعد زلتهم تأليفًا لقلوبهم وإشعارًا ببقاء منزلتهم، حتى لا يظنوا أن خطأ أُحد أخرجهم من المشاركة؛ فالعفو والاستغفار يتبعهما رد الاعتبار العملي بالمشاورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص214–215، تحت «علة التفريع في قوله: ﴿فاعف عنهم﴾».","url":""}]},{"id":"s3-588","number":588,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا أمر الله بالتوكل عليه بعد الأمر بالمشاورة في قوله تعالى: ﴿فإذا عزمت فتوكل على الله﴾؟","answer":"المشاورة أخذ بالأسباب، ثم يأتي التوكل حتى لا يكون الاعتماد على الرأي الذي انتهت إليه المشاورة وحده، بل على إعانة الله وتسديده؛ فيجمع العمل بين النظر في الأسباب والاعتماد على مسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص217، تحت عنوان «دلالة نسبة التوكل على الله تعالى»","url":""}]},{"id":"s3-589","number":589,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا ختم بـ﴿إن الله يحب المتوكلين﴾؟","answer":"ختم بالمحبة ترغيبًا في التوكل بعد العزم؛ لأنه علامة صدق الإيمان والافتقار إلى الله. وأكد الخبر بـ﴿إن﴾، وعبّر بـ﴿المتوكلين﴾ لمدح من ثبت التوكل وصفًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص218–219، تحت «بلاغة التذييل بجملة ﴿إن الله يحب المتوكلين﴾».","url":""}]},{"id":"s3-590","number":590,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]},{"surah":62,"verses":[11]}],"verseLabel":"آل عمران: 159؛ الجمعة: 11","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿لانفضوا من حولك﴾، وقوله تعالى في الجمعة ﴿انفضوا إليها وتركوك قائمًا﴾؟","answer":"﴿من حولك﴾ تصور تفكك الجماعة وابتعادها عن مركزها بسبب الفظاظة، أما ﴿إليها﴾ فتصور اندفاعهم نحو التجارة واللهو؛ فالحرفان يرسمان جهتي الحركة: نفورًا من شخص، وإقبالًا على مغرٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص746، تحت «نكتة تعدية الفعل ﴿انفضوا﴾ بـ(إلى)».","url":""}]},{"id":"s3-591","number":591,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ينصركم الله فلا غالب لكم﴾، دون أن يقال: فأنتم الغالبون؟","answer":"﴿فلا غالب لكم﴾ تنفي جنس من يستطيع غلبتكم نفيًا شاملاً، وهو أقوى من مجرد قول «فأنتم الغالبون»؛ لأن العبرة ليست بقوتكم الذاتية بل باستحالة قهر من نصره الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص225، تحت «بيان دلالة النفي في قوله: ﴿إن ينصركم الله فلا غالب لكم﴾».","url":""}]},{"id":"s3-592","number":592,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"لماذا قابل النصر بالخذلان لا بالهزيمة؟","answer":"لأن الخذلان هو سلب المعونة، وهو المقابل الحقيقي لنصر الله؛ أما الهزيمة فنتيجة ظاهرة قد تقع ابتلاءً ولا تدل وحدها على انقطاع الولاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص226، تحت «براعة التعبير عن المقابلة».","url":""}]},{"id":"s3-593","number":593,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن ذا الذي ينصركم من بعده﴾ في صورة سؤال؟","answer":"الاستفهام إنكاري بمعنى: لا أحد ينصركم إذا خذلكم الله، وهو أبلغ لأنه يدفعهم إلى طلب الناصر ثم الإقرار باستحالته؛ وصيغ سؤالًا تلطفًا بالمؤمنين بدل التصريح القاسي بنفي الناصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص226، تحت «غرض الاستفهام البلاغي».","url":""}]},{"id":"s3-594","number":594,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"لماذا ختم ﴿وعلى الله فليتوكل المؤمنون﴾ كما ختمت آية 122؟","answer":"لما انحصر النصر والخذلان في مشيئة الله، لزم أن يخصه المؤمنون بالتوكل؛ فقدم ﴿على الله﴾ للحصر، وعلق الأمر بالمؤمنين لأن إيمانهم بأنه وحده الناصر يقتضي تفويض الأمر إليه، كما في آية 122.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص229، تحت «فائدة التعبير بلفظ المؤمنين».","url":""}]},{"id":"s3-595","number":595,"surah":3,"verses":[161],"references":[{"surah":3,"verses":[161]}],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان لنبي أن يغل﴾ بصيغة الاستبعاد؟","answer":"﴿ما كان لنبي﴾ لا تنفي وقوع الغلول فحسب، بل تستبعد إمكان ملاءمته لمقام النبوة أصلًا؛ فالأمانة لازمة لكل نبي، والخيانة منافية لما اصطفاه الله له.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص234، تحت «بلاغة النفي بالتعبير ﴿وما كان﴾»","url":""}]},{"id":"s3-596","number":596,"surah":3,"verses":[161],"references":[{"surah":3,"verses":[161]}],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يغلل يأت بما غل يوم القيامة﴾، وكيف يأتي الإنسان بما أخفى؟","answer":"يجيء الغال يوم القيامة حاملًا ما خانه على رؤوس الأشهاد، وقيل يأتي بإثم الغلول وتبعته؛ ففي الوجهين ينقلب ما أخفاه في الدنيا إلى علامة ظاهرة تفضحه وتلزمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص241–245، تحت «الإتيان والمجيء».","url":""}]},{"id":"s3-597","number":597,"surah":3,"verses":[161],"references":[{"surah":3,"verses":[161]}],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم توفى كل نفس ما كسبت﴾، فجعل العمل كسبًا؟","answer":"سمى العمل كسبًا لأنه ثمرة اختيار النفس وسعيها، يعود نفعه أو ضرره عليها؛ وبعد ذكر الغال خاصة عمم الحكم: كل نفس تستوفي جزاء جميع ما اكتسبت بلا نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص240، تحت «سبب وضع المكسوب موضع جزائه».","url":""}]},{"id":"s3-599","number":599,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما وجه البلاغة في الفصل بالاستفهام الإنكاري في قوله تعالى: ﴿أفمن اتبع رضوان الله كمن باء بسخط من الله﴾؟","answer":"الاستفهام ينفي التسوية نفيًا يحمل السامع على الحكم بنفسه؛ فشتان بين من طلب الرضا ومن رجع حاملًا السخط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص245، تحت «بلاغة الفصل بالاستفهام الإنكاري».","url":""}]},{"id":"s3-600","number":600,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿اتبع رضوان الله﴾، وكيف يُتبع الرضوان؟","answer":"اتبع رضوان الله أي سلك الأعمال والهدى التي توصل إليه، مقتفيًا أمر الله ومجتنبًا نهيه؛ فنزل طلب أسباب الرضا منزلة اتباع طريق وآثار تقود إلى الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص246، تحت «التعبير بالرضوان دون الرضا».","url":""}]},{"id":"s3-601","number":601,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿باء بسخط﴾ لا: استحق سخطًا؟","answer":"﴿باء بسخط﴾ أبلغ من «استحق»؛ فهي تصوره راجعًا وقد حمل السخط ولزمه، حتى صار مآبه مقرونًا به، لا مجرد حكم باستحقاق بعيد عن مشهد الرجوع والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص246، تحت «وجه الاستعارة في الاستفهام»، في بيان ﴿كمن باء بسخط من الله﴾.","url":""}]},{"id":"s3-602","number":602,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"لماذا ختم بـ﴿وبئس المصير﴾ بعد ذكر جهنم؟","answer":"لم يكتف بذكر جهنم، بل ذمها بوصفها المرجع الذي ينتهي إليه صاحبه ويستقر فيه؛ فـ﴿بئس﴾ تقبح العاقبة، و﴿المصير﴾ يقرر أنها نهاية طريق السخط لا عارض عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص247، تحت «تعقيب ذكر السخط بذكر العقاب».","url":""}]},{"id":"s3-603","number":603,"surah":3,"verses":[163],"references":[{"surah":3,"verses":[163]}],"verseLabel":"آل عمران: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿هم درجات عند الله﴾، دون أن يقال: لهم درجات؟","answer":"﴿هم درجات﴾ أبلغ من ﴿لهم درجات﴾؛ إذ جعلهم نفس الدرجات مبالغة في شدة تفاوتهم بحسب أعمالهم، كأن ذواتهم تجسدت منازل متفاوتة علوًا وسفلاً عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص253، تحت «بلاغة المجاز بحذف المضاف في قوله: ﴿هم درجات﴾».","url":""}]},{"id":"s3-604","number":604,"surah":3,"verses":[163],"references":[{"surah":3,"verses":[163]}],"verseLabel":"آل عمران: 163","question":"لماذا جمع الجميع في لفظ ﴿درجات﴾ مع اختلاف منازل الخير والشر؟","answer":"إذا عاد ﴿هم﴾ إلى فريقي الرضوان والسخط، أطلق ﴿درجات﴾ على منازل الفريقين من باب تغليب درجات أهل الخير على دركات أهل الشر؛ فشمل تفاوت الثواب والعقاب مع إبراز جانب الرضوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص254، تحت «نكتة التعبير عن الدرجات بجمع القلة»","url":""}]},{"id":"s3-605","number":605,"surah":3,"verses":[163],"references":[{"surah":3,"verses":[163]}],"verseLabel":"آل عمران: 163","question":"لماذا ختم بـ﴿والله بصير بما يعملون﴾؟","answer":"البصر أنسب بمقام الأعمال والمواقف المشاهدة، وفيه مراقبة ووعد أو وعيد بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص255، تحت «التعبير بصيغة فعيل».","url":""}]},{"id":"s3-606","number":606,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد منّ الله على المؤمنين﴾، وخص المؤمنين مع أن الرسول أُرسل للناس؟","answer":"الرسالة عامة، لكن المنة خصت بالمؤمنين لأنهم الذين آمنوا بالرسول وانتفعوا بتلاوته وتزكيته وتعليمه؛ فمن رد الرسالة لم تتحقق فيه ثمرة هذه النعمة وإن بلغه أصل الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص266، تحت «سر التعبير بالرسول دون النبي»","url":""}]},{"id":"s3-607","number":607,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿رسولًا من أنفسهم﴾ لا: منهم؟","answer":"﴿من أنفسهم﴾ تشعر بأنه من صميم جماعتهم وجنسهم ولسانهم، معروف النسب والسيرة بينهم؛ فذلك أدعى لأن يألفوه ويفهموا عنه ويثقوا بصدقه، وهو أبلغ قربًا من «منهم».","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص264–265، تحت «فائدة التعبير بلفظ ﴿أنفسهم﴾».","url":""}]},{"id":"s3-608","number":608,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"لماذا رتب وظائف الرسول: التلاوة، ثم التزكية، ثم تعليم الكتاب والحكمة؟","answer":"التلاوة توصل الوحي أولًا، والتزكية تهيئ النفوس لقبوله، والتعليم يبني الفهم الراسخ للكتاب والحكمة؛ فجمع البلاغ والتربية والمعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص267–268، تحت «نكتة توسيط التزكية بين تلاوة الآيات وتعليمها».","url":""}]},{"id":"s3-609","number":609,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سرّ تقديم التزكية هنا على تعليم الكتاب والحكمة؟","answer":"قدمت التزكية لأن تخليص النفوس من الشرك وأخلاق الجاهلية يهيئها للانتفاع بالكتاب والحكمة، ولأن المخاطبين كانوا أحوج أولًا إلى تهذيب النفس؛ وليس المقصود فصل العمليتين زمنيًا، فالتعليم نفسه من وسائل التزكية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص267، تحت «علة تقديم جملة ﴿ويزكيهم﴾».","url":""}]},{"id":"s3-610","number":610,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن كانوا من قبل لفي ضلال مبين﴾ بهذا التوكيد؟","answer":"أكد الجملة بـ﴿إن﴾ واللام في ﴿لفي﴾ لتقرير أنهم كانوا قبل الرسالة غارقين حقًا في ضلال واضح هو الشرك؛ وكلما ثبتت شدة الحال الأولى ظهر مقدار المنة في إخراجهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص269، تحت «نكتة التعبير بجملة ﴿وإن كانوا من قبل﴾».","url":""}]},{"id":"s3-611","number":611,"surah":3,"verses":[164],"references":[{"surah":2,"verses":[129,151]},{"surah":3,"verses":[164]},{"surah":62,"verses":[2]}],"verseLabel":"آل عمران: 164؛ البقرة: 129، 151؛ الجمعة: 2","question":"ما سرّ تقديم التزكية على تعليم الكتاب في آل عمران، بينما قدم إبراهيم التعليم على التزكية في دعائه؟","answer":"دعاء إبراهيم سار على ترتيب الوسائل المتوقعة: تلاوة ثم تعليم ثم تزكية، أما الإخبار عن منة الله فقدم ثمرة الرسالة العملية وهي تزكية النفوس، مع أن أعمال الرسول متداخلة؛ فترتيب الدعاء ترتيب طلب، وترتيب الامتنان ترتيب عناية وغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص267–268، تحت «علة تقديم جملة ﴿ويزكيهم﴾».","url":""}]},{"id":"s3-613","number":613,"surah":3,"verses":[165],"references":[{"surah":3,"verses":[165]}],"verseLabel":"آل عمران: 165","question":"ما دلالة لفظ ﴿مثليها﴾ وما يستفاد منها؟","answer":"أنكر تعجبهم من أُحد وذكّرهم بموازين الوقائع: أصابهم قتل سبعين، وقد أصابوا المشركين في بدر مثلي ذلك قتلًا وأسرًا؛ فلا يصح أن ينسوا النعمة السابقة ثم يستبعدوا مصيبة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص276، تحت «دلالة لفظ ﴿مثليها﴾ وما يستفاد منها».","url":""}]},{"id":"s3-614","number":614,"surah":3,"verses":[165],"references":[{"surah":3,"verses":[165]}],"verseLabel":"آل عمران: 165","question":"لماذا حكى تعجبهم بقولهم ﴿أنى هذا﴾ لا: كيف حدث هذا؟","answer":"﴿أنى﴾ تسأل عن جهة مجيء المصيبة ومصدرها، فجاء الجواب ﴿هو من عند أنفسكم﴾ مطابقًا؛ أما كيف فتطلب صفة الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص277، تحت «بلاغة الاستفهام بـ﴿أنى﴾».","url":""}]},{"id":"s3-615","number":615,"surah":3,"verses":[165],"references":[{"surah":3,"verses":[165]}],"verseLabel":"آل عمران: 165","question":"لماذا جاء الجواب ﴿قل هو من عند أنفسكم﴾؟","answer":"ردّ سبب المصيبة إلى مخالفة الرماة والتنازع، ليمنع تعليق الفشل على القدر وحده ويثبت مسؤولية الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص277، تحت «وجه التوكيد في جملة القول».","url":""}]},{"id":"s3-616","number":616,"surah":3,"verses":[165],"references":[{"surah":3,"verses":[165]}],"verseLabel":"آل عمران: 165","question":"لماذا ختم بـ﴿إن الله على كل شيء قدير﴾ مع أن الحديث عن خطأ البشر؟","answer":"حتى لا يفهم إسناد المصيبة إلى أنفسهم أن الله عجز عن دفعها؛ فهو قادر على النصر والخذلان، لكن حكمته أجرت أثر مخالفتهم عليهم. فاجتمعت مسؤولية البشر مع شمول القدرة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص278، تحت «بلاغة الفاصلة القرآنية».","url":""}]},{"id":"s3-617","number":617,"surah":3,"verses":[166],"references":[{"surah":3,"verses":[166]}],"verseLabel":"آل عمران: 166","question":"ما سرّ التعبير بـ﴿يوم التقى الجمعان﴾ دون ﴿يوم أُحد﴾؟","answer":"بعد قوله إن المصيبة من عند أنفسهم، بيّن أنها لم تخرج عن سلطان الله: وقعت بعلمه وقضائه وقدره وإذنه الكوني؛ فالمخالفة سببها البشري، والإذن يثبت أن الأسباب لا تستقل عن تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص285، تحت «سر التعبير بـ﴿يوم التقى الجمعان﴾ دون ﴿يوم أُحد﴾».","url":""}]},{"id":"s3-618","number":618,"surah":3,"verses":[166],"references":[{"surah":3,"verses":[166]}],"verseLabel":"آل عمران: 166","question":"لماذا عبّر عن أُحد بـ﴿يوم التقى الجمعان﴾؟","answer":"لم يسم أُحد، بل استحضرها بوصفها يوم مواجهة جمع المؤمنين وجمع المشركين؛ لأن المقصود ليس المكان وحده، بل اللقاء الذي ترتبت عليه المصيبة وانكشف فيه صدق المؤمنين ونفاق المتخلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص285، تحت «سرّ التعبير بـ﴿يوم التقى الجمعان﴾ دون يوم أُحد»","url":""}]},{"id":"s3-619","number":619,"surah":3,"verses":[166],"references":[{"surah":3,"verses":[166]}],"verseLabel":"آل عمران: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿وليعلم المؤمنين﴾ مع سبق علم الله؟","answer":"ليس المراد حدوث علم لم يكن، فعلم الله سابق محيط؛ بل أن يظهر إيمان المؤمنين في الواقع ويتميزوا بأفعالهم، فينكشف للناس ما كان معلومًا لله ويقوم عليه الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص286، تحت «نكتة تكرار فعل العلم من قوله تعالى: ﴿وليعلم المؤمنين وليعلم الذين نافقوا﴾».","url":""}]},{"id":"s3-620","number":620,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"ما دلالة ﴿أو﴾ وبلاغة التعريض في قوله: ﴿قاتلوا في سبيل الله أو ادفعوا﴾؟","answer":"أقيمت عليهم الحجة بدعوتهم إلى أحد طريقين: قتال مخلص في سبيل الله، أو على الأقل دفع العدو عن الحرم والأهل وتكثير جمع المسلمين؛ فرفضهم الأمرين كشف أن تخلفهم ليس لاختلاف نية القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص289، تحت «دلالة ﴿أو﴾ وبلاغة التعريض في قوله: ﴿قاتلوا في سبيل الله أو ادفعوا﴾».","url":""}]},{"id":"s3-621","number":621,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"لماذا عُرض عليهم القتال في سبيل الله، ثم أدنى منه مجرد الدفع؟","answer":"أقام عليهم الحجة بالتدرج: إن لم يخلصوا للقتال الديني فليدفعوا عن الأهل والبلد؛ فلما رفضوا الأدنى انكشف أن عذرهم ستار للنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص289، تحت «دلالة ﴿أو﴾ وبلاغة التعريض في قوله: ﴿قاتلوا في سبيل الله أو ادفعوا﴾».","url":""}]},{"id":"s3-622","number":622,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"ما دلالة قولهم ﴿لو نعلم قتالًا لاتبعناكم﴾ بدل أن يقولوا: لقاتلنا معكم؟","answer":"قالوا ﴿لاتبعناكم﴾ ليظهروا أن امتناعهم تابع لتقدير عسكري لا رفضًا للجماعة، وكأنهم مستعدون للسير خلفهم متى ثبت عندهم القتال؛ لكنهم كانوا يعلمون وقوعه ولا ينوون الاتباع، ففضحت العبارة كذب الشرط والجواب معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص290، تحت «دلالة تعليق الشرط بـ(لو) في قوله تعالى: ﴿لو نعلم قتالًا﴾».","url":""}]},{"id":"s3-623","number":623,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿هم للكفر يومئذ أقرب منهم للإيمان﴾ لا: هم كافرون؟","answer":"لم يحكم على بواطنهم حكمًا مطلقًا، بل وصف ما أظهره موقفهم يومئذ؛ وفي المقارنة كشف لتأرجحهم وغلبة جانب الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص291، تحت «دلالة تقديم ما حقه التأخير في قوله تعالى: ﴿هم للكفر يومئذ أقرب منهم للإيمان﴾».","url":""}]},{"id":"s3-624","number":624,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"أين تتجلى براعة المجاز المرسل في قوله تعالى: ﴿يقولون بأفواههم ما ليس في قلوبهم﴾؟","answer":"ذكر الأفواه مع أن القول لا يكون إلا بها ليصور أن دعواهم بقيت ألفاظًا على الشفاه لا حقيقة لها في القلوب؛ فالمقابلة بين الفم والقلب تكشف انفصال ظاهرهم عن باطنهم، وهو عين النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص293، تحت «براعة المجاز المرسل في قوله تعالى: ﴿يقولون بأفواههم ما ليس في قلوبهم﴾».","url":""}]},{"id":"s3-625","number":625,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"لماذا جاءت خاتمة آل عمران ﴿والله أعلم بما يكتمون﴾، وفي المائدة ﴿والله أعلم بما كانوا يكتمون﴾؟","answer":"في آل عمران كشف موقف عارض اشتد فيه قربهم من الكفر، فجيء بـ﴿يكتمون﴾ لحال كتمانهم؛ أما المائدة فتصف قومًا رسخ تاريخهم في الدخول بالكفر والخروج به، فزادت ﴿كانوا﴾ للدلالة على استمرار الكتمان وتمكنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص295، تحت «توجيه المتشابه اللفظي».","url":""}]},{"id":"s3-626","number":626,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]},{"surah":63,"verses":[1]}],"verseLabel":"آل عمران: 167؛ المنافقون: 1","question":"ما سرّ التعبير بقوله تعالى: في آل عمران ﴿الذين نافقوا﴾، وجاء في السورة الأخرى الاسم الصريح ﴿المنافقون﴾؟","answer":"في آل عمران يصف النص فعلًا ظهر منهم في حادثة أحد، فناسب الموصول والفعل ﴿الذين نافقوا﴾؛ أما سورة المنافقون فتعالج الصفة بعد رسوخها واشتهار أصحابها بها، فجاء اسم الفاعل عنوانًا ثابتًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص286، تحت «سرّ التعبير عن أهل الإيمان بالاسم وعن أهل النفاق بالفعل في قوله تعالى: ﴿وليعلم المؤمنين وليعلم الذين نافقوا﴾».","url":""}]},{"id":"s3-627","number":627,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين قالوا لإخوانهم وقعدوا﴾، دون أن يقال: الذين قعدوا وقالوا؟","answer":"الواو في ﴿وقعدوا﴾ للحال، أي قالوا لإخوانهم هذا الكلام وهم قد قعدوا عن الجهاد؛ فقدم القول لأنه موضع الرد، وذكر القعود حالًا تكشف تناقض من يلوم المقاتلين بعد أن تخلف هو.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص300، تحت «دلالة (أل) في ﴿الذين﴾ في قوله تعالى: ﴿الذين قالوا لإخوانهم وقعدوا﴾».","url":""}]},{"id":"s3-628","number":628,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"لماذا سمّوا المقتولين ﴿إخوانهم﴾ مع تخذيلهم لهم؟","answer":"سماهم إخوانهم لما بينهم من نسب وقوم، أو بحسب أخوة الإسلام التي يظهرها المنافقون؛ وفي التسمية توبيخ خفي: كيف يتخذون الأخوة لسانًا ثم يقعدون ويجعلونها بابًا للوم المقتولين؟","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص300–301، تحت «دلالة الأخوة في قوله تعالى: ﴿الذين قالوا لإخوانهم وقعدوا لو أطاعونا ما قتلوا﴾».","url":""}]},{"id":"s3-629","number":629,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"ما سرّ التعبير بقوله تعالى: لهم ﴿فادرءوا عن أنفسكم الموت إن كنتم صادقين﴾؟","answer":"ألزمهم بنتيجة قولهم: إن كان القعود يرد الموت حقًا فادفعوه عن أنفسكم حين يأتيكم؛ فلما كانوا عاجزين ثبت أن الخروج لم ينشئ الأجل، وأن قولهم ﴿لو أطاعونا ما قتلوا﴾ كذب على القدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص302، تحت «براعة أسلوب البحث في قوله تعالى: ﴿قل فادرؤوا عن أنفسكم الموت إن كنتم صادقين﴾»","url":""}]},{"id":"s3-630","number":630,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"لماذا اختير ﴿ادرءوا﴾ لا: ادفعوا؟","answer":"الدرء دفع الشيء وإبعاده قبل أن يصل، فـ﴿ادرءوا﴾ تصور محاولة اعتراض الموت وصرفه عن النفس قبل وقوعه؛ وهذا أبلغ في التحدي من مجرد دفع غير محدد الجهة أو الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص296–297، تحت «الدفع والرد والدرء».","url":""}]},{"id":"s3-631","number":631,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تحسبن الذين قتلوا في سبيل الله أمواتًا﴾ بصيغة النهي؟","answer":"جاء نهيًا مؤكدًا بالنون ليقتلع الظن الذي روّجه المنافقون أن القتل ضياع، ويوجه الرسول والمؤمنين إلى الحكم المقابل يقينًا: الشهداء ليسوا أمواتًا عند ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص309، تحت «دلالة الخطاب في قوله تعالى: ﴿ولا تحسبن الذين قتلوا في سبيل الله أمواتًا﴾».","url":""}]},{"id":"s3-632","number":632,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"ما دلالة ﴿بل﴾ في قوله تعالى عن الشهداء: ﴿بل أحياء عند ربهم يرزقون﴾؟","answer":"تنقل ﴿بل﴾ الحكم من حسبانهم أمواتًا إلى إثبات الحياة لهم. فمع ثبوت قتل أجسامهم، لهم حياة حقيقية عند ربهم تزيد على مجرد بقاء الأرواح؛ ولذلك وصفوا بأنهم أحياء يرزقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص309–310، تحت عنوان «دلالة الطباق في قول الله تعالى: ﴿ولا تحسبن الذين قتلوا في سبيل الله أمواتًا بل أحياء﴾»","url":""}]},{"id":"s3-633","number":633,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿عند ربهم﴾، دون أن يقال: في الجنة؟","answer":"﴿عند ربهم﴾ تفيد منزلة القرب والتشريف والكرامة مع رعاية الرب لهم، لا مجرد كونهم في مكان نعيم؛ وإضافة ﴿ربهم﴾ إليهم تزيد معنى العناية والتربية الخاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص310–311، تحت «نكتة التعبير بالاسم الأحسن (الرب) وإضافته إلى الضمير العائد على الشهداء».","url":""}]},{"id":"s3-634","number":634,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"لماذا جاء ﴿يرزقون﴾ بالمضارع المبني للمجهول؟","answer":"المضارع يصور رزقهم متجددًا مستمرًا، وبني للمجهول لأن المقصود إبراز دوام ما يصل إليهم من النعيم، مع أن الرازق معلوم من قربه: هم عند ربهم وهو الذي يرزقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص320، تحت «الرزق والنعمة واللذة».","url":""}]},{"id":"s3-635","number":635,"surah":3,"verses":[169],"references":[{"surah":2,"verses":[154]},{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169؛ البقرة: 154","question":"ما سرّ اختلاف التفصيل في شأن الشهداء بين قوله تعالى في البقرة ﴿بل أحياء ولكن لا تشعرون﴾، وقوله تعالى في آل عمران ﴿بل أحياء عند ربهم يرزقون﴾؟","answer":"البقرة جاءت في أول تربية الأمة على البلاء فاكتفت بإثبات حياة لا تدركها الحواس، أما آل عمران فنزلت بعد وقوع القتل في أحد ففصلت تسليةً لأهل الشهداء: قربٌ ورزق وفرح واستبشار؛ فالثانية تفصيل للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص310، تحت «﴿بل أحياء﴾».","url":""}]},{"id":"s3-636","number":636,"surah":3,"verses":[170],"references":[{"surah":3,"verses":[170]}],"verseLabel":"آل عمران: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿فرحين بما آتاهم الله من فضله﴾ لا: بما استحقوا؟","answer":"لأن ما نالوه ليس ثمنًا واجبًا على الله بمجرد عملهم، بل عطاء تفضل به فوق ما يتصورونه؛ فذكر الإيتاء والفضل يرد النعمة إلى واهبها ويضاعف الفرح بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص311، تحت «سر التعبير بالاسم الموصول (ما) في قوله تعالى: ﴿فرحين بما آتاهم الله من فضله﴾».","url":""}]},{"id":"s3-637","number":637,"surah":3,"verses":[170],"references":[{"surah":3,"verses":[170]}],"verseLabel":"آل عمران: 170","question":"ما دلالة التعبير بالاسم الموصول وصلته في قوله تعالى: ﴿ويستبشرون بالذين لم يلحقوا بهم من خلفهم﴾؟","answer":"يفرح الشهداء بإخوانهم المؤمنين الذين بقوا بعدهم ولم يصلوا بعد إلى منزلتهم، لما علموا من حسن ما أعد لهم؛ فـ﴿لم يلحقوا﴾ تصور الفاصل المؤقت وتوقع اجتماع اللاحق بالسابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص312، تحت «دلالة التعبير بالاسم الموصول وصلته في قوله تعالى: ﴿ويستبشرون بالذين لم يلحقوا بهم من خلفهم﴾»","url":""}]},{"id":"s3-638","number":638,"surah":3,"verses":[170],"references":[{"surah":3,"verses":[170]}],"verseLabel":"آل عمران: 170","question":"لماذا نُفي عن اللاحقين الخوف والحزن مع اختلاف زمنيهما؟","answer":"الخوف توقع مكروه آت، والحزن ألم على فائت؛ فنفيهما يؤمن مستقبلهم وماضيهم ويستوعب اضطراب النفس كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص313، تحت «نكتة تقديم نفي الخوف على نفي الحزن في قوله تعالى: ﴿ألا خوف عليهم ولا هم يحزنون﴾».","url":""}]},{"id":"s3-639","number":639,"surah":3,"verses":[171],"references":[{"surah":3,"verses":[171]}],"verseLabel":"آل عمران: 171","question":"لماذا كرر ﴿يستبشرون﴾ في آيتين متتاليتين؟","answer":"الاستبشار الأول بإخوانهم اللاحقين وأمنهم، والثاني بنعمة الله وفضله وعدم ضياع الأجر؛ فأعيد الفعل لأن متعلق الفرح تجدد: فرح بمصير إخوانهم، ثم فرح بما هم فيه من نعمة وضمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص314–315، تحت «فائدة تكرار الفعل ﴿يستبشرون﴾».","url":""}]},{"id":"s3-640","number":640,"surah":3,"verses":[171],"references":[{"surah":3,"verses":[171]}],"verseLabel":"آل عمران: 171","question":"لماذا فُصّل الاستبشار بـ﴿نعمة من الله وفضل﴾، وما الفرق بينهما؟","answer":"النعمة هي ما أنعم الله به عليهم من الحياة والرزق والكرامة، والفضل زيادة الإحسان فوق أصل الجزاء والاستحقاق؛ فجمعهما ليستوعب أصل العطاء وما زاد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص315–316، تحت «نكتة تنكير ﴿نعمة﴾ و﴿فضل﴾، وسر ذكر الخاص بعد العام».","url":""}]},{"id":"s3-641","number":641,"surah":3,"verses":[171],"references":[{"surah":3,"verses":[171]}],"verseLabel":"آل عمران: 171","question":"لماذا ختم بـ﴿وأن الله لا يضيع أجر المؤمنين﴾؟","answer":"ختم بضمان جامع يفسر استبشار الشهداء ويشمل من خلفهم: الله لا يبطل ثواب إيمان أو طاعة، بل يوفي كل مؤمن أجره؛ فكرامة الشهداء مثال على قاعدة حفظ العمل لا حالة منفصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص316، تحت «توجيه القراءات القرآنية في قوله: ﴿وأن الله لا يضيع أجر المؤمنين﴾».","url":""}]},{"id":"s3-642","number":642,"surah":3,"verses":[172],"references":[{"surah":3,"verses":[172]}],"verseLabel":"آل عمران: 172","question":"ما النكتة البلاغية في الوصف في قوله تعالى: ﴿الذين استجابوا لله والرسول﴾؟","answer":"وصفهم بالاستجابة لأنهم لبوا نداء الخروج إلى حمراء الأسد فور أُحد، مع أن جراح المعركة ما زالت فيهم؛ فذكر القرح يعظم طاعتهم، إذ غلبوا الألم والخوف ولم يتخذوه عذرًا للقعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص326، تحت «نكتة الوصف في قوله تعالى: ﴿الذين استجابوا لله والرسول﴾».","url":""}]},{"id":"s3-644","number":644,"surah":3,"verses":[172],"references":[{"surah":3,"verses":[172]}],"verseLabel":"آل عمران: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿للذين أحسنوا منهم واتقوا﴾، فجاء بـ﴿منهم﴾؟","answer":"جاءت ﴿منهم﴾ لتمييز من استمر إحسانه وتقواه داخل جماعة المستجيبين؛ فالأجر العظيم ليس لمجرد الحضور أو الاسم، بل لمن أحسن العمل واتقى المخالفة، وقيل هي لبيان أن هؤلاء هم الجماعة الممدوحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص328، تحت «سبب فصل قول الله تعالى: ﴿للذين أحسنوا منهم واتقوا أجر عظيم﴾ عما قبله».","url":""}]},{"id":"s3-645","number":645,"surah":3,"verses":[172],"references":[{"surah":3,"verses":[172]}],"verseLabel":"آل عمران: 172","question":"لماذا جمع الإحسان والتقوى؟","answer":"لأن الوصفين يجمعان ترك المنكرات وفعل الخيرات؛ فالتقوى باعتبار أصلها اتقاء المنكر، والإحسان عمل الخير بإخلاص ومراقبة لله، فاجتمعت سلامة الترك وحسن العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص754، تحت عنوان «علة الجمع بين صفتي التقوى والإحسان»","url":""}]},{"id":"s3-646","number":646,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"ما دلالة تكرار لفظ ﴿الناس﴾ في قوله تعالى: ﴿الذين قال لهم الناس إن الناس قد جمعوا لكم﴾؟","answer":"«الناس» الأولى ناقل التخويف، والثانية جيش المشركين المجتمع؛ وتكرار اللفظ يضخم التهديد كأن جماعة البشر كلها اجتمعت عليهم، مع اختلاف المراد في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص330–331، تحت «بلاغة المجاز المرسل في قوله تعالى: ﴿الذين قال لهم الناس إن الناس قد جمعوا لكم﴾».","url":""}]},{"id":"s3-647","number":647,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"لماذا زادهم التخويف إيمانًا بدل الخوف؟","answer":"لأن التهديد ردهم إلى يقينهم بأن الله كافيهم، فصار اجتماع الناس عليهم دليلًا جديدًا على صدق الوعد وميدانًا للتوكل، لا سببًا للانهيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص332، تحت «دلالة قوله تعالى: ﴿فزادهم إيمانًا﴾».","url":""}]},{"id":"s3-648","number":648,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"ما دلالة جواب المؤمنين: ﴿حسبنا الله ونعم الوكيل﴾؟","answer":"﴿حسبنا الله﴾ تعلن أن الله وحده كافيهم خطر العدو، و﴿نعم الوكيل﴾ تثني عليه بوصفه خير من يفوض إليه الأمر ويحفظه؛ فكان جوابهم توكلًا عمليًا يقابل التخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص332، تحت «دلالة قوله تعالى: ﴿حسبنا الله ونعم الوكيل﴾».","url":""}]},{"id":"s3-649","number":649,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"لماذا اختير اسم ﴿الوكيل﴾ في هذا الموقف؟","answer":"الوكيل هو من تفوض إليه الأمور فيحفظها ويدبرها ويكفي صاحبها؛ فناسب موقف قوم لا يملكون تقدير قوة العدو ونتيجة المواجهة، فأسندوا الحماية والتدبير إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص332–334، تحت «دلالة قوله تعالى: ﴿حسبنا الله ونعم الوكيل﴾».","url":""}]},{"id":"s3-650","number":650,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿فانقلبوا بنعمة من الله وفضل﴾، فجعل الرجوع انقلابًا؟","answer":"الانقلاب رجوع يصحبه تحول في الحال؛ خرجوا مثقلين بالجراح ومهددين بالعدو، ثم عادوا آمنين سالمين تحيط بهم النعمة والفضل، فدل الفعل على عودتهم وعلى انقلاب الخوف أمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص341–342، تحت «(انقلبوا)، و(رجعوا)» ضمن الفروق المعجمية.","url":""}]},{"id":"s3-652","number":652,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"لماذا جاءت جملة ﴿لم يمسسهم سوء﴾ بين النعمة واتباع الرضوان؟","answer":"توسطت لتبين أثر النعمة المحسوس: عادوا ولم يصبهم أدنى سوء، ثم عطفت المكسب الأعلى وهو اتباع رضوان الله؛ فجمعت سلامة البدن من الضرر وسلامة القصد بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص341، تحت «بلاغة التنكير وفن الاحتراس في قوله تعالى: ﴿لم يمسسهم سوء﴾».","url":""}]},{"id":"s3-653","number":653,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"لماذا ختم بـ﴿والله ذو فضل عظيم﴾؟","answer":"ختم بإرجاع السلامة والنعمة والرضوان والأجر إلى مصدرها: الله صاحب الفضل العظيم؛ فما نالوه تجاوز قدرتهم واستحقاقهم، ويفتح الختام الفضل على ما ذُكر وما لم يذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص192، تحت «بلاغة التذييل بقوله: ﴿والله ذو الفضل العظيم﴾».","url":""}]},{"id":"s3-654","number":654,"surah":3,"verses":[175],"references":[{"surah":3,"verses":[175]}],"verseLabel":"آل عمران: 175","question":"ما سرّ استعمال أداة ﴿إنما﴾؟","answer":"قصر بـ﴿إنما﴾ حقيقة هذا التهويل على وسوسة الشيطان؛ فهو يخوفكم بأوليائه ويضخم قوتهم في نفوسكم، ولذلك جاء التفريع: ﴿فلا تخافوهم﴾، أي لا تستجيبوا للصورة التي صنعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص346، تحت «سر استعمال أداة ﴿إنما﴾».","url":""}]},{"id":"s3-655","number":655,"surah":3,"verses":[175],"references":[{"surah":3,"verses":[175]}],"verseLabel":"آل عمران: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تخافوهم وخافون﴾، فجمع ضميرهم وأفرد ضمير الله؟","answer":"جمع ضمير الأعداء لكثرتهم الظاهرة، ثم أفرد ضمير الله لأن المستحق للخوف واحد؛ فالمقابلة تهدم رهبة العدد: لا تخافوا هذا الجمع، وخافوا الله وحده الذي يملك الأمر كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص348، تحت «فائدة جمع الضمير في قوله: ﴿فلا تخافوهم﴾».","url":""}]},{"id":"s3-656","number":656,"surah":3,"verses":[175],"references":[{"surah":3,"verses":[175]}],"verseLabel":"آل عمران: 175","question":"لماذا عُلّق الأمر بالخوف من الله بقوله ﴿إن كنتم مؤمنين﴾؟","answer":"لأن الإيمان الحق يثمر خوف الله وحده ويمنع خضوع القلب لتهويل الشيطان؛ فالشرط يحرضهم: إن كان الإيمان مستقرًا في قلوبكم فليظهر أثره في ترك خوف العدو والثبات على طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص349–352، تحت «الخوف والخشية».","url":""}]},{"id":"s3-657","number":657,"surah":3,"verses":[176],"references":[{"surah":3,"verses":[176]}],"verseLabel":"آل عمران: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحزنك الذين يسارعون في الكفر﴾، وكيف تكون المسارعة داخل الكفر؟","answer":"جعل الكفر ميدانًا يندفعون في داخله، فالصورة تكشف نشاطهم في أسبابه، ثم تسلّي الرسول بأنهم لا يضرون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص356، تحت «سر التعبير بالاسم الموصول في قوله سبحانه: ﴿الذين يسارعون في الكفر﴾».","url":""}]},{"id":"s3-658","number":658,"surah":3,"verses":[176],"references":[{"surah":3,"verses":[176]}],"verseLabel":"آل عمران: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿إنهم لن يضروا الله شيئًا﴾ لا: لن يضروك؟","answer":"لم يقل «لن يضروك» لأن مسارعتهم ليست اعتداءً شخصيًا على الرسول ﷺ فقط، بل محاولة لمغالبة دين الله؛ فنفى قدرتهم على الإضرار بالله، أي بدينه ووعده، وارتد ضررهم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص356–357، تحت «غرض التعليل في قوله تعالى: ﴿إنهم لن يضروا الله﴾».","url":""}]},{"id":"s3-659","number":659,"surah":3,"verses":[176],"references":[{"surah":3,"verses":[176]}],"verseLabel":"آل عمران: 176","question":"ما وجه البلاغة في فصل جملة ﴿يريد الله ألا يجعل لهم حظًا في الآخرة﴾؟","answer":"كشف عاقبة الإمهال حتى لا يظن نشاطهم نجاحًا: يتركهم الله لاختيارهم حتى يستوفوا طريق الكفر، فتكون النتيجة ألا يبقى لهم نصيب من ثواب الآخرة، بل عذاب عظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص358، تحت «بلاغة فصل جملة ﴿يريد الله ألا يجعل لهم حظًا في الآخرة﴾».","url":""}]},{"id":"s3-660","number":660,"surah":3,"verses":[176],"references":[{"surah":3,"verses":[176]}],"verseLabel":"آل عمران: 176","question":"لماذا سمّى نصيب الآخرة ﴿حظًا﴾؟","answer":"الحظ هو النصيب المقدر من الخير، فنفاه عنهم ليقرر أنهم لا يملكون في الآخرة أدنى سهم من النعيم أو الثواب؛ وتنكيره في سياق النفي يعم القليل والكثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص358، تحت «غرض تنكير ﴿حظ﴾ ونكتة تأخيره عن ﴿لهم﴾».","url":""}]},{"id":"s3-661","number":661,"surah":3,"verses":[177],"references":[{"surah":3,"verses":[177]}],"verseLabel":"آل عمران: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿اشتروا الكفر بالإيمان﴾، وكيف يُشترى الكفر؟","answer":"صور تركهم الإيمان واختيارهم الكفر بصفقة: دفعوا الإيمان ثمنًا وأخذوا الكفر بدلًا منه؛ فالفعل يثبت أنهم اختاروا الخسارة بإرادتهم، لا أنهم وقعوا فيها بلا قصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص361–362، تحت «بلاغة الاستعارة في قوله تعالى: ﴿اشتروا﴾».","url":""}]},{"id":"s3-662","number":662,"surah":3,"verses":[177],"references":[{"surah":3,"verses":[177]}],"verseLabel":"آل عمران: 177","question":"لماذا أعاد ﴿لن يضروا الله شيئًا﴾؟","answer":"أعيد لأن السياق انتقل من المسارعة في الكفر إلى صفقة استبدال الإيمان به؛ فمهما تعددت صور الكفر لا ينال ضررها دين الله أو ملكه، وإنما يرجع على أصحابها بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص362، تحت «المبالغة في تعليل النهي في قوله تعالى: ﴿إنهم لن يضروا الله شيئًا﴾».","url":""}]},{"id":"s3-663","number":663,"surah":3,"verses":[177],"references":[{"surah":3,"verses":[177]}],"verseLabel":"آل عمران: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿ولهم عذاب أليم﴾ بعد نفي الضرر عن الله؟","answer":"لما نفى أن يبلغ ضررهم الله، بيّن أين يقع الضرر حقيقة: عليهم هم؛ فتقديم ﴿لهم﴾ يخصهم بالعذاب، و﴿أليم﴾ يقابل وهم القوة بألم العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص362، تحت «المبالغة في تعليل النهي في قوله تعالى: ﴿إنهم لن يضروا الله شيئًا﴾».","url":""}]},{"id":"s3-664","number":664,"surah":3,"verses":[178],"references":[{"surah":3,"verses":[178]}],"verseLabel":"آل عمران: 178","question":"كيف يُوجَّه بلاغيًا عطف قوله تعالى: ﴿ولا يحسبن الذين كفروا﴾؟","answer":"نهاهم أن يظنوا أن تمديد العمر وإرخاء المهلة دليل خير أو رضا؛ فقد يكون الإملاء استدراجًا يتيح لهم الإصرار حتى تتراكم تبعة اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص364، تحت «توجيه عطف قوله تعالى: ﴿ولا يحسبن الذين كفروا﴾».","url":""}]},{"id":"s3-665","number":665,"surah":3,"verses":[178],"references":[{"surah":3,"verses":[178]}],"verseLabel":"آل عمران: 178","question":"لماذا كرر ﴿إنما نملي لهم﴾ بعد ذكر الإملاء أولًا؟","answer":"ذُكر الإملاء أولًا داخل ظنهم أنه خير، ثم أعيد بـ﴿إنما﴾ ليصحح ذلك الظن ويقصر حقيقته في حالهم على تمكينهم من زيادة الإثم؛ فالثاني تفسير حاسم للأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص366–367، تحت «بلاغة قوله تعالى: ﴿إنما نملي لهم ليزدادوا إثمًا﴾».","url":""}]},{"id":"s3-666","number":666,"surah":3,"verses":[178],"references":[{"surah":3,"verses":[178]}],"verseLabel":"آل عمران: 178","question":"لماذا عُلّل الإمهال بقوله ﴿ليزدادوا إثمًا﴾؟","answer":"أي يمد لهم في الزمن وهم يختارون الكفر، فتكون نتيجة الإمهال ازدياد إثمهم بأفعالهم؛ فاللام للعاقبة أو الغاية بحسب التوجيه، ولا تعني إجبارهم على المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص366، تحت «بلاغة قوله تعالى: ﴿إنما نملي لهم ليزدادوا إثمًا﴾».","url":""}]},{"id":"s3-667","number":667,"surah":3,"verses":[178],"references":[{"surah":3,"verses":[178]}],"verseLabel":"آل عمران: 178","question":"لماذا وصف العذاب هنا بـ﴿مهين﴾؟","answer":"لأنهم اغتروا بالمهلة وعدوها كرامة وقوة، فجاء العذاب مهينًا يسلبهم العزة الموهومة ويقابل استكبارهم بالذل، مع ما فيه من الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص362–363، تحت «مناسبة الآية لما قبلها» في قوله تعالى: ﴿ولهم عذاب مهين﴾.","url":""}]},{"id":"s3-669","number":669,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"ما معنى اللام في قوله: ﴿ليذر المؤمنين﴾؟","answer":"الصيغة تنفي وتستبعد أن يترك الله الجماعة على حال اختلاط الصادق بالمنافق؛ فحكمته تقتضي أحداثًا وابتلاءات تظهر الخبيث من الطيب، لا دوام الاشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص372، تحت «معنى اللام في قوله: ﴿ليذر المؤمنين﴾».","url":""}]},{"id":"s3-670","number":670,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"لماذا انتقل من الغيبة في ﴿المؤمنين﴾ إلى الخطاب في ﴿ما أنتم عليه﴾؟","answer":"بدأ باسم المؤمنين لتقرير سنة عامة في جماعتهم، ثم التفت إلى ﴿أنتم﴾ ليواجه أهل المدينة مباشرة بحال اختلاطهم يومئذ؛ فصار الخبر حكمًا عامًا وتنبيهًا شخصيًا في آن.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص373، تحت «براعة الالتفات في إفادة الإيجاز».","url":""}]},{"id":"s3-671","number":671,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يميز الخبيث من الطيب﴾، ومن الخبيث والطيب هنا؟","answer":"المراد أن تكشف المحنة المنافق الخبيث من المؤمن الطيب، أو الكفر من الإيمان وآثارهما؛ فاستعير وصفا الخبث والطيب من الأشياء المحسوسة للنفوس والأعمال بحسب فسادها وصلاحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص374، تحت «نكتة إفراد الخبيث والطيب».","url":""}]},{"id":"s3-672","number":672,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"لماذا نفى إطلاع الناس على الغيب ثم أثبت اجتباء الرسل؟","answer":"نفى أن يكون الغيب مباحًا للبشر ابتداءً، ثم بيّن الاستثناء المنضبط: الله يختار من رسله من يطلعه على قدر يؤدي به الرسالة؛ فلا تناقض بين النفي والاجتباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص376، تحت «سر التعبير بلفظ الاجتباء في قوله تعالى: ﴿ولكن الله يجتبي من رسله﴾».","url":""}]},{"id":"s3-673","number":673,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿يجتبي من رسله من يشاء﴾ لا: يختار؟","answer":"الاجتباء اختيار خاص يصحبه اصطفاء وتقريب وضم إلى صفوة الله؛ فليس كل اختيار اجتباءً، ولذلك ناسب الرسل الذين يخصهم الله بحمل الوحي وبما يشاء من الغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص376، تحت «سر التعبير بلفظ الاجتباء في قوله تعالى: ﴿ولكن الله يجتبي من رسله﴾».","url":""}]},{"id":"s3-674","number":674,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"لماذا ختم بـ﴿وإن تؤمنوا وتتقوا فلكم أجر عظيم﴾؟","answer":"بدل الانشغال بطلب الغيب وتمييز السرائر، ردهم إلى ما يستطيعونه ويكلفون به: صدق الإيمان ولزوم التقوى؛ فمن حققهما فله الأجر العظيم وإن خفيت عليه بواطن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص377، تحت «قوة تفريع شرط الإيمان على الأمر بالإيمان».","url":""}]},{"id":"s3-675","number":675,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"ما نوع عطف قوله: ﴿ولا يحسبن الذين يبخلون﴾؟","answer":"نهى البخلاء أن يظنوا أن احتباس المال وحفظه ينفعهم؛ فما أمسكوه من عطاء الله لا يبقى لهم، بل يتحول يوم القيامة عقوبة ملازمة، فصحح مقياس الربح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص383–384، تحت «نوع عطف قوله: ﴿ولا يحسبن الذين يبخلون﴾».","url":""}]},{"id":"s3-676","number":676,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿بما آتاهم الله من فضله﴾، دون أن يقال: بأموالهم؟","answer":"لم يسم المال مالهم حتى لا يتوهموا استقلال الملك؛ إنه ما آتاهم الله تفضلًا، فالبخل حبس لنعمة المالك الحقيقي عن الحق الذي أمر به، وفي اللفظ تقبيح للجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص383–384، تحت «نكتة اختيار لفظ الإيتاء في قوله: ﴿بما آتاهم الله﴾».","url":""}]},{"id":"s3-677","number":677,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"لماذا أعقب ﴿هو خيرًا لهم﴾ بقوله ﴿بل هو شر لهم﴾؟","answer":"أبطلت ﴿بل﴾ ظنهم ولم تكتف بنفي الخير، بل أثبتت ضده: عين المال أو البخل الذي عدوه نفعًا هو شر عليهم؛ فانتقل الحكم من الوهم إلى الحقيقة المقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص384، تحت «فائدة الإضراب والتنوين في قوله: ﴿بل هو شر لهم﴾».","url":""}]},{"id":"s3-678","number":678,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"لماذا صوّر مال البخيل بقوله ﴿سيطوقون ما بخلوا به﴾؟","answer":"حوّل المال المحبوب إلى طوق ملازم خانق يوم القيامة؛ فالعقوبة من جنس تعلقهم بما منعوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص384–385، تحت «براعة المباغتة في الوعيد، وحسن التفسير بالتمثيل البليغ».","url":""}]},{"id":"s3-679","number":679,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"لماذا ختم بـ﴿ولله ميراث السماوات والأرض﴾؟","answer":"لأن البخيل سيترك ما أمسكه ويموت، بينما الملك كله يرجع ويبقى لله؛ فتقديم ﴿لله﴾ يقصر الميراث الحقيقي عليه، ويجعل حبس المال عن حقه وهمًا قصيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص385–386، تحت «فائدة تقديم لفظ الجلالة في قوله: ﴿ولله ميراث السماوات والأرض﴾».","url":""}]},{"id":"s3-680","number":680,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد سمع الله قول الذين قالوا﴾ مع أن الله يسمع كل شيء؟","answer":"التوكيد والقول المكرر يثبتان أن الكلمة لم تضع، ويحوّلان ما حسبوه حديثًا عابرًا إلى جريمة محفوظة محاسب عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص392، تحت «علة التعبير بلفظ السمع».","url":""}]},{"id":"s3-681","number":681,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"لماذا حكى مقالتهم البشعة نصًا: ﴿إن الله فقير ونحن أغنياء﴾؟","answer":"حكاها نصًا لتقوم الحجة بعين لفظهم، ولتظهر شناعة الافتراء والمفاخرة: أكدوا بـ﴿إن﴾ زعم فقر الله، وجاؤوا بواو الحال في ﴿ونحن أغنياء﴾ ليجعلوا غناهم الموهوم في مقابلة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص392، تحت «بلاغة توكيد المقولة».","url":""}]},{"id":"s3-682","number":682,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿سنكتب ما قالوا﴾، وكيف يُكتب القول؟","answer":"أي سنثبت مقالتهم ونحفظها في صحائف أعمالهم لتبقى حجة عليهم ويجازوا بها؛ فالقول يكتب بكتابة ألفاظه وإثبات تبعته، والسين وعيد بأن الجريمة لن تنسى أو تهمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص392، تحت «دلالة السين في فعل الكتابة».","url":""}]},{"id":"s3-683","number":683,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"لماذا عطف ﴿وقتلهم الأنبياء بغير حق﴾ على مقالتهم؟","answer":"لأن جرأة اللسان في قولهم على الله امتداد لجرأة الفعل على رسله؛ فجمع شاهد العقيدة الفاسدة وشاهد التاريخ الإجرامي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص393، تحت «بلاغة العطف في جملة قتل الأنبياء».","url":""}]},{"id":"s3-684","number":684,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما دلالة وجوه المبالغة في مقولة إذاقة عذاب الحريق في قوله تعالى: ﴿ونقول ذوقوا عذاب الحريق﴾؟","answer":"استعير ﴿ذوقوا﴾ للمباشرة والإحساس الذي يختبره المعذب بنفسه، فصار العذاب كأنه شيء يباشر أثره ولا يسمع خبره فقط؛ و﴿الحريق﴾ نار ملتهبة تحرق وتلازم الإحراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص394، تحت «وجوه المبالغة في مقولة إذاقة عذاب الحريق».","url":""}]},{"id":"s3-685","number":685,"surah":3,"verses":[182],"references":[{"surah":3,"verses":[182]}],"verseLabel":"آل عمران: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك بما قدمت أيديكم﴾ مع أن الذنوب ليست كلها باليد؟","answer":"الأيدي كناية عن الإنسان وأعماله لأنها أبرز آلات الكسب والمباشرة؛ فالمعنى: ذلك بسبب ما عملتموه باختياركم، لا أن كل ذنب وقع بالجارحة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص395، تحت «بديع المجاز في لفظ الأيدي».","url":""}]},{"id":"s3-686","number":686,"surah":3,"verses":[182],"references":[{"surah":3,"verses":[182]}],"verseLabel":"آل عمران: 182","question":"لماذا عبّر عن الأعمال الماضية بأنها ﴿قدمت﴾؟","answer":"لأن الأعمال تسبق أصحابها إلى موقف الحساب كأنهم أرسلوها أمامهم، ثم يلقون ما ترتب عليها؛ فـ﴿قدمت﴾ تصل فعل الدنيا بنتيجته الآتية في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص395، تحت «بديع المجاز في لفظ الأيدي».","url":""}]},{"id":"s3-687","number":687,"surah":3,"verses":[182],"references":[{"surah":3,"verses":[182]}],"verseLabel":"آل عمران: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿وأن الله ليس بظلام للعبيد﴾ بصيغة المبالغة؟","answer":"جاءت الصيغة باعتبار كثرة العبيد وكثرة ما يحكم فيه بينهم؛ فنفى الله عن نفسه تكرر الظلم أو وقوع شيء منه في أي عبد، فالعذاب أثر ما قدموه لا جور في الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص397، تحت «فائدة التعبير بصيغة المبالغة في ﴿بظلام﴾».","url":""}]},{"id":"s3-688","number":688,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما دلالة نسبتهم طلبهم إلى عهد إلهي في قولهم: ﴿إن الله عهد إلينا﴾؟","answer":"نسبوا اشتراطهم إلى عهد من الله ليصوروا امتناعهم من التصديق التزامًا دينيًا لا تعنتًا منهم؛ فجاء الرد بتكذيب دعواهم من تاريخهم مع الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص404–405، تحت «بلاغة التضمين في جملة العهد».","url":""}]},{"id":"s3-689","number":689,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما سرّ اشتراطهم قربانًا ﴿تأكله النار﴾؟","answer":"زعموا أن علامة الرسول المقبول أن يقدم ما يتقرب به إلى الله، فتنزل نار فتستوفيه وتحرقه؛ فجعلوا أكل النار للقربان آية حسية اشترطوها للإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص405–406، تحت «بلاغة المجاز والاستعارة في أكل النار».","url":""}]},{"id":"s3-691","number":691,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما دلالة ختام الرد بقوله تعالى: ﴿فلم قتلتموهم إن كنتم صادقين﴾؟","answer":"ختم باستفهام تقريعي يلزمهم بتاريخهم: إن كان الامتناع سببه حقًا غياب القربان، فلم قتل أسلافكم رسلًا جاؤوا به؟ فالشرط يهدم صدق الدعوى بالفعل المناقض لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص407–408، تحت «الشرط، وأثره في تجلية المعنى».","url":""}]},{"id":"s3-692","number":692,"surah":3,"verses":[184],"references":[{"surah":3,"verses":[184]}],"verseLabel":"آل عمران: 184","question":"ما دلالة قوله تعالى: ﴿فإن كذبوك فقد كذب رسل من قبلك﴾ في تسلية النبي ﷺ؟","answer":"سلاه بأن التكذيب ليس خاصًا به ولا ناشئًا عن نقص في بيانه؛ فقد وقع لرسل قبله جاءوا بأجناس الحجج والوحي، فله في ثباتهم أسوة وعاقبة المكذبين معلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص408، تحت «دلالة الفاء في جملة الشرط».","url":""}]},{"id":"s3-693","number":693,"surah":3,"verses":[184],"references":[{"surah":3,"verses":[184]}],"verseLabel":"آل عمران: 184","question":"ما دلالة الجمع بين ﴿البينات والزبر والكتاب المنير﴾؟","answer":"جمع أجناس الحجة التي جاء بها الرسل: دلائل ومعجزات ظاهرة، وصحفًا مكتوبة فيها المواعظ، وكتابًا وحيانيًا ينير طريق الحق؛ فالتكذيب وقع مع اكتمال البرهان والتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص409، تحت «فائدة العطف في الآية».","url":""}]},{"id":"s3-694","number":694,"surah":3,"verses":[184],"references":[{"surah":3,"verses":[184]}],"verseLabel":"آل عمران: 184","question":"ما سرّ وصف الكتاب بـ﴿المنير﴾؟","answer":"لأنه يبين الحق ويفصل الهدى من الضلال، فشبه أثره في البصائر بأثر النور في الأبصار؛ لا يترك طالب الحق في ظلمة الالتباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص410–411، تحت «بيان المجاز في وصف المنير».","url":""}]},{"id":"s3-695","number":695,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿كل نفس ذائقة الموت﴾، وهل الموت يُذاق؟","answer":"استعير الذوق للمباشرة الشخصية التي لا ينوب فيها أحد عن أحد؛ واسم الفاعل يقرر تحقق التجربة لكل نفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص417، تحت «بلاغة المجاز في لفظ التذوق».","url":""}]},{"id":"s3-696","number":696,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿ذائقة﴾ باسم الفاعل لا: تذوق؟","answer":"اسم الفاعل في ﴿ذائقة﴾ يثبت الصفة لصاحبها ويقرر تحققها، وهو أرسخ من فعل عابر مقيد بزمن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–421، تحت «وجه التحقيق في جملة المجازاة».","url":""}]},{"id":"s3-697","number":697,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما دلالة القصر في قوله تعالى: ﴿وإنما توفون أجوركم يوم القيامة﴾ مع وجود جزاء في الدنيا؟","answer":"﴿إنما﴾ تقصر تمام الاستيفاء على يوم القيامة: هناك تعطى الأجور كاملة بلا نقص، أما ما يقع في الدنيا أو البرزخ فبعض الجزاء أو مقدماته، فلا يناقض التوفية الأخيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418، تحت «براعة أسلوب القصر».","url":""}]},{"id":"s3-698","number":698,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما سرّ تصوير النجاة بقوله تعالى: ﴿فمن زحزح عن النار﴾؟","answer":"الزحزحة تنحية بجذب متكرر عاجل، فصورت الإنسان مشرفًا على نار هائلة لا يبعد عنها إلا بجهد ورحمة متجددة؛ لذلك كان مجرد إبعاده عنها فوزًا عظيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص419، تحت «سر إيثار فعل الزحزحة».","url":""}]},{"id":"s3-699","number":699,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"لماذا قدّم الزحزحة عن النار على إدخال الجنة؟","answer":"لأن النجاة من أعظم مرهوب مقدمة الفوز، ثم يكتمل بإدخال الجنة؛ فجمع دفع الشر وجلب الخير ورتبهما بحسب المرور يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص419، تحت «سر إيثار فعل الزحزحة».","url":""}]},{"id":"s3-700","number":700,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما دلالة الإيجاز والتوكيد في قوله تعالى: ﴿فقد فاز﴾؟","answer":"﴿قَدْ﴾ تحقق الفوز، والفعل الموجز ﴿فَازَ﴾ يجمع النجاة من المكروه والظفر بالمطلوب: الزحزحة عن النار ودخول الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص420، تحت «بلاغة الإيجاز في جملة المجازاة».","url":""}]},{"id":"s3-701","number":701,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما سرّ وصف الحياة الدنيا بأنها ﴿متاع الغرور﴾؟","answer":"لأنها منفعة مؤقتة تشبه سلعة يدلس بها على المشتري فيعجب بظاهرها ثم يتبين زوالها؛ فالإضافة تكشف أن التعلق بها ناشئ من غرورها، لا من دوام حقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص421، تحت «براعة الاستعارة، أو التشبيه البليغ في الفاصلة».","url":""}]},{"id":"s3-702","number":702,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]},{"surah":21,"verses":[35]},{"surah":29,"verses":[57]}],"verseLabel":"آل عمران: 185؛ الأنبياء: 35؛ العنكبوت: 57","question":"لماذا تكررت ﴿كل نفس ذائقة الموت﴾ ثم اختلف ما بعدها في آل عمران والأنبياء والعنكبوت؟","answer":"آل عمران في سياق العمل والجزاء فأتبعها بتوفية الأجور والفوز، والأنبياء في سياق الابتلاء فأتبعها بفتنة الخير والشر، والعنكبوت في سياق الهجرة والرجوع فأتبعها بالرجوع إلى الله؛ فالحقيقة الواحدة صارت مدخلًا للغرض الذي تعالجه كل سورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–422، تحت «براعة الاستعارة، أو التشبيه البليغ في الفاصلة».","url":""}]},{"id":"s3-703","number":703,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"لماذا قدّم الابتلاء في الأموال على الأنفس؟","answer":"قدم المال على النفس على سبيل الترقي من الأدنى إلى الأشرف والأعز؛ فابتلاء المال شديد، ثم يبلغ الابتلاء ذروته حين يمس النفس بالجراح والمرض والقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص426، تحت «نكتة تقديم الأموال على الأنفس».","url":""}]},{"id":"s3-704","number":704,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"ما دلالة توكيد الابتلاء بلام القسم ونون التوكيد في ﴿لتبلون﴾ و﴿لتسمعن﴾؟","answer":"أكدهما بلام القسم ونون التوكيد الثقيلة ليوقن المؤمنون أن الابتلاء والأذى واقعان، فلا يفاجئهم وقوعهما، ويتهيؤوا لهما بالصبر والتقوى والاعتماد على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص425–426، تحت «بلاغة تأكيد المطلع».","url":""}]},{"id":"s3-705","number":705,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتسمعن... أذى كثيرًا﴾، فجعل الأذى مسموعًا؟","answer":"لأن الأذى هنا قول يطعن في الدين والكتاب والرسول، فسمعوا الكلام المؤذي نفسه؛ لذلك جعل ﴿أذى﴾ مفعولًا للسماع، ووصفه بالكثرة لتعدد قدره وأنواعه وطرائقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص427، تحت «علة التعبير عن نزول الأذى بسماعه».","url":""}]},{"id":"s3-706","number":706,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"لماذا جمع أذى أهل الكتاب والمشركين في آية واحدة؟","answer":"ليتهيأ المؤمنون لاجتماع مصادر العداوة المختلفة على أذاهم، فلا يفاجئهم صدوره ممن عنده كتاب ولا ممن يعلن الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص426–427، تحت «وجه التفريق بين من أوتوا الكتاب ومن أشركوا».","url":""}]},{"id":"s3-707","number":707,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"ما دلالة العزم والحزم في قوله تعالى: ﴿وإن تصبروا وتتقوا فإن ذلك من عزم الأمور﴾؟","answer":"الصبر يضبط احتمال الأذى، والتقوى تضبط الرد عليه، ووصفهما بالعزم لأن الثبات الأخلاقي عند الاستفزاز يحتاج إرادة راسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص431–434، تحت «العزم والحزم».","url":""}]},{"id":"s3-708","number":708,"surah":3,"verses":[187],"references":[{"surah":3,"verses":[187]}],"verseLabel":"آل عمران: 187","question":"ما دلالة الميثاق على العموم في قوله تعالى: ﴿وإذ أخذ الله ميثاق الذين أوتوا الكتاب﴾؟","answer":"استحضر وقت أخذ الله العهد المؤكد على علماء أهل الكتاب أن يبينوا ما في كتابهم ولا يكتموه؛ فذكر الميثاق يجعل كتمانهم خيانة لعهد معلوم، لا مجرد تقصير عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص435، تحت «دلالة الميثاق على العموم».","url":""}]},{"id":"s3-709","number":709,"surah":3,"verses":[187],"references":[{"surah":3,"verses":[187]}],"verseLabel":"آل عمران: 187","question":"ما دلالة تقديم ﴿لتبيننه للناس﴾ على ﴿ولا تكتمونه﴾؟","answer":"لأن الأمر بالبيان العام هو الأصل الأعم، وثبوته يستلزم ترك الكتمان؛ ثم صرح بالنهي عن الكتمان دفعًا لتوهم أن يكفي بيان بعض الحق لبعض الناس مع إخفاء بقيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص437، تحت «سر تقديم التبيان على عدم الكتمان».","url":""}]},{"id":"s3-710","number":710,"surah":3,"verses":[187],"references":[{"surah":3,"verses":[187]}],"verseLabel":"آل عمران: 187","question":"لماذا صوّر ترك الميثاق بقوله ﴿فنبذوه وراء ظهورهم﴾؟","answer":"صوّر إهمال الميثاق بكتاب يُرمى خلف الظهر فلا يُرى ولا يُرجع إليه؛ وهي أبلغ من مجرد الترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص438–439، تحت «بلاغة الاستعارة الترشيحية في لفظ النبذ».","url":""}]},{"id":"s3-711","number":711,"surah":3,"verses":[187],"references":[{"surah":3,"verses":[187]}],"verseLabel":"آل عمران: 187","question":"ما وجه البلاغة في المجاز المرسل في لفظ الاشتراء في قوله تعالى: ﴿واشتروا به ثمنًا قليلًا﴾؟","answer":"صور خيانتهم صفقة: بذلوا الميثاق وما في الكتاب ثمنًا، وأخذوا مقابله رشى وجاهًا ومنافع دنيوية زائلة؛ فسمي العوض قليلًا لهوانه أمام الحق الذي فرطوا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص439، تحت «بلاغة المجاز المرسل في لفظ الاشتراء».","url":""}]},{"id":"s3-714","number":714,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"ما دلالة الجمع بين قوله تعالى: ﴿يفرحون بما أتوا﴾ و﴿يحبون أن يحمدوا بما لم يفعلوا﴾؟","answer":"علق الحكم بموصول يجمع خصلتين: الإعجاب بما أتوه من باطل، وطلب الحمد على خير لم يفعلوه؛ ثم نهى عن حسبان نجاتهم ليهدم تزكيتهم لأنفسهم واغترارهم بثناء الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص446–447، تحت «سر التعبير بالاسم الموصول».","url":""}]},{"id":"s3-715","number":715,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"لماذا جمع بين الفرح بالعمل وحب الحمد بغير عمل؟","answer":"الأول إعجاب بالباطل الذي فعلوه، والثاني طلب منزلة لم يحققوها؛ فجمع فساد تقييم العمل وفساد طلب السمعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص446–447، تحت «سر التعبير بالاسم الموصول».","url":""}]},{"id":"s3-716","number":716,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"ما دلالة تكرار النهي في قوله تعالى: ﴿فلا تحسبنهم بمفازة من العذاب﴾ بعد قوله: ﴿لا تحسبن الذين يفرحون﴾؟","answer":"طالت الصلة بذكر حالين، فأعيد النهي في ﴿فَلَا تَحْسَبَنَّهُمْ﴾ لتجديد التحذير وإبراز نتيجته: أنهم ليسوا بمنجاة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص447، تحت «سر إعادة فعل الحسبان».","url":""}]},{"id":"s3-717","number":717,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿بمفازة من العذاب﴾، فجعل النجاة مكانًا؟","answer":"المفازة مصدر للفوز والسلامة، وتستعمل أيضًا لمكان النجاة؛ فصورهم كمن يطلب موضعًا آمنًا يفصل بينه وبين العذاب، ثم نفى أن يكونوا في شيء من ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص451، تحت «مفازة ومنجاة».","url":""}]},{"id":"s3-718","number":718,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"ما مناسبة ختام الآية بقوله تعالى: ﴿ولهم عذاب أليم﴾؟","answer":"لم يكتف بنفي المفازة، بل أثبت لهم العذاب اختصاصًا بتقديم ﴿لهم﴾، ووصفه بـ﴿أليم﴾ أي ثابت الألم شديده؛ فانتقل من إبطال وهم النجاة إلى تقرير المصير المقابل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص449، تحت «بلاغة التوكيد في الفاصلة».","url":""}]},{"id":"s3-719","number":719,"surah":3,"verses":[189],"references":[{"surah":3,"verses":[189]}],"verseLabel":"آل عمران: 189","question":"لماذا تكرر تقرير ملك السماوات والأرض قبيل آيات التفكر؟","answer":"ليجعل النظر في الكون نظرًا في ملك الله وآيات قدرته لا تأملًا منفصلًا عن العبادة، وليمهد للاستدلال من الخلق على الحكمة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص455، تحت «بلاغة الوصل في الآية».","url":""}]},{"id":"s3-720","number":720,"surah":3,"verses":[189],"references":[{"surah":3,"verses":[189]}],"verseLabel":"آل عمران: 189","question":"ما مناسبة الجمع بين ملك السماوات والأرض والقدرة على كل شيء في قوله تعالى: ﴿ولله ملك السماوات والأرض والله على كل شيء قدير﴾؟","answer":"ملك السماوات والأرض يثبت شمول السلطان، والقدرة على كل شيء تثبت نفاذه؛ فليس بعسير على مالك الكون أن يبعث الخلق ويحاسبهم، وهي مناسبة لما قبلها ولآيات التفكر بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص455، تحت «بلاغة الوصل في الآية».","url":""}]},{"id":"s3-721","number":721,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما دلالة التوكيد والجمع في قوله تعالى: ﴿إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات﴾؟","answer":"أكدت الجملة بـ﴿إِنَّ﴾ واللام، وجمعت ﴿آيَاتٍ﴾؛ لأن في أصل الخلق وتعاقب الليل والنهار دلائل كثيرة متجددة، لا علامة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص461، تحت «بديع التوكيد في مطلع الآية».","url":""}]},{"id":"s3-722","number":722,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"لماذا قدّم خلق السماوات والأرض على اختلاف الليل والنهار؟","answer":"قدم الأصل الجامع، وهو إنشاء جرمي السماوات والأرض، ثم ذكر الظاهرة المتجددة الواقعة فيهما، وهي تعاقب الليل والنهار؛ فانتقل من إيجاد محل الآيات إلى نظامها المشاهد المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص458–460، تحت «مناسبة الآية لما قبلها» في قوله تعالى: ﴿إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات لأولي الألباب﴾.","url":""}]},{"id":"s3-723","number":723,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سرّ تخصيص الانتفاع بهذه الآيات بـ﴿أولي الألباب﴾؟","answer":"لأن أولي الألباب هم أصحاب العقول الصافية من شوائب الكبر والعناد، فيعبرون من مشاهدة الخلق إلى معرفة الخالق؛ وفي التخصيص تعريض بمن يرى الآيات ولا ينتفع بعقله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص465، تحت «الألباب والعقول».","url":""}]},{"id":"s3-724","number":724,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما دلالة ترتيب أحوال الذكر في قوله تعالى: ﴿قيامًا وقعودًا وعلى جنوبهم﴾؟","answer":"رتب أشهر هيئات الإنسان من الأكمل قدرة إلى ما دونها: قائمًا، ثم قاعدًا، ثم مضطجعًا على جنبه؛ ليدل على دوام ذكر الله في جميع الأحوال وعدم سقوطه بالعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص469–470، تحت «بلاغة الفصل في الآية».","url":""}]},{"id":"s3-725","number":725,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"لماذا انتقل من ذكر الله إلى التفكر في خلق السماوات والأرض؟","answer":"لأن الذكر يوقظ القلب والتفكر يقيم الدليل في العقل؛ وباجتماعهما تتحول مشاهدة الكون إلى معرفة وخشية ودعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص473، تحت «التفكر والتدبر».","url":""}]},{"id":"s3-726","number":726,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما دلالة اسم الإشارة المفرد في دعائهم: ﴿ربنا ما خلقت هذا باطلًا﴾؟","answer":"أفرد اسم الإشارة لأن السماوات والأرض واختلاف الليل والنهار نُظر إليها كنظام كوني واحد متماسك يشهد بالحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص472، تحت «سر التعبير باسم الإشارة».","url":""}]},{"id":"s3-727","number":727,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما مناسبة قولهم ﴿سبحانك﴾ بين الاعتراف بحكمة الخلق وطلب الوقاية من النار؟","answer":"لما قرروا أن الخلق ليس باطلًا، نزهوا الله بـ﴿سبحانك﴾ عن العبث وكل ما لا يليق بحكمته؛ ثم بنوا على هذا اليقين طلب الوقاية من النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص472، تحت «نكتة التعبير بالمصدر: ﴿سبحانك﴾».","url":""}]},{"id":"s3-728","number":728,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما مناسبة دعائهم: ﴿فقنا عذاب النار﴾ بعد التفكر في الكون؟","answer":"لأن التفكر أوصلهم إلى أن الخلق لحكمة وأن وراءه حسابًا؛ ففرعوا بالفاء على هذا الإقرار دعاء الوقاية من عذاب النار، لتصير المعرفة عملًا وخشية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص473، تحت «سر استعمال الفاء».","url":""}]},{"id":"s3-729","number":729,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما سرّ التعبير في قوله تعالى: ﴿إنك من تدخل النار فقد أخزيته﴾، فجعل دخول النار خزيًا؟","answer":"لأن دخول النار يجمع ألم العقوبة بانكشاف الخسارة والذل أمام الخلق؛ فالخزي انكسار وافتضاح وهوان، ومن أدخله الله النار فقد بلغ به ذلك غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص479، تحت «نكتة اصطفاء لفظي (الإدخال، والخزي) في مورد العذاب».","url":""}]},{"id":"s3-730","number":730,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما دلالة الجمع ودخول ﴿من﴾ في قوله تعالى: ﴿وما للظالمين من أنصار﴾؟","answer":"جمع ﴿أنصار﴾ ليستغرق كل صور النصرة والأعوان، وزيدت ﴿من﴾ في سياق النفي لتقرر أنه لا يوجد للظالمين ناصر واحد فضلًا عن جماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص479–480، تحت «بلاغة التعبير بلفظ ﴿للظالمين﴾».","url":""}]},{"id":"s3-731","number":731,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة الجمع بين الاسم والفعل من مادة واحدة في قوله تعالى: ﴿إننا سمعنا مناديًا ينادي للإيمان﴾؟","answer":"الجمع بين ﴿مُنَادِيًا﴾ و﴿يُنَادِي﴾ يثبت ذات المنادي ويستحضر تجدد ندائه، فيبرز قوة الدعوة ووضوح وصولها إلى السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص487، تحت «فائدة الجمع بين ﴿مناديًا﴾ و﴿ينادي﴾».","url":""}]},{"id":"s3-732","number":732,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"لماذا لم يصرّحوا باسم المنادي؟","answer":"لأن المقصود مضمون النداء وأثره لا ذات المنادي، ولأن إبهامه يفخمه: منادٍ عظيم الشأن يدعو إلى أعظم مطلوب وهو الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص486، تحت «نكتة تنوين لفظ المنادي».","url":""}]},{"id":"s3-733","number":733,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة تفسير النداء بقوله تعالى: ﴿أن آمنوا بربكم فآمنا﴾؟","answer":"جاءت ﴿أن آمنوا﴾ تفسيرًا لمضمون النداء حتى لا يبقى مجملًا، ثم دلت الفاء في ﴿فآمنا﴾ على أنهم بادروا إلى الامتثال فور سماعه بلا مكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص486، تحت «دلالة النداء للإيمان».","url":""}]},{"id":"s3-734","number":734,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"لماذا رتبوا الدعاء: مغفرة الذنوب، وتكفير السيئات، ثم الوفاة مع الأبرار؟","answer":"بدأوا بطلب غفران الذنوب رحمة وفضلًا، ثم تكفير السيئات بما شرع من الطاعات، ثم سألوا دوام البر وحسن الخاتمة حتى يتوفوا في زمرة الأبرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص489–490، تحت «وجه الجمع بين لفظي: الغفران والتكفير».","url":""}]},{"id":"s3-735","number":735,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة الجمع بين ﴿ذنوبنا﴾ و﴿سيئاتنا﴾ في الدعاء؟","answer":"إما أن الجمع للتوكيد واستيعاب التقصير كله، وإما لأن الذنب ما فيه عصيان وتقصير فيناسبه الغفران، والسيئة الفعلة القبيحة فيناسبها التكفير الذي يسترها ويعوض أثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص489، تحت «وجه الجمع بين لفظي: (الغفران، والتكفير)».","url":""}]},{"id":"s3-736","number":736,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما سرّ التعبير في دعائهم: ﴿وآتنا ما وعدتنا على رسلك﴾، دون أن يقال: على ألسنة رسلك؟","answer":"لأن الرسل أنفسهم حملة الوعد ومبلغوه، فنسب مجيء الوعد إليهم مباشرة: ما وعدتنا على أيدي رسلك وبسبب تصديقهم، وهو أوجز وأشمل من حصر التبليغ في الألسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص495، تحت «دلالة حرف الجر ﴿على﴾».","url":""}]},{"id":"s3-737","number":737,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"لماذا طلبوا إنجاز الوعد مع يقينهم أن الله لا يخلف الميعاد؟","answer":"ليس شكًا في الوعد، بل تضرع لطلب الدخول في أهله والثبات على أسبابه؛ فالخشية متجهة إلى تقصيرهم لا إلى خلف من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص497، تحت «الوعد والعهد».","url":""}]},{"id":"s3-738","number":738,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما سرّ تخصيص نفي الخزي بقولهم: ﴿يوم القيامة﴾؟","answer":"لأن خزي القيامة هو الأشد والأبقى: افتضاح أمام الخلق يعقبه مصير لا مهرب منه ولا فرصة لتداركه، فخصوه بالدعاء وإن وقعت صور من الخزي في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص497، تحت «الخزي والذل».","url":""}]},{"id":"s3-739","number":739,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما مناسبة ختم الدعاء بقولهم: ﴿إنك لا تخلف الميعاد﴾؟","answer":"ختموا بها تعليلًا لرجائهم وتثبيتًا لقلوبهم: طلبهم مبني على وعد صادق لا يتخلف، وهم يسألون أن يجعلهم الله من أهله؛ وفيها كمال اليقين مع كمال التضرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص495، تحت «بلاغة التأكيد والتعليل في الفاصلة».","url":""}]},{"id":"s3-740","number":740,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستجاب لهم ربهم﴾ لا ﴿فأجابهم﴾؟","answer":"الاستجابة تفيد قبول الدعاء وتحقيق مقتضاه، وإظهار ﴿ربهم﴾ يربط الإجابة بالتربية والرعاية والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص503، تحت «سر التعبير بـ(استجاب) دون (أجاب)».","url":""}]},{"id":"s3-741","number":741,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سرّ إظهار وصف الربوبية في قوله تعالى: ﴿ربهم﴾؟","answer":"أظهر وصف الربوبية لأن استجابته لهم من إحسانه وتفضله ورعايته لعباده، ولأنهم كرروا دعاءه بقولهم ﴿ربنا﴾؛ فجاء ﴿ربهم﴾ مشعرًا بالشفقة والقرب والتشريف وردِّ حسن دعائهم بمثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص504، تحت «نكتة اختيار اسم الله الرب»","url":""}]},{"id":"s3-742","number":742,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير في قوله تعالى: ﴿أني لا أضيع عمل عامل منكم﴾، فجعل العمل شيئًا يضيع؟","answer":"صوّر العمل كشيء محفوظ يمكن أن يضيع، ثم نفى إضاعته؛ أي لا يُبطل الله ثواب عمل عامل ولا يدعه يذهب هدرًا، بل يحفظه لصاحبه ويجازيه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص505، تحت «نكتة التعبير عن ترك الإثابة بالإضاعة».","url":""}]},{"id":"s3-743","number":743,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة التصريح بقوله تعالى: ﴿من ذكر أو أنثى﴾ بعد عموم ﴿عامل﴾؟","answer":"جاء ﴿من ذكر أو أنثى﴾ بعد عموم ﴿عامل﴾ توكيدًا ورفعًا لتوهم أن الخطاب أو الوعد خاص بالرجال؛ فصرح بأن حفظ العمل والجزاء عليه يشمل الجنسين سواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص502، تحت «المعنى الإجمالي».","url":""}]},{"id":"s3-744","number":744,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"لماذا اعترض بقوله ﴿بعضكم من بعض﴾؟","answer":"اعتراض يقرر وحدة الأصل والتكليف والتناصر، وينفي أن يضيع عمل بسبب الذكورة أو الأنوثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص505، تحت «بلاغة الإطناب بالاعتراض».","url":""}]},{"id":"s3-745","number":745,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"لماذا رُتبت الأعمال: الهجرة، والإخراج، والأذى، والقتال، والقتل؟","answer":"تصاعدت من مفارقة الوطن، إلى الإكراه على الخروج، إلى تحمل الأذى، ثم مباشرة القتال، ثم بذل النفس؛ فوافق تصاعد الجزاء تصاعد التضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص507، تحت «براعة حسن ترتيب المعطوفات».","url":""}]},{"id":"s3-746","number":746,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"لماذا أكّد التكفير والإدخال بلام ونون التوكيد؟","answer":"لتثبيت الوعد بعد ذكر أقصى التضحيات وقطع توهم ضياع شيء منها؛ فاللام والنون تنقلان الجزاء إلى وعد محقق مؤكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص509، تحت «سر تأكيد الخبر بـ﴿لأكفرن﴾ و﴿لأدخلنهم﴾».","url":""}]},{"id":"s3-747","number":747,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير بالمصدر في قوله تعالى: ﴿ثوابًا من عند الله﴾ بعد تفصيل الجزاء؟","answer":"جاء ﴿ثوابًا﴾ توكيدًا لمعنى الجزاء المفصل قبله من التكفير وإدخال الجنات، و﴿من عند الله﴾ لتعظيم هذا الثواب وتشريفه وبيان أنه فضل خاص صادر من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص510، تحت «دلالة التنكير في ﴿ثوابًا﴾».","url":""}]},{"id":"s3-748","number":748,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة ختم الآية بقوله تعالى: ﴿والله عنده حسن الثواب﴾؟","answer":"ذُيّلت الآية بـ﴿والله عنده حسن الثواب﴾ لتقرير أن الجزاء الكامل الحسن مختص بالله ومدخر عنده، وتعظيم ما أعده للعاملين وترغيبهم فيه بعد تفصيل الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص511–512، تحت «نكتة التذييل في الفاصلة».","url":""}]},{"id":"s3-749","number":749,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]},{"surah":4,"verses":[124]}],"verseLabel":"آل عمران: 195؛ النساء: 124","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿مَنْ يَعْمَلْ مِنَ الصَّالِحَاتِ مِنْ ذَكَرٍ أَوْ أُنْثَى﴾، وقوله تعالى في آل عمران: ﴿لَا أُضِيعُ عَمَلَ عَامِلٍ مِنْكُمْ مِنْ ذَكَرٍ أَوْ أُنْثَى﴾؟","answer":"في آل عمران: 195: في النساء سيقت قاعدة دخول الجنة، فذُكر الإيمان والعمل من الصالحات شرطًا للجزاء؛ وهنا سيق جواب الدعاء ووعد الجماعة المؤمنة، فنفى إضاعة عمل أي عامل منهم ثم صرح بشمول الذكر والأنثى.\n\nفي النساء: 124؛ آل عمران: 195: النساء تقرر قاعدة الجزاء بصيغة الشرط، فبدأت بالعمل ثم عممت فاعله. وآل عمران جواب دعاء، فبدأت بنفي إضاعة عمل أي عامل، تمهيدًا لما بعدها من أعمال المهاجرين والمجاهدين.","sources":[{"label":"[آل عمران: 195] موسوعة التفسير البلاغي، ج6، ص498–514؛ مسح عكسي","url":""},{"label":"[النساء: 124؛ آل عمران: 195] موسوعة التفسير البلاغي، ج6، ص498–514؛ وج8، ص93–102","url":""}]},{"id":"s3-750","number":750,"surah":3,"verses":[196],"references":[{"surah":3,"verses":[196]}],"verseLabel":"آل عمران: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يغرنك تقلب الذين كفروا في البلاد﴾، وما الصورة التي يرسمها ﴿تقلب﴾؟","answer":"التقلب هو تنقلهم وتصرفهم في البلاد للتجارة والمكاسب، وما يصاحبه من ظهور السعة والقوة؛ فنُهي عن أن يخدع هذا الازدهار العارض، لأن مآله متاع قليل ثم جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص518، تحت «بلاغة المجاز العقلي في قوله: ﴿لا يغرنك تقلب﴾».","url":""}]},{"id":"s3-751","number":751,"surah":3,"verses":[196],"references":[{"surah":3,"verses":[196]}],"verseLabel":"آل عمران: 196","question":"لماذا أُفرد خطاب النبي في نهي يراد به تثبيت المؤمنين؟","answer":"لأن ثبات القائد أبلغ طريق إلى تثبيت الجماعة، والخطاب له تشريف وتعليم لكل سامع؛ فإذا نُهي الرسول عن الاغترار بتقلب الكافرين فالأمة أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص517، تحت «دلالة الخطاب في ﴿لا يغرنك﴾».","url":""}]},{"id":"s3-753","number":753,"surah":3,"verses":[196],"references":[{"surah":3,"verses":[196]},{"surah":40,"verses":[4]}],"verseLabel":"آل عمران: 196؛ غافر: 4","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران: ﴿لا يغرنك تقلب الذين كفروا في البلاد﴾، وقوله في غافر: ﴿فلا يغررك تقلبهم في البلاد﴾؟","answer":"في آل عمران جاء النهي ابتداءً، وصرح بـ﴿الَّذِينَ كَفَرُوا﴾، وأكد الفعل بنون التوكيد الثقيلة: ﴿يَغُرَّنَّكَ﴾. وفي غافر جاء بالفاء نتيجةً لما قبلها، واكتفى بالضمير بعد ذكر الكافرين، وجاء الفعل مجزومًا بلا نون: ﴿يَغْرُرْكَ﴾؛ فناسب كل تعبير سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص519–521، تحت «توجيه المتشابه اللفظي».","url":""}]},{"id":"s3-754","number":754,"surah":3,"verses":[197],"references":[{"surah":3,"verses":[197]}],"verseLabel":"آل عمران: 197","question":"ما دلالة إيجاز نجاحهم الدنيوي في قوله تعالى: ﴿متاع قليل﴾؟","answer":"سمّاه ﴿متاعًا﴾ لأنه انتفاع عارض لا بقاء له، ووصفه بالقلة لقصر مدته وضآلة قدره أمام نعيم الآخرة أو عذابها؛ فاختصر بهما بريق نجاحهم كله وحقره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص519، تحت «بلاغة الفصل في قوله: ﴿متاع قليل﴾».","url":""}]},{"id":"s3-755","number":755,"surah":3,"verses":[197],"references":[{"surah":3,"verses":[197]}],"verseLabel":"آل عمران: 197","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم مأواهم جهنم﴾؟","answer":"﴿ثُمَّ﴾ تفيد التراخي الزمني، وتبرز كذلك البون بين المتاع العابر والمصير الثقيل. و﴿مَأْوَاهُمْ﴾ تسمي جهنم مقرهم النهائي بعد ذلك التقلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص519، تحت «دلالة حرف العطف ﴿ثم﴾».","url":""}]},{"id":"s3-756","number":756,"surah":3,"verses":[197],"references":[{"surah":3,"verses":[197]}],"verseLabel":"آل عمران: 197","question":"لماذا ختم بـ﴿وبئس المهاد﴾، وسمّى جهنم مهادًا؟","answer":"سمّى النار مهادًا على سبيل التهكم؛ فالمهاد موضع الراحة، أما هذا المهاد فغاية العذاب، وفي التضاد زيادة تهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص521، تحت «بلاغة الاستعارة التهكمية في قوله: ﴿ثم مأواهم جهنم وبئس المهاد﴾».","url":""}]},{"id":"s3-757","number":757,"surah":3,"verses":[198],"references":[{"surah":3,"verses":[198]}],"verseLabel":"آل عمران: 198","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الذين اتقوا ربهم﴾ بعد وصف حال الكافرين؟","answer":"جاءت ﴿لكن﴾ استدراكًا ينقل من تقلب الكافرين القصير ومأواهم في النار إلى المصير المقابل للمتقين: جنات خالدة ونزل من الله؛ فأتبع الوعيد بالوعد وأظهر التفاوت بين المآلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص527–528، تحت «بلاغة المقابلة».","url":""}]},{"id":"s3-758","number":758,"surah":3,"verses":[198],"references":[{"surah":3,"verses":[198]}],"verseLabel":"آل عمران: 198","question":"ما دلالة قوله تعالى: ﴿لهم جنات تجري من تحتها الأنهار خالدين فيها﴾ في مقابلة ﴿متاع قليل﴾؟","answer":"جمع ﴿جنات﴾ ونكّرها للإشعار بكثرتها وتنوعها وتفاوت درجاتها بحسب الأعمال، ووصفها بجريان الأنهار لدوام زهرتها وتجدد نعيمها، ثم قال ﴿خالدين فيها﴾ ليقابل دوام نعيم المتقين قصر متاع الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص527–528، تحت «بلاغة المقابلة».","url":""}]},{"id":"s3-759","number":759,"surah":3,"verses":[198],"references":[{"surah":3,"verses":[198]}],"verseLabel":"آل عمران: 198","question":"لماذا سمّى نعيم الجنة ﴿نزلًا من عند الله﴾؟","answer":"النزل ما يهيأ للضيف عند قدومه؛ فإذا كان نعيم الجنة مجرد نزل من عند الله فما بعده أعظم وأدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص528، تحت «سر التعبير بـ﴿نزلا﴾»","url":""}]},{"id":"s3-760","number":760,"surah":3,"verses":[198],"references":[{"surah":3,"verses":[198]}],"verseLabel":"آل عمران: 198","question":"ما سرّ التعبير بقوله تعالى: ﴿وما عند الله خير للأبرار﴾، دون: للمتقين كما في أول الآية؟","answer":"عدل من ﴿الذين اتقوا﴾ إلى ﴿الأبرار﴾ ليبين أن ما وصفوا به من التقوى والطاعة هو عين البر، وأنهم جمعوا الوصفين؛ ففي الإظهار تنويه بهم وإشعار بتداخل أعمال البر والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص530، تحت «نكتة وضع المظهر موضع المضمر».","url":""}]},{"id":"s3-761","number":761,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة قوله تعالى: ﴿وإن من أهل الكتاب لمن يؤمن بالله﴾ بعد الآيات التي نقدت مواقف فريق منهم؟","answer":"لئلا يعم النقد جميع أهل الكتاب؛ فبين أن منهم فريقًا آمن بالله والوحي وخشع ولم يبع الآيات، فهو داخل في وصف المتقين. وفي ذلك إنصاف يميز الصادقين من ناقضي الميثاق والمحرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص535، تحت «سبب وصل ﴿وإن من أهل الكتاب﴾ بما قبلها».","url":""}]},{"id":"s3-762","number":762,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"لماذا جمع بين ﴿ما أنزل إليكم وما أنزل إليهم﴾؟","answer":"ليثبت أن إيمان الصادقين من أهل الكتاب لا يتجزأ: يصدقون بالقرآن وبأصل الوحي الذي عندهم، فيلتقي التنزيلان عند مصدر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص536، تحت «نكات تقديم الإيمان بالقرآن على الإيمان بما أنزل إليهم».","url":""}]},{"id":"s3-763","number":763,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة وصفهم بقوله تعالى: ﴿خاشعين لله﴾ بين صفات الإيمان؟","answer":"لأن الخشوع أثر الإيمان الصادق في القلب: انقياد باطن لله مع الذل والافتقار والتأثر بجلاله؛ ومن ثمرته ألا يؤثر صاحبه عرض الدنيا على آيات الله، فوقع بين الإيمان وعدم بيع الآيات رابطًا بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص542–545، تحت «الخشوع والخضوع».","url":""}]},{"id":"s3-764","number":764,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة قوله تعالى: ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾ في مقابل من سبق ذكرهم؟","answer":"صوّر إيثار الدنيا على الوحي بصفقة يبيع فيها المرء آيات الله بثمن حقير؛ فنفى ذلك عن المؤمنين من أهل الكتاب مدحًا لهم، وعرّض بمن حرفوا وكتموا لقاء الرشوة، فظهر التباين بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص537، تحت «بلاغة المجاز في قوله: ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾».","url":""}]},{"id":"s3-765","number":765,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سرّ إضافة الأجر إليهم في قوله تعالى: ﴿أولئك لهم أجرهم عند ربهم﴾؟","answer":"أضاف الأجر إليهم في ﴿أجرهم﴾ للعهد والاختصاص؛ أي الأجر المعروف الموعود لهم، وقدم ﴿لهم﴾ لتأكيد أنه خاص بهؤلاء المؤمنين دون من بقي على رد القرآن وتحريف الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص539، تحت «فائدة الإضافة في قوله: ﴿أجرهم﴾».","url":""}]},{"id":"s3-766","number":766,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"لماذا ختم بـ﴿إن الله سريع الحساب﴾ في مقام الوعد؟","answer":"سرعة الحساب تطمئن إلى قرب الوفاء، وتحذر من توهم أن كثرة الخلق أو الأعمال تؤخر الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص540، تحت «نكتة الإتيان بجملة ﴿إن الله سريع الحساب﴾ بعد ذكر الأجر».","url":""}]},{"id":"s3-767","number":767,"surah":3,"verses":[77,199],"references":[{"surah":3,"verses":[77,199]}],"verseLabel":"آل عمران: 199؛ آل عمران: 77","question":"لماذا قوبل من ﴿يشترون بعهد الله وأيمانهم ثمنًا قليلًا﴾ بمن ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾ في آخر السورة؟","answer":"التركيب الواحد يقيم ميزانًا داخل أهل الكتاب: فريق باع العهد والآيات فعوقب بالحرمان، وفريق آمن وخشع ورفض البيع فثبت له الأجر؛ فالمقابلة تختم السورة بالإنصاف بعد النقد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص537، تحت «بلاغة المجاز في قوله: ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾».","url":""}]},{"id":"s3-768","number":768,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما دلالة اجتماع الأوامر الأربعة في خاتمة السورة: ﴿اصبروا وصابروا ورابطوا واتقوا الله﴾؟","answer":"خُتمت بها لأنها تجمع مقتضى ما سبق من العقائد والأحكام: صبر النفس على الطاعة والبلاء، ومغالبة الخصم في الصبر، والثبات لحراسة الدين ودفع العدوان، وجعل التقوى باعثًا وضابطًا لهذه الأعمال كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص548، تحت «براعة الختام في السورة».","url":""}]},{"id":"s3-769","number":769,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما الفرق بين ﴿اصبروا﴾ و﴿صابروا﴾، وما الذي زادته صيغة المفاعلة؟","answer":"﴿اصبروا﴾ أمر عام بحبس النفس على الطاعة وعن المعصية وعلى البلاء، ثم زادت صيغة المفاعلة في ﴿صابروا﴾ معنى مقابلة الخصم ومغالبته في الصبر حتى لا يكون أثبت منكم؛ فهي صبر مشترك أشد من الصبر الفردي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص546–547، تحت «بلاغة عطف الخاص على العام».","url":""}]},{"id":"s3-770","number":770,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما مناسبة إتباع الصبر والمصابرة بالأمر: ﴿ورابطوا﴾؟","answer":"لأن المرابطة مرحلة أزيد من مجرد الصبر ومغالبة الخصم فيه: ثبات دائم واستعداد في الثغور لحراسة الدين ودفع العدوان؛ فترقى الأمر من صبر النفس إلى مصابرة العدو ثم ملازمة موقع الحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص546–547، تحت «بلاغة عطف الخاص على العام».","url":""}]},{"id":"s3-771","number":771,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما دلالة ختم الأوامر بقوله تعالى: ﴿واتقوا الله﴾؟","answer":"لأن التقوى هي الدافع والضابط للأوامر السابقة: تحمل على الصبر، وتقوي المصابرة، وتصون المرابطة من الرياء أو العدوان؛ وهي أن يحذر المؤمن مخالفة أمر الله بتركه ونهيه بفعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص545–546، تحت «بلاغة عطف الخاص على العام».","url":""}]},{"id":"s3-772","number":772,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما دلالة تعليق الفلاح على هذه الأوامر في قوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"لأن الصبر والمصابرة والمرابطة والتقوى أسباب الفلاح؛ فجاء ﴿لعلكم﴾ ترغيبًا ورجاءً للمؤمنين أن يفضي امتثالهم إليها إلى الفوز بخير الدنيا والآخرة وإدراك الخير والبقاء فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص548–549، تحت «براعة الختام في السورة».","url":""}]},{"id":"s3-780","number":780,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"ما دلالة التعبير بـ﴿بَعْدَ إِذْ هَدَيْتَنَا﴾، وما وجه ملاءمة «بعد» لمقام الدعاء على الثبات؟","answer":"«بعد» ظرف زمان، فجاءت لتصوّر خوف الراسخين من انحراف القلب بعد حصول الهداية؛ فالمطلوب ليس ابتداء الهداية فحسب، بل دوامها وعدم الرجوع عنها. وهذا يختلف عن «خلف» التي يغلب استعمالها في المكان أو فيمن يخلّف الإنسان وراءه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «بعد» و«خلف».؛ العنوان الجزئي: الفروق السياقية بين «بعد» و«خلف».","url":""}]},{"id":"s3-781","number":781,"surah":3,"verses":[8,38,147,193,194],"references":[{"surah":3,"verses":[8,38,147,193,194]}],"verseLabel":"آل عمران: 8، 38، 147، 193، 194","question":"ما دلالة تكرر نداء ﴿رَبَّنَا﴾ والدعاء في محطات متباعدة من السورة، من تثبيت القلوب إلى طلب الذرية والنصر وحسن الخاتمة؟","answer":"تتنوع مواطن الابتلاء، لكن باب الثبات فيها واحد: افتقار العبد إلى ربه. لذلك صاحَب الدعاء فتنة الزيغ، وانتظار الذرية، وشدة القتال، والتفكر في المصير؛ فصار تكرار ﴿ربنا﴾ خيطًا يصل الثبات الفكري والأسري والميداني والأخروي بربوبية الله ورعايته.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، محور الثبات وكثرة الدعاء في سورة آل عمران.؛ العنوان الجزئي: الدعاء أداة الثبات في مسارات السورة.","url":""}]},{"id":"s3-782","number":782,"surah":3,"verses":[10,12],"references":[{"surah":3,"verses":[10,12]}],"verseLabel":"آل عمران: 10، 12","question":"ما وجه الجمع بين نفي نفع الأموال والأولاد، ثم ذكر الغلبة في الدنيا والحشر إلى جهنم؟","answer":"الآيات ترسم مصيرًا كاملًا للكافرين: لا تنفعهم أسباب القوة الدنيوية، ثم يُغلبون في الدنيا، ثم يُحشرون إلى جهنم في الآخرة. فالسياق لا يحصر الخسران في الجزاء الأخروي، بل يجمع بين سقوط الحماية في الدنيا وسوء المآل في الآخرة.","sources":[{"label":"فاضل السامرائي، قبسات من البيان القرآني، ص 139–144.؛ العنوان الجزئي: امتداد عدم الإغناء من الدنيا إلى الآخرة.","url":""}]},{"id":"s3-783","number":783,"surah":3,"verses":[11],"references":[{"surah":3,"verses":[11]}],"verseLabel":"آل عمران: 11","question":"ما دلالة التعبير بـ﴿فَأَخَذَهُمُ اللَّهُ﴾ بعد ﴿بِآيَاتِنَا﴾، وعدم مجيئه بضمير الجمع: «فأخذناهم»؟","answer":"لأن القرآن لا يستعمل ضمير الجمع في مقام الأخذ والعقوبة من غير قرينة قريبة تدل على الإفراد. فجاءت «بآياتنا» بضمير العظمة، ثم أُتبعَت بـ«فأخذهم الله» لتظهر وحدة الفاعل صراحة، وليبرز إسناد الأخذ والعقوبة إلى الله تعالى.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، الجزء الثاني، ص 26.؛ العنوان الجزئي: مناسبة الإظهار في «فأخذهم الله» بعد «بآياتنا».","url":""}]},{"id":"s3-784","number":784,"surah":3,"verses":[12],"references":[{"surah":3,"verses":[12]}],"verseLabel":"آل عمران: 12","question":"ما دلالة حرف الغاية في ﴿وَتُحْشَرُونَ إِلَى جَهَنَّمَ﴾، وما الفرق بينه وبين ﴿وَحَشَرْنَا عَلَيْهِمْ﴾؟","answer":"«إلى» في آية آل عمران تبيّن جهة الانتهاء والمصير: يُجمعون إلى جهنم. أما «عليهم» في آية الأنعام فتفيد جمع الحجج والآيات في مواجهتهم وإقامتها عليهم؛ فالسياق الأول سياق مصير، والثاني سياق إقامة حجة.","sources":[{"label":"فاضل السامرائي، بلاغة «حشرنا عليهم» و«تحشرون إلى جهنم».؛ العنوان الجزئي: دلالة حروف الغاية والمواجهة في مادة «حشر».","url":""}]},{"id":"s3-785","number":785,"surah":3,"verses":[18],"references":[{"surah":3,"verses":[18]}],"verseLabel":"آل عمران: 18","question":"ما دلالة وصف الشهادة الإلهية بأنه ﴿قَائِمًا بِالْقِسْطِ﴾؟","answer":"يفيد الوصف ثبوت القيام بالقسط ودوامه، لا وقوعه في حالة عابرة. فالشهادة بالتوحيد اقترنت ببيان أن الله قائم بالعدل على وجه اللزوم والاستمرار، وفي ذلك جمع بين أصل الاعتقاد وكمال تدبير العالم.","sources":[{"label":"فاضل السامرائي، وقفة «قائمًا بالقسط».؛ العنوان الجزئي: لزوم القيام بالقسط في شهادة التوحيد.","url":""}]},{"id":"s3-786","number":786,"surah":3,"verses":[20],"references":[{"surah":3,"verses":[20]}],"verseLabel":"آل عمران: 20","question":"ما دلالة الفرق بين ﴿أَسْلَمْتُ وَجْهِيَ لِلَّهِ﴾ و﴿مَنْ يُسْلِمْ وَجْهَهُ إِلَى اللَّهِ﴾ في التعبير عن علاقة العبد بربه؟","answer":"«أسلم له» تدل على الانقياد وجعل النفس خالصة لله، وفيها معنى الاختصاص والتمليك. أما «أسلم إليه» فتحتمل معنى دفع الأمر وتفويضه إليه؛ فاختيار اللام في آية آل عمران يصور إخلاص الوجه لله، لا مجرد تفويض الأمر إليه.","sources":[{"label":"فاضل السامرائي، الفرق بين «أسلم لله» و«أسلم إليه»، لمسات بيانية.؛ العنوان الجزئي: دلالة تعدية «أسلم» باللام وبـ«إلى».","url":""}]},{"id":"s3-787","number":787,"surah":3,"verses":[21],"references":[{"surah":3,"verses":[21]}],"verseLabel":"آل عمران: 21","question":"ما سر تكرار ﴿وَضُرِبَتْ عَلَيْهِمُ﴾ في آية آل عمران 112، بعد أن جُمعت الذلة والمسكنة في آية البقرة 61؟","answer":"جمع آية البقرة الوصفين في سياق واحد، أما آل عمران ففصل بينهما وكرر الفعل: ﴿ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ ... وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ﴾. هذا التكرار يفيد التعميق والتوكيد، ويناسب سياقًا صُوِّرت فيه الجريمة والعقوبة بصورة أشد، فلا يصح وضع أحد التعبيرين مكان الآخر.","sources":[{"label":"فاضل السامرائي، المقارنة البيانية بين آيات الذلة والمسكنة.؛ العنوان الجزئي: تكرار الفعل في «ضربت عليهم الذلة» و«ضربت عليهم المسكنة».","url":""}]},{"id":"s3-788","number":788,"surah":3,"verses":[21],"references":[{"surah":3,"verses":[21]}],"verseLabel":"آل عمران: 21","question":"ما وجه اختلاف ﴿يَقْتُلُونَ النَّبِيِّينَ﴾ و﴿يَقْتُلُونَ الْأَنْبِيَاءَ﴾، وما الذي يضيفه اختلاف الجمع إلى شدة الجريمة؟","answer":"جاء «النبيين» في سياق، و«الأنبياء» في سياق آخر؛ وبيّن السامرائي أن «الأنبياء» جمع كثرة، فيوحي باتساع عدد من قتلوهم، بينما «النبيين» أضيق من جهة الصيغة. فاختيار الجمع يوافق مقدار الجريمة وسياق الحكم في كل آية.","sources":[{"label":"فاضل السامرائي، المقارنة البيانية بين آيات قتل الأنبياء.؛ العنوان الجزئي: الفرق بين «النبيين» و«الأنبياء» في سياق الجريمة.","url":""}]},{"id":"s3-789","number":789,"surah":3,"verses":[25],"references":[{"surah":3,"verses":[25]}],"verseLabel":"آل عمران: 25","question":"ما الفرق بين التعبير بـ﴿مَا عَمِلَتْ﴾ في آل عمران والنحل، وبـ﴿مَا كَسَبَتْ﴾ في البقرة عند الحديث عن جزاء النفس؟","answer":"«عملت» يركّز على الفعل نفسه وما باشرته النفس، أما «كسبت» فيركّز على ما حصّلته النفس واكتسبته من آثار ذلك العمل. فاختيار اللفظ يتبع سياق الآية: تارة يُنظر إلى مباشرة العمل، وتارة إلى ما آل إليه وصار كسبًا لصاحبه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «ما عملت» و«ما كسبت».؛ العنوان الجزئي: الفرق بين «ما عملت» و«ما كسبت».","url":""}]},{"id":"s3-790","number":790,"surah":3,"verses":[26,27],"references":[{"surah":3,"verses":[26,27]}],"verseLabel":"آل عمران: 26، 27","question":"ما سر تتابع الأفعال في قوله تعالى: ﴿تُؤْتِي﴾ و﴿تَنْزِعُ﴾ و﴿تُعِزُّ﴾ و﴿تُذِلُّ﴾ و﴿تُولِجُ﴾ و﴿تُخْرِجُ﴾ و﴿تَرْزُقُ﴾؟","answer":"التتابع بالفعل يصوّر تجدد التصرفات الإلهية وانتقال الأحوال: ملك يُعطى ويُنزع، وعز يتحول إلى ذل، وليل يدخل في نهار، وحي يخرج من ميت. فالسياق سياق تغيّر وتبديل وحركة، فجاءت الأفعال ملائمة لمقتضى الحال، لا ألفاظًا اسمية توحي بالثبات وحده.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الصيغة الفعلية في «يخرج» وسياق التغيرات.؛ العنوان الجزئي: مطابقة الصيغة الفعلية لسياق التغير والتجدد.","url":""}]},{"id":"s3-791","number":791,"surah":3,"verses":[29],"references":[{"surah":3,"verses":[29]}],"verseLabel":"آل عمران: 29","question":"ما دلالة التعبير بـ﴿مَا فِي صُدُورِكُمْ﴾ في آل عمران، مقابل ﴿مَا فِي أَنْفُسِكُمْ﴾ في البقرة؟","answer":"«الأنفس» أليق بما يختزن من شهوات وأهواء ودوافع، ولذلك وردت في سياق ما تحاسب عليه النفس. أما «الصدور» فتشير إلى مكنونات القلب من الهواجس والعواطف والوساوس والحقد والحب ونحوها؛ فاختلاف اللفظ يراعي نوع الباطن المقصود في كل سياق.","sources":[{"label":"فاضل السامرائي، قبسات من البيان القرآني، ص 167–176، مادة المقارنة بين «ما في صدوركم» و«ما في أنفسكم».؛ العنوان الجزئي: وظائف النفس والصدر في التعبير القرآني.","url":""}]},{"id":"s3-792","number":792,"surah":3,"verses":[30],"references":[{"surah":3,"verses":[30]}],"verseLabel":"آل عمران: 30","question":"ما الفرق بين ﴿أَمَدًا بَعِيدًا﴾ في آل عمران، و«المدى» في التعبير عن نهاية الشيء؟","answer":"الأمد هو غاية الشيء ومنتهى الأجل، وقد يكون قريبًا أو بعيدًا، ولذلك صح وصفه بالبعد في الآية. أما المدى فيدل على النهاية أو الغاية، وقد يوصف هو أيضًا بالقرب أو البعد؛ فاختيار «أمد» يصوّر المسافة الزمنية التي تتمنى النفس تباعدها عن سوء عملها.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الأمد والمدى.؛ العنوان الجزئي: الفرق بين «الأمد» و«المدى».","url":""}]},{"id":"s3-793","number":793,"surah":3,"verses":[33],"references":[{"surah":3,"verses":[33]}],"verseLabel":"آل عمران: 33","question":"ما الفرق بين ﴿اصْطَفَى﴾ و«اختار» في قوله تعالى: ﴿إِنَّ اللَّهَ اصْطَفَى آدَمَ وَنُوحًا﴾؟","answer":"الاختيار يكون من أشياء غير متشابهة، كاختيار قلم من ورقة وكتاب وقلم. أما الاصطفاء فيكون من أشياء متشابهة أو متناظرة، فينتقي الله بعضها من جنسها ويخصها بفضله؛ فلفظ «اصطفى» أنسب بالسياق الذي يذكر اصطفاء أشخاص من بين أمثالهم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «اصطفى» و«اختار».؛ العنوان الجزئي: الفرق بين الاصطفاء والاختيار.","url":""}]},{"id":"s3-794","number":794,"surah":3,"verses":[33,42],"references":[{"surah":3,"verses":[33,42]}],"verseLabel":"آل عمران: 33، 42","question":"ما سر تقديم الثناء على آل عمران واصطفاء مريم قبل مناقشة عقيدة أهل الكتاب في عيسى وإبراهيم؟","answer":"أثنت السورة أولًا على من يستحق الثناء من البيت الذي ينتسب إليه عيسى، وأثبتت اصطفاء مريم وطهارتها، ثم ناقشت الغلو بالحجة. فدل ترتيبها على أن تصحيح الاعتقاد لا يقتضي انتقاص أهل الفضل، وأن الإنصاف يمهد للجدال بالحق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الثناء على الأنبياء وأهل الاصطفاء قبل المحاجة.؛ العنوان الجزئي: الإنصاف تمهيدًا لتصحيح الاعتقاد.","url":""}]},{"id":"s3-795","number":795,"surah":3,"verses":[37],"references":[{"surah":3,"verses":[37]}],"verseLabel":"آل عمران: 37","question":"كيف تتسع عبارة ﴿يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ﴾ لكل هذه المعاني في سياق رزق مريم؟","answer":"«بغير حساب» تعني أن الله لا يُسأل عما يفعل، ولا يرزق الناس على قدر طاعتهم وحدها، ولا يخشى نفاد خزائنه. وتحتمل كذلك أن يأتي العبد رزقه من حيث لا يحتسب؛ وهذا هو الظاهر في رزق مريم الذي جاءها من غير الطريق المألوف، فكانت العبارة من جوامع الكلم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، معاني «بغير حساب».؛ العنوان الجزئي: اتساع دلالة «بغير حساب».","url":""}]},{"id":"s3-796","number":796,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"كيف ينسجم تأنيث ﴿فَنَادَتْهُ الْمَلَائِكَةُ﴾ مع اختلاف التعبير عن نزول الملائكة في مشهدي الشدة والبشرى؟","answer":"يندرج نداء زكريا في خط البشرى الذي تلائمه الصيغة المؤنثة، ونظيره ﴿تَتَنَزَّلُ عَلَيْهِمُ الْمَلَائِكَةُ﴾ في بشارة المستقيمين. أما مشهد القيامة الشديد فجاء فيه ﴿وَنُزِّلَ الْمَلَائِكَةُ﴾ بالتذكير؛ فتتساند الصيغة مع الجو النفسي للمشهد.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، نزول الملائكة بين الشدة والبشارة.؛ العنوان الجزئي: انتظام البشارة في خط التأنيث.","url":""}]},{"id":"s3-797","number":797,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما دلالة مجيء نداء الملائكة لزكريا مؤنث الفعل، مع ورود الأمر إليهم مذكرًا في نحو ﴿اسْجُدُوا لِآدَمَ﴾؟","answer":"إذا حكى القرآن أمرًا موجهًا إلى الملائكة جاء بضمير التذكير، وفي ذلك تثبيت حقيقتهم وردّ على زعم المشركين أنهم إناث. أما حكاية صدور البشارة عن جمع الملائكة فيجوز فيها التأنيث، فاستعمله القرآن حيث يلائم الرقة والبشرى من غير أن يمس حقيقة الملائكة.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، أوامر الملائكة وصيغ البشارة.؛ العنوان الجزئي: التذكير في التكليف والتأنيث في البشارة.","url":""}]},{"id":"s3-798","number":798,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما سر تأنيث الفعل في ﴿فَنَادَتْهُ الْمَلَائِكَةُ﴾، مقابل تذكيره في ﴿فَسَجَدَ الْمَلَائِكَةُ﴾؟","answer":"يجيز اللسان العربي الوجهين مع جمع التكسير، لكن الاختيار القرآني يتبع المقام. جاء التأنيث في آل عمران مع بشارة زكريا، بينما جاء التذكير مع السجود والعبادة؛ فناسب مقام البشارة اللطف، وناسب مقام العبادة التذكير الذي جرى عليه الخط التعبيري في أفعال الملائكة الدالة على التكليف والطاعة.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، التذكير والتأنيث مع الملائكة.؛ العنوان الجزئي: ملاءمة صيغة الفعل لمقام البشارة والعبادة.","url":""}]},{"id":"s3-799","number":799,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما سر تأنيث فعل الملائكة في بشارة زكريا، مع تذكير الفعل في بشارة إبراهيم: ﴿وَبَشَّرُوهُ بِغُلَامٍ عَلِيمٍ﴾؟","answer":"قصة إبراهيم لم تُسند الفعل فيها إلى لفظ «الملائكة»، بل قُدِّموا بوصفهم ﴿ضَيْفِ إِبْرَاهِيمَ الْمُكْرَمِينَ﴾، فجرى الضمير على الضيف. أما في آل عمران فالمذكور صراحة هو جمع «الملائكة»، فظهر فيه الاختيار التعبيري الخاص بهذا اللفظ في مقام البشرى.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، بشارة زكريا وبشارة إبراهيم.؛ العنوان الجزئي: أثر الاسم المذكور في مرجع الضمير.","url":""}]},{"id":"s3-800","number":800,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما وجه الفرق بين لطف ﴿فَنَادَتْهُ الْمَلَائِكَةُ﴾ في بشارة زكريا، واختلاف الصيغة عند قبض أرواح الظالمين والطيبين؟","answer":"يختار القرآن للملائكة صيغة تلائم طبيعة الموقف: فمقام الخير والبشارة والطمأنينة يناسبه التأنيث، كما في نداء زكريا وقبض الطيبين؛ أما مقام الشدة والعقوبة فيناسبه التذكير. وهكذا تسهم الصيغة في تلوين المشهد قبل تفصيل مضمونه.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، صيغة الفعل بين البشرى والعقوبة.؛ العنوان الجزئي: أثر طبيعة الحدث في اختيار التذكير والتأنيث.","url":""}]},{"id":"s3-801","number":801,"surah":3,"verses":[39,42],"references":[{"surah":3,"verses":[39,42]}],"verseLabel":"آل عمران: 39، 42","question":"ما سر اتفاق بشارة زكريا وخطاب مريم على إسناد الفعل إلى الملائكة بصيغة التأنيث؟","answer":"الموضعان من سياق واحد قوامه المنح الإلهية والبشارة: ولد لزكريا واصطفاء لمريم ثم بشارتها بالمسيح. فجاء التأنيث رابطًا صوتيًا بين مشاهد الرحمة، ومميزًا لها عن مواطن الأوامر الشديدة والعبادات والعقوبات التي يغلب فيها التذكير.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، خط البشارة في إسناد أفعال الملائكة.؛ العنوان الجزئي: وحدة النبرة في مشاهد البشارة.","url":""}]},{"id":"s3-802","number":802,"surah":3,"verses":[39,42],"references":[{"surah":3,"verses":[39,42]}],"verseLabel":"آل عمران: 39، 42","question":"ما وجه المناسبة بين تأنيث فعل الملائكة في بشارتي زكريا ومريم، وتذكيره في سجود الملائكة؟","answer":"يجمع موضعا آل عمران معنى البشارة والتكريم، فجاء ﴿فَنَادَتْهُ﴾ و﴿قَالَتِ الْمَلَائِكَةُ﴾ بما يلائم رقة المقام. أما السجود فهو عبادة وتكليف، وقد جرى التعبير في أفعال الطاعة الصادرة عن الملائكة على التذكير، فاختار لكل مقام نبرته المناسبة.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، البشارة والعبادة في أفعال الملائكة.؛ العنوان الجزئي: اختلاف الصيغة باختلاف جو الحدث.","url":""}]},{"id":"s3-803","number":803,"surah":3,"verses":[40],"references":[{"surah":3,"verses":[40]}],"verseLabel":"آل عمران: 40","question":"ما دلالة تقديم عقر الزوجة في سورة مريم، وتقديم بلوغ الكِبَر في آل عمران، في وصف موانع الولادة؟","answer":"في مريم قيل: ﴿وَكَانَتِ امْرَأَتِي عَاقِرًا وَقَدْ بَلَغْتُ مِنَ الْكِبَرِ﴾، فناسب أن يبدأ بما كان مانعًا أصليًا ممتدًا في الزوجة. أما في آل عمران فقيل: ﴿وَقَدْ بَلَغَنِيَ الْكِبَرُ وَامْرَأَتِي عَاقِرٌ﴾، فناسب أن يتقدم ما طرأ على زكريا في السياق المعروض هناك؛ فالتقديم يتبع صورة المانع في كل قصة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم موانع الولادة في قصتي زكريا.؛ العنوان الجزئي: تقديم موانع الولادة وتأخيرها بحسب السياق.","url":""}]},{"id":"s3-804","number":804,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما أثر التعبير بـ﴿إِلَّا رَمْزًا﴾ في آل عمران، مقابل ﴿سَوِيًّا﴾ في مريم، في تصوير شدة الآية وظهورها؟","answer":"«إلا رمزًا» يسلط الضوء على الاستثناء من الكلام، فيصوّر انقطاع القدرة على التخاطب مع بقاء الإشارة، وهو أوضح في إظهار الآية. أما «سويًا» في مريم فيعرض حال زكريا في تلك الليالي بوصفه سويًا، ضمن سياق مختلف. فاختلاف العبارة يوافق اختلاف زاوية التصوير، مع كون آية آل عمران أظهر وأعظم اتصالًا بعظم البشارة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، مقابلة «إلا رمزًا» و«سويًا» في قصتي زكريا.؛ العنوان الجزئي: تصوير الآية بين انقطاع الكلام وبقاء السواء.","url":""}]},{"id":"s3-805","number":805,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما دلالة أن يُؤمر زكريا في آل عمران بالذكر والتسبيح بنفسه، بينما يأمر قومه بالتسبيح في سورة مريم؟","answer":"في آل عمران كانت البشارة أعظم وأوصاف يحيى أكمل، فناسب أن يظهر شكر زكريا نفسه بالذكر الكثير والتسبيح. أما في مريم فالمشهد ينتقل إلى قومه، فناسب أن يخرج إليهم ويوصيهم بالتسبيح؛ فاختلاف المخاطَب يبرز اختلاف مقدار الشكر وموقعه في القصة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، من يباشر الذكر والتسبيح في قصتي زكريا.؛ العنوان الجزئي: شكر زكريا وشكر قومه بعد البشارة.","url":""}]},{"id":"s3-806","number":806,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما دلالة الجمع بين ﴿وَاذْكُرْ رَبَّكَ كَثِيرًا﴾ و﴿سَبِّحْ بِالْعَشِيِّ وَالْإِبْكَارِ﴾؟","answer":"الذكر أعم من التسبيح؛ فهو يشمل التسبيح والتحميد والتهليل، ولذلك أُطلق ولم يُقيد بوقت. أما التسبيح فهو نوع أخص من الذكر، فناسب أن يُذكر معه وقتاه. اجتمع العموم والخصوص في الآية ليشمل الشكر قلب زكريا ولسانه ووقته.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الذكر والتسبيح.؛ العنوان الجزئي: عموم الذكر وخصوص التسبيح.","url":""}]},{"id":"s3-807","number":807,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما وجه اختلاف ﴿ثَلَاثَةَ أَيَّامٍ﴾ في آل عمران عن ﴿ثَلَاثَ لَيَالٍ﴾ في مريم؟","answer":"اليوم من طلوع الشمس إلى غروبها، والليل من غروبها إلى طلوع الفجر. فجاء ذكر الأيام في آل عمران؛ لأن البشارة فيها أعظم، وظهور الآية في النهار أبين، إذ تكثر المخالطة والذكر والعبادة. أما ذكر الليالي في مريم فناسب سياق القصة هناك وما فيه من مقابلة الليل والنهار.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين ثلاثة أيام وثلاث ليال.؛ العنوان الجزئي: تقابل الليل والنهار في قصتي زكريا.","url":""}]},{"id":"s3-808","number":808,"surah":3,"verses":[42],"references":[{"surah":3,"verses":[42]}],"verseLabel":"آل عمران: 42","question":"ما أثر تأنيث الفعل في ﴿وَإِذْ قَالَتِ الْمَلَائِكَةُ يَا مَرْيَمُ﴾ في مشهد الاصطفاء والتطهير؟","answer":"التأنيث جائز مع لفظ الملائكة، واختياره هنا ينسجم مع خطاب التكريم الهادئ الموجه إلى مريم: اصطفاء وتطهير وبشارة. فليست الصيغة مجرد احتمال نحوي، بل صوت تعبيري يوافق اللطف الذي يملأ المشهد.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، تأنيث فعل الملائكة في مقام الخير.؛ العنوان الجزئي: رقة الصيغة في خطاب الاصطفاء.","url":""}]},{"id":"s3-809","number":809,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما دلالة مجيء قوله تعالى: ﴿وَمِنَ الْمُقَرَّبِينَ﴾ بعد ﴿وَجِيهًا فِي الدُّنْيَا وَالْآخِرَةِ﴾؟","answer":"الوجاهة تصف المكانة الظاهرة، أما القرب فيصف المنزلة الخاصة عند الله. فجمع التعبير بين أثر الرسالة في الدنيا والآخرة، وبين منزلة العبد المقرب، حتى لا تُفهم الوجاهة على أنها مجرد قبول اجتماعي أو منزلة دنيوية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أوصاف عيسى عليه السلام.؛ العنوان الجزئي: اجتماع الوجاهة والقرب في وصف عيسى.","url":""}]},{"id":"s3-810","number":810,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما سر التعبير عن عيسى في الآية بثلاثة ألقاب وأسماء: ﴿الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ﴾، وما الأثر البلاغي لاختلاف هذه التسميات؟","answer":"«المسيح» لقب يدل على المنزلة والوصف، و«عيسى» اسم العلم، و«ابن مريم» كنية. فجمعها يعرّف بالمبشَّر به من جهات متعددة، ويهيئ لذكر خصائصه من غير أن يخلط بين اللقب والاسم والكنية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التفريق بين «المسيح» و«عيسى» و«ابن مريم».؛ العنوان الجزئي: المسيح لقب، وعيسى اسم، وابن مريم كنية.","url":""}]},{"id":"s3-811","number":811,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما سر ورود لقب ﴿الْمَسِيحُ﴾ في بشارة مريم ومقامات تصحيح الاعتقاد، وعدم جعله الاسم الغالب في سياق التكليف بالرسالة؟","answer":"«المسيح» لقب يبرز المنزلة ويكثر في الثناء أو في مناقشة ما قيل في عيسى وتصحيح الاعتقاد فيه. أما سياقات الرسالة وإيتاء البينات فتغلب فيها تسميته باسمه أو نسبه؛ فيختار القرآن من وجوه التعريف ما يخدم غرض المقام.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المسيح وعيسى وابن مريم بحسب المقام.؛ العنوان الجزئي: توزيع ألقاب عيسى على مقامات الثناء والعقيدة والرسالة.","url":""}]},{"id":"s3-812","number":812,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما سر وصف عيسى عليه السلام بأنه ﴿وَجِيهًا فِي الدُّنْيَا وَالْآخِرَةِ﴾ بعد التصريح باسمه ونسبه، وما الذي يضيفه قيدَا الزمان إلى البشارة؟","answer":"الوجاهة منزلة قبول ورفعة، وليست مجرد شهرة عابرة. وذكر الدنيا والآخرة يبين امتداد هذه المنزلة: فهو وجيه بين الناس في الدنيا بما آتاه الله من النبوة والآيات، ووجيه في الآخرة بما له من القرب والكرامة. فجاء القيدان لتقرير أن منزلته ثابتة في المرحلتين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أسماء عيسى وأوصافه في القرآن.؛ العنوان الجزئي: دلالة لقب «المسيح» ووصف عيسى بالوجاهة.","url":""}]},{"id":"s3-813","number":813,"surah":3,"verses":[46],"references":[{"surah":3,"verses":[46]}],"verseLabel":"آل عمران: 46","question":"ما دلالة وصف عيسى بأنه ﴿وَكَهْلًا﴾، وما الفرق بين الكهل والشيخ في هذا السياق؟","answer":"الكهل مرحلة بين الشباب والشيخوخة، ويُطلق غالبًا على من اكتملت قوته ونضجه قبل أن يبلغ سنّ الشيخوخة. لذلك فالوصف لا يعني أنه كان شيخًا، بل يشير إلى استمرار كلامه بالحق في المهد ثم في مرحلة النضج.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «كهلًا».؛ العنوان الجزئي: الفرق بين الكهل والشيخ في وصف عيسى.","url":""}]},{"id":"s3-814","number":814,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"ما سر مجيء اسم الإشارة في ﴿كَذَلِكِ اللَّهُ يَخْلُقُ مَا يَشَاءُ﴾ بالكسر، وما الذي يحدده هذا الكسر في الخطاب؟","answer":"الكاف في «ذلكِ» للمخاطبة، والخطاب هنا لمريم، فجاءت الكاف مكسورة لموافقة المخاطَب المؤنث. فالكسر ليس وصفًا للشيء المشار إليه، بل علامة على جهة الخطاب التي وُجِّه إليها البيان.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «ذلكِ» في خطاب مريم.؛ العنوان الجزئي: كسر الكاف في «ذلكِ» للمخاطبة المؤنثة.","url":""}]},{"id":"s3-815","number":815,"surah":3,"verses":[49],"references":[{"surah":3,"verses":[49]}],"verseLabel":"آل عمران: 49","question":"كيف يفهم التعبير عن عيسى بقوله: ﴿أَنِّي أَخْلُقُ لَكُم﴾، مع اختصاص الله بالخلق ابتداءً؟","answer":"للخلق استعمالان: خلق ابتداءً من غير مثال سابق، وهذا مختص بالله، وخلق بمعنى التقدير والتشكيل والصنع من مواد خلقها الله، وهذا يصح أن ينسب إلى الإنسان. فعيسى يصنع هيئة الطير من الطين، أما إيجادها حيّةً فبإذن الله، فانتفى توهم الاستقلال في الخلق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، معنى الخلق في «أحسن الخالقين» والاستشهاد بآية عيسى.؛ العنوان الجزئي: الفرق بين خلق الإيجاد وخلق التقدير.","url":""}]},{"id":"s3-816","number":816,"surah":3,"verses":[52],"references":[{"surah":3,"verses":[52]}],"verseLabel":"آل عمران: 52","question":"ما وجه اختلاف ختم جواب الحواريين بين ﴿وَاشْهَدْ بِأَنَّا مُسْلِمُونَ﴾ في آل عمران، و﴿وَاشْهَدْ بِأَنَّنَا مُسْلِمُونَ﴾ في المائدة؟","answer":"سياق آل عمران سياق استجابة عاجلة لنصرة عيسى بعد ظهور الكفر، فجاء التعبير أخف وأسرع. أما المائدة فسياق تعداد النعم والإقرار بها، فناسب زيادة التوكيد في ﴿بِأَنَّنَا﴾. فالاختلاف يخدم اختلاف المقام، ولا يدل على اختلاف أصل إسلام الحواريين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، جواب الحواريين في آل عمران والمائدة.؛ العنوان الجزئي: الفرق بين «بأنا مسلمون» و«بأننا مسلمون».","url":""}]},{"id":"s3-817","number":817,"surah":3,"verses":[59],"references":[{"surah":3,"verses":[59]}],"verseLabel":"آل عمران: 59","question":"ما سر التعبير عن خلق عيسى بقوله: ﴿إِنَّ مَثَلَ عِيسَى عِندَ اللَّهِ كَمَثَلِ آدَمَ﴾، مع أن عيسى وُلد من أم، وآدم لم يولد من أب ولا أم؟","answer":"المقصود إبطال دعوى أن الولادة الخارقة تستلزم الألوهية أو البنوة. فإذا كان آدم قد خُلق من تراب من غير أب ولا أم، فخلق عيسى من أم من غير أب ليس أعجب من ذلك. ووجه الشبه هو الخلق بقدرة الله، لا تماثل التفاصيل بين القصتين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الحجج العقلية في قصة عيسى.؛ العنوان الجزئي: المماثلة بين خلق عيسى وخلق آدم.","url":""}]},{"id":"s3-818","number":818,"surah":3,"verses":[59,65,66],"references":[{"surah":3,"verses":[59,65,66]}],"verseLabel":"آل عمران: 59، 65، 66","question":"كيف يتدرج الاحتجاج من قياس خلق عيسى بخلق آدم إلى إبطال المجادلة في إبراهيم بغير علم؟","answer":"قدمت السورة دليلًا عقليًا محسوس البنية: من خلق آدم بلا أب ولا أم لا يعجز عن خلق عيسى بلا أب. ثم كشفت التناقض التاريخي في نسبة إبراهيم إلى شريعة نزلت بعده، وختمت بذم الجدال فيما لا علم لهم به؛ فتدرجت من إقامة البرهان إلى كشف فساد دعوى الخصم ومنهجه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الحجج والبراهين وسيلة للتثبيت.؛ العنوان الجزئي: بناء الحجة ثم تقويض دعوى المجادل.","url":""}]},{"id":"s3-819","number":819,"surah":3,"verses":[64,84],"references":[{"surah":3,"verses":[64,84]}],"verseLabel":"آل عمران: 64، 84","question":"ما وجه التكامل بين الدعوة إلى ﴿كَلِمَةٍ سَوَاءٍ﴾ وإعلان الإيمان بجميع الأنبياء من غير تفريق؟","answer":"تبدأ الآية 64 من أصل مشترك هو توحيد العبادة ورفض اتخاذ البشر أربابًا، ثم تبين الآية 84 سعة الموقف الإسلامي من سلسلة الوحي كلها. فالحوار لا يبنى على محو المشترك ولا على تنازل عقدي، بل على توحيد خالص وإنصاف لجميع الرسل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، إيجاد نقاط الاتفاق في حوار أهل الكتاب.؛ العنوان الجزئي: التوحيد ووحدة الرسالات أساسًا للحوار.","url":""}]},{"id":"s3-820","number":820,"surah":3,"verses":[70,71,75],"references":[{"surah":3,"verses":[70,71,75]}],"verseLabel":"آل عمران: 70، 71، 75","question":"كيف يتصاعد العتاب من كفر أهل الكتاب بالآيات ولبس الحق إلى كشف أثر ذلك في الأمانة بالآية 75؟","answer":"بدأت المواجهة بكشف الخلل العلمي: كفر مع شهادة، ولبس مع معرفة. ثم أظهرت أثر الانحراف في السلوك حين سوّغ بعضهم أكل حقوق «الأميين» والكذب على الله. فالسياق يبين أن تحريف المعرفة لا يبقى فكرة، بل ينتهي إلى فساد في المعاملة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تحذير أهل الكتاب من التكذيب والكتمان.؛ العنوان الجزئي: من كتمان الحق إلى فساد السلوك.","url":""}]},{"id":"s3-821","number":821,"surah":3,"verses":[72],"references":[{"surah":3,"verses":[72]}],"verseLabel":"آل عمران: 72","question":"ما سر تحديد الإيمان المصطنع بقولهم: ﴿وَجْهَ النَّهَارِ﴾، ثم الكفر في ﴿آخِرَهُ﴾؟","answer":"جعلوا أول النهار ميدانًا لإظهار الإيمان وآخره ميدانًا لإظهار الكفر ليوقعوا الشك في نفوس المؤمنين، كأن التراجع وقع بعد اختبار قصير. فالتحديد الزمني يصور الخطة بوصفها تمثيلية مقصودة، لا تحولًا حقيقيًا في الاعتقاد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، خطة الإيمان في وجه النهار والكفر في آخره.؛ العنوان الجزئي: التوقيت المقصود في فتنة أهل الكتاب.","url":""}]},{"id":"s3-822","number":822,"surah":3,"verses":[75,199],"references":[{"surah":3,"verses":[75,199]}],"verseLabel":"آل عمران: 75، 199","question":"ما سر توكيد وجود المؤمنين من أهل الكتاب بـ﴿إِنَّ﴾ واللام، مع عدم هذا التوكيد في وصف من يؤدي الأمانة في الآية 75؟","answer":"أداء الأمانة موجود في الناس بكثرة، ومن أهل الكتاب من يؤديها بلا استغراب كبير. أما انتقال المرء عن معتقده السابق وإيمانه بالوحي الجديد خاشعًا لله فحالة أندر؛ لذلك قُوِّي الخبر بما يزيل استبعاد السامع ويثبت وقوعه.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، تفاوت التوكيد بين الأمانة والإيمان.؛ العنوان الجزئي: زيادة التوكيد بقدر ندرة الخبر.","url":""}]},{"id":"s3-823","number":823,"surah":3,"verses":[92],"references":[{"surah":3,"verses":[92]}],"verseLabel":"آل عمران: 92","question":"ما سر التعبير بـ﴿لَن تَنَالُوا الْبِرَّ حَتَّى تُنفِقُوا مِمَّا تُحِبُّونَ﴾، وما الذي يضيفه «مما تحبون»؟","answer":"«لن تنالوا البر» يصور البر منزلة يسعى الإنسان إلى بلوغها، لا مجرد عمل جزئي. ثم اشترط الإنفاق من المحبوب ليظهر صدق البذل؛ فالإنفاق مما لا يحتاجه المرء أسهل، أما إخراج المحبوب فيكشف تغلب الإيمان على شح النفس. ولذلك ارتبطت الآية بمعنى كمال الخير وشموله.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الإنفاق من المحبوب ونيل البر.؛ العنوان الجزئي: معنى «البر» وضمير «تحبون» في آية 92.","url":""}]},{"id":"s3-824","number":824,"surah":3,"verses":[101],"references":[{"surah":3,"verses":[101]}],"verseLabel":"آل عمران: 101","question":"ما دلالة الاستفهام في قوله تعالى: ﴿وَكَيْفَ تَكْفُرُونَ﴾ بعد ذكر تلاوة الآيات ووجود الرسول؟","answer":"الاستفهام إنكاري تعجبي، لأن أسباب الثبات حاضرة: آيات الله تُتلى، والرسول بين المؤمنين. فالكفر بعد هذه النعم ليس مجرد خطأ في الاستدلال، بل انقلاب عن مقتضى البيان والصحبة النبوية. ثم جاء الاعتصام بالله علاجًا عمليًا لهذا الانقلاب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وسائل الثبات في سياق آل عمران.؛ العنوان الجزئي: الاستفهام الإنكاري في «وكيف تكفرون».","url":""}]},{"id":"s3-825","number":825,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"ما دلالة افتتاح الأمر بقوله تعالى: ﴿وَلْتَكُن مِّنكُمْ أُمَّةٌ﴾ بعد الأمر بالاعتصام والنهي عن التفرق؟","answer":"الاعتصام يحفظ وحدة الجماعة، ثم يأتي الأمر بوجود أمة تدعو إلى الخير لتحفظ هذه الوحدة من الداخل بالفعل الإيجابي. فليست الجماعة المطلوبة مجرد تجمع ساكن، بل جماعة تقوم بالدعوة والأمر بالمعروف والنهي عن المنكر؛ وبذلك يتحول الاجتماع إلى رسالة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الدعوة إلى الخير وسيلة للثبات.؛ العنوان الجزئي: الصلة بين الاعتصام والدعوة إلى الخير.","url":""}]},{"id":"s3-826","number":826,"surah":3,"verses":[109],"references":[{"surah":3,"verses":[109]}],"verseLabel":"آل عمران: 109","question":"ما دلالة تقديم ﴿لِلَّهِ﴾ في قوله: ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ عقب الحديث عن تبييض الوجوه وتسـويدها؟","answer":"التقديم يقرر اختصاص الملك الحقيقي بالله، فيأتي الجزاء السابق صادرًا عن المالك الذي لا يخرج شيء عن سلطانه. فليس اختلاف المصائر حكمًا منفصلًا عن ملكه، بل هو تصرف العدل في ملكه، ولذلك أعقبه برجوع الأمور كلها إليه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تفصيل ملك السماوات والأرض.؛ العنوان الجزئي: اختصاص الملك بالله في ختام مقطع الجزاء.","url":""}]},{"id":"s3-827","number":827,"surah":3,"verses":[109],"references":[{"surah":3,"verses":[109]}],"verseLabel":"آل عمران: 109","question":"ما سر الانتقال من ملك الموجودات في ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ إلى رجوع الشؤون في ﴿وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ﴾؟","answer":"صدر الآية يقرر أن الذوات كلها ملك لله، وخاتمتها تقرر أن العواقب والتدبير والقضاء ترجع إليه كذلك. فاجتمع ملك الموجودات ومرجع الأمور، ليكتمل معنى السلطان الإلهي ولا يتوهم أن شيئًا من الخلق أو التدبير خارج عنه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ملك السماوات والأرض ومرجع الأمور.؛ العنوان الجزئي: الجمع بين الملك والمرجع.","url":""}]},{"id":"s3-828","number":828,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سر تقييد خيرية الأمة بقوله: ﴿أُخْرِجَتْ لِلنَّاسِ﴾، لا بمجرد قوله «كنتم خير أمة»؟","answer":"القيد ينقل الخيرية من امتياز مغلق إلى رسالة نافعة للناس؛ فالأمة أُظهرت لتقوم بوظيفة الأمر بالمعروف والنهي عن المنكر والإيمان بالله. ومن ثم فخيريتها مرتبطة بأداء ما أُخرجت له، لا بالاسم أو الانتساب وحدهما.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، معنى إخراج الأمة للناس.؛ العنوان الجزئي: الخيرية بوصفها وظيفة ورسالة.","url":""}]},{"id":"s3-829","number":829,"surah":3,"verses":[111],"references":[{"surah":3,"verses":[111]}],"verseLabel":"آل عمران: 111","question":"ما وجه المقابلة بين ﴿لَن يَضُرُّوكُمْ إِلَّا أَذًى﴾ في الآية 111، و﴿لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْئًا﴾ في الآية 120؟","answer":"في الآية 111 ذُكر ما قد يصدر منهم من أذى محسوس أو كلامي، مع نفي بلوغه درجة الضرر. وفي الآية 120 عُلّق انتفاء أثر الكيد على الصبر والتقوى؛ فصار الكيد كله عديم الأثر، وجاء التعبير بـ«شيئًا» لتأكيد استئصال النفع منه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الأذى والضرر وكيد أهل الكتاب.؛ العنوان الجزئي: تفاوت التعبير بحسب مقام الأذى ومقام الكيد.","url":""}]},{"id":"s3-830","number":830,"surah":3,"verses":[111,120],"references":[{"surah":3,"verses":[111,120]}],"verseLabel":"آل عمران: 111، 120","question":"ما الدلالة البيانية لاختلاف القراءة في ﴿لَا يَضُرُّكُمْ﴾، مع قوله ﴿لَن يَضُرُّوكُمْ إِلَّا أَذًى﴾؟","answer":"القراءة بالفتح أخف في النطق والدلالة، فتشير إلى أن الضرر لا يقع حقيقة، أما الضم فأثقل، فيوحي ببقاء أذى أو أثر لا يبلغ حد الضرر المستقر. ولذلك جاء سياق الصبر والتقوى مناسبًا لاحتمال بقاء شيء من الأذى مع انتفاء الضرر الحقيقي.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف القراءة في «لا يضرّكم» ودلالة الثقل والخفة.؛ العنوان الجزئي: دلالة اختلاف القراءة في «يضرّكم».","url":""}]},{"id":"s3-831","number":831,"surah":3,"verses":[120,121],"references":[{"surah":3,"verses":[120,121]}],"verseLabel":"آل عمران: 120، 121","question":"ما دلالة الانتقال من مواجهة كيد أهل الكتاب في الآية 120 إلى مشهد ترتيب الصفوف في أُحد في الآية 121؟","answer":"بهذا الانتقال تنتقل السورة من الثبات أمام الأفكار والخصوم من الخارج إلى الثبات العملي داخل الصف المؤمن. فختمت المواجهة الفكرية بالصبر والتقوى، ثم شرعت في اختبار الطاعة والانضباط، ليظهر أن الثبات بناء متكامل لا موقف ذهني فحسب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، انقسام السورة إلى الثبات الخارجي والداخلي.؛ العنوان الجزئي: الانتقال من الثبات الفكري إلى الثبات العملي.","url":""}]},{"id":"s3-832","number":832,"surah":3,"verses":[121,152],"references":[{"surah":3,"verses":[121,152]}],"verseLabel":"آل عمران: 121، 152","question":"ما سر بدء قصة أُحد بذكر ترتيب المؤمنين للقتال، ثم تأخير العتاب الصريح على الفشل والتنازع إلى الآية 152؟","answer":"بُني السياق على التثبيت قبل العتاب: ذكّرهم الله بولايته ونصره في بدر وبإمداد الملائكة، ثم واجههم بسبب الخلل بعد رفع معنوياتهم. فكان العتاب مربيًا لا محطمًا، يحفظ الانتماء ويكشف الخطأ في الوقت نفسه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تسلسل معالجة غزوة أُحد.؛ العنوان الجزئي: تقديم التثبيت على العتاب.","url":""}]},{"id":"s3-833","number":833,"surah":3,"verses":[130,152],"references":[{"surah":3,"verses":[130,152]}],"verseLabel":"آل عمران: 130، 152","question":"ما وجه إدخال النهي عن الربا في أثناء الحديث عن أُحد قبل العودة إلى بيان أسباب الهزيمة؟","answer":"لم يأت النهي مقطوعًا عن سياق المعركة؛ فالربا من الشهوات التي تفسد المجتمع وتثير التنازع، والسورة تكشف أن الهزيمة تبدأ من خلل الطاعة والقيم قبل أن تظهر في الميدان. لذلك عالجت أسباب الضعف الداخلي ثم عادت إلى تفاصيل أُحد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، صلة آية الربا بأسباب الهزيمة والثبات.؛ العنوان الجزئي: الربا عائقًا من عوائق الثبات.","url":""}]},{"id":"s3-834","number":834,"surah":3,"verses":[132,159],"references":[{"surah":3,"verses":[132,159]}],"verseLabel":"آل عمران: 132، 159","question":"ما وجه الصلة بين الأمر بـ﴿أَطِيعُوا اللَّهَ وَالرَّسُولَ﴾، ثم الأمر للنبي ﷺ بالعفو والاستغفار والمشاورة بعد خطأ أُحد؟","answer":"الطاعة تحفظ الجماعة من التنازع، لكن وقوع المخالفة لا يعني هدمها؛ لذلك جاء العلاج النبوي بالعفو والاستغفار والشورى. فجمع السياق بين حزم المرجعية ورحمة القيادة، وهما معًا من أسباب بقاء الصف وثباته.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المعالجة المتدرجة لأحداث أُحد، وقاعدة التعبير في طاعة الله والرسول.؛ العنوان الجزئي: الطاعة ورحمة القيادة في بناء الصف.","url":""}]},{"id":"s3-835","number":835,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما دلالة قوله ﴿مِنْ رَبِّكُمْ﴾ بعد «مغفرة»، وما الذي يضيفه هذا القيد إلى الرجاء؟","answer":"ذكر الربوبية يقرّب معنى العناية والرحمة والتربية؛ فالمغفرة مطلوبة من رب يتولى عباده ويرعاهم. ولهذا كان التعبير أوقع في الترغيب من قول مختصر لا يبرز جهة المنعم والمغفر.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وصل المغفرة بقوله «من ربكم».؛ العنوان الجزئي: مناسبة ذكر الربوبية في مقام المغفرة.","url":""}]},{"id":"s3-836","number":836,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما سر اختيار ﴿وَسَارِعُوا﴾، لا «وأسرعوا»؟","answer":"صيغة «سارعوا» أبلغ في طلب المبادرة والمبالغة في الإسراع، وتصور جماعة تتنافس في التوجه إلى المغفرة. أما «أسرعوا» فكانت تدل على مجرد السرعة دون هذا الإيحاء بالمبادرة والمسابقة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وسارعوا وصيغة المبالغة في طلب الإسراع.؛ العنوان الجزئي: المبالغة في «سارعوا».","url":""}]},{"id":"s3-837","number":837,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"ما سر التعبير بـ﴿يُنْفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ﴾، وما الذي يضيفه ذكر الحالين؟","answer":"ذكر السراء والضراء يخرج الإنفاق من كونه سلوكًا مرتبطًا بالرخاء إلى كونه خلقًا ثابتًا في الشدة واليسر. فالمتقون لا ينتظرون فائض المال، بل يثبتون على البذل حتى حين تكون الحاجة والمشقة حاضرتين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الإنفاق في السراء والضراء.؛ العنوان الجزئي: ثبات الإنفاق في حالتي اليسر والعسر.","url":""}]},{"id":"s3-838","number":838,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"ما الذي يكشفه المضارع في ﴿مَن يُرِدْ ثَوَابَ الْآخِرَةِ﴾ عن طبيعة إرادة الثواب؟","answer":"المضارع يلائم الإرادة المتجددة؛ فالأعمال تتكرر، ومع كل عمل تتجدد نية الثواب. أما قوله في الإسراء ﴿وَمَنْ أَرَادَ الْآخِرَةَ﴾ فالمقصود به الوجهة الكبرى الواحدة التي اختارها الإنسان، فجاء الماضي أنسب لحسم الاختيار.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الماضي والمضارع في إرادة الآخرة وثوابها.؛ العنوان الجزئي: تجدد إرادة الثواب ووحدة إرادة الآخرة.","url":""}]},{"id":"s3-839","number":839,"surah":3,"verses":[145,144],"references":[{"surah":3,"verses":[145,144]}],"verseLabel":"آل عمران: 145، 144","question":"ما سر وصف أصحاب الثبات بالشكر في ختام الآيتين، مع أن المقام مقام قتال وصبر؟","answer":"الثبات بعد شائعة موت الرسول ﷺ اعتراف عملي بأن الرسالة نعمة لا تتوقف على حياة فرد، ولو كان الرسول نفسه. ومن يثبت ولا ينقلب فقد حفظ النعمة وأدى حقها، فكان وصف الشاكرين أعمق من وصف الصابرين وحده.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اتساق «سيجزي» و«سنجزي الشاكرين».؛ العنوان الجزئي: الثبات صورة من صور شكر نعمة الرسالة.","url":""}]},{"id":"s3-840","number":840,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"ما الأثر البلاغي لاختلاف القراءتين في ﴿مَا كَانَ قَوْلُهُمْ﴾ و﴿مَا كَانَ قَوْلَهُمْ﴾؟","answer":"قراءة الرفع تفيد أن هذا الدعاء هو القول الذي لم يقولوا غيره في ذلك الموقف. وقراءة النصب تفيد أن هذا القول لم يصدر إلا عنهم، فالأولى تمدح مضمون الدعاء، والثانية تمدح قائليه؛ وباجتماع القراءتين يتكامل مدح المقال وأهله.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المعنى البلاغي لاختلاف القراءتين في «قولهم».؛ العنوان الجزئي: تكامل المعنى بين رفع «قولهم» ونصبه.","url":""}]},{"id":"s3-841","number":841,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما دلالة ختام مشهد المخالفة بقوله: ﴿وَلَقَدْ عَفَا عَنْكُمْ﴾، مع ذكر الفشل والتنازع والعصيان قبلها؟","answer":"يوازن السياق بين كشف الخطأ وفتح باب الرحمة؛ فلم يحجب العفوَ وقوعُ المخالفة، بل جاء بعد بيانها ليمنع اليأس ويقرر أن العتاب القرآني إصلاح لا مجرد إدانة. ثم يذكر فضل الله على المؤمنين ليؤكد أن النجاة فضل ورحمة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، العفو بعد بيان أسباب الهزيمة.؛ العنوان الجزئي: مجيء العفو بعد العتاب.","url":""}]},{"id":"s3-842","number":842,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما دلالة مجيء ﴿ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ﴾ بعد الفشل والتنازع والعصيان؟","answer":"«ثم» ترتب التحول في المشهد بعد أن ظهرت أسباب الخلل من جانبهم، فجاء الصرف عن العدو نتيجةً تربوية للابتلاء لا مجرد هزيمة مفاجئة. وبذلك يربط السياق بين السلوك الداخلي والنتيجة الخارجية في المعركة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تسلسل أحداث أحد والابتلاء.؛ العنوان الجزئي: ترتيب الفشل والصرف والابتلاء.","url":""}]},{"id":"s3-843","number":843,"surah":3,"verses":[152,154],"references":[{"surah":3,"verses":[152,154]}],"verseLabel":"آل عمران: 152، 154","question":"كيف يتدرج علاج أُحد من ﴿وَلَقَدْ عَفَا عَنْكُمْ﴾ إلى ﴿أَمَنَةً نُّعَاسًا﴾ ثم إلى تمحيص القلوب؟","answer":"بدأ العلاج بإزالة اليأس بإعلان العفو، ثم أعاد إلى الطائفة المؤمنة سكينتها بنعاس الأمن، ثم كشف ما في النفوس ومحص القلوب. فالخطاب لا يكتفي بتسجيل الخطأ، بل ينقل الجماعة من الذنب إلى الطمأنينة ثم إلى التربية الداخلية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التثبيت والعتاب في تسلسل أُحد، وآية 154.؛ العنوان الجزئي: مراحل إعادة بناء الصف بعد الهزيمة.","url":""}]},{"id":"s3-844","number":844,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما دلالة رسم ﴿لِكَيْلَا﴾ موصولة في آل عمران، مقابل ﴿كَيْ لَا﴾ مفصولة في الحشر؟","answer":"يربط الدكتور السامرائي بين الوصل في آل عمران واتصال الغمين: غم الهزيمة وغم فوات الغنائم. أما الحشر فالسياق في تفريق المال حتى لا يكون دولة بين الأغنياء، فناسبه الفصل في الرسم، مع التنبيه إلى أن الرسم ليس قاعدة مطردة مستقلة عن السياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، لكيلا الوصل والفصل بحسب المعنى.؛ العنوان الجزئي: مناسبة رسم «لكيلا» لاتصال الغم أو انفصال المال.","url":""}]},{"id":"s3-845","number":845,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما دلالة الجمع بين ﴿مَا فِي صُدُورِكُمْ﴾ و﴿مَا فِي قُلُوبِكُمْ﴾ في آية واحدة؟","answer":"الصدور وعاء لما يختلج ويُخفى، فناسبها فعل الابتلاء الذي يكشف، والقلوب محل الاعتقاد والنية، فناسبها التمحيص الذي ينقي. وبذلك لم يكن التعبيران تكرارًا، بل وزع كل لفظ على المرحلة التي تلائمه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، برنامج لمسات بيانية — آية 154.؛ العنوان الجزئي: ملاءمة الصدور للابتلاء والقلوب للتمحيص.","url":""}]},{"id":"s3-846","number":846,"surah":3,"verses":[155,165],"references":[{"surah":3,"verses":[155,165]}],"verseLabel":"آل عمران: 155، 165","question":"ما وجه التكامل بين ﴿بِبَعْضِ مَا كَسَبُوا﴾ و﴿قُلْ هُوَ مِنْ عِندِ أَنْفُسِكُمْ﴾ في تفسير مصيبة أُحد؟","answer":"الأولى تكشف المدخل الباطني الذي استغله الشيطان، والثانية تحمل الجماعة مسؤولية النتيجة التي ترتبت على الاختيار والمخالفة. فاجتمع تحليل السبب النفسي مع تقرير المسؤولية العملية، حتى لا تُنسب الهزيمة إلى القدر على وجه يعطل المحاسبة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، عوائق الثبات في الآيتين 155 و165.؛ العنوان الجزئي: من زلة النفس إلى مسؤولية النتيجة.","url":""}]},{"id":"s3-847","number":847,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"ما دلالة تسمية من خالفوا المجاهدين ﴿لِإِخْوَانِهِمْ﴾، مع اختلاف موقفهم عن موقف المؤمنين؟","answer":"الأخوة هنا أخوة نسب وقوم، لا أخوة إيمان؛ فكانوا من بني قومهم وإن خالفوا المجاهدين في الاعتقاد والموقف. وهذا يزيد أثر قولهم سوءًا، لأن القريب الذي يثبط عن الجهاد يلبس نصيحته ثوب الشفقة وهو يزرع الحسرة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الأخوة النسبية في آية 156.؛ العنوان الجزئي: الأخوة النسبية لا الأخوة الإيمانية.","url":""}]},{"id":"s3-848","number":848,"surah":3,"verses":[156,158],"references":[{"surah":3,"verses":[156,158]}],"verseLabel":"آل عمران: 156، 158","question":"ما وجه تخصيص سياق آل عمران بالموت في الغربة والجهاد، مقابل الموت على الفراش في سورة المؤمنون؟","answer":"آيات آل عمران تعالج وهم الذين ظنوا أن البقاء في البيوت يمنع الموت، فجاءت في سياق السفر والغزو والشهادة. أما المؤمنون فسياقها في إنكار البعث بعد الموت، فناسب ذكر الموت الذي يتصوره الناس على الفراش، فجاء كل سياق بما يثير شبهته ويجيب عنها.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف سياق الموت بين آل عمران والمؤمنون.؛ العنوان الجزئي: الموت في الغربة والموت على الفراش.","url":""}]},{"id":"s3-849","number":849,"surah":3,"verses":[157,158],"references":[{"surah":3,"verses":[157,158]}],"verseLabel":"آل عمران: 157، 158","question":"ما الأثر البلاغي لاختلاف حركة الميم في ﴿مُتُّمْ﴾ بآل عمران، و﴿مِتُّمْ﴾ في سورة المؤمنون؟","answer":"الضمة أثقل الحركات، فجاءت في سياق الموت المرتبط بالغربة والغزو والشهادة، وهو أشد على النفس من الموت على الفراش بين الأهل الذي يتحدث عنه سياق المؤمنون. فاختيار الحركة يوافق ثقل المشهد وشدته، لا مجرد اختلاف لهجي.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ثقل الضمة ومناسبة سياق الموت.؛ العنوان الجزئي: مناسبة حركة الميم لشدة السياق.","url":""}]},{"id":"s3-850","number":850,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"ما الفرق البلاغي بين ﴿إِن يَنصُرْكُمُ اللَّهُ﴾ و﴿إِن يَخْذُلْكُمْ﴾، وما الذي يضيفه لفظ الخذلان؟","answer":"النصر هو إعانة المؤمنين وتأييدهم، أما الخذلان فترك النصرة ورفع المعونة عنهم. فالمقابلة لا تتحدث عن هزيمة مجردة، بل ترد الأمر كله إلى جهة النصرة: إن تولى الله عباده فلا غالب لهم، وإن ترك نصرتهم فلا ناصر بعده.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الخذلان والنصرة.؛ العنوان الجزئي: الخذلان ترك النصرة.","url":""}]},{"id":"s3-851","number":851,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"ما سر مجيء الشرطين في الآية متقابلين: ﴿إِن يَنصُرْكُمُ اللَّهُ﴾ و﴿إِن يَخْذُلْكُمْ﴾؟","answer":"جمع الشرطان طرفي حال المؤمن في الصراع: نصر يزيل كل غلبة، وترك للنصرة لا يملك معه أحد أن ينقذ. وبذلك ينتقل السياق من تقرير القدرة الإلهية إلى بناء التوكل العملي على هذا التقرير.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المقابلة بين النصر والخذلان.؛ العنوان الجزئي: المقابلة بين النصر والخذلان.","url":""}]},{"id":"s3-852","number":852,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سر اختلاف التعبير بين ﴿وَمَأْوَاهُ جَهَنَّمُ﴾ في آل عمران، و﴿مَأْوَاكُمُ النَّارُ هِيَ مَوْلَاكُمْ﴾ في سورة الحديد؟","answer":"آية آل عمران تتحدث عن الكافرين وهم في الدنيا، فناسبها الإخبار بأن جهنم مأواهم ومصيرهم. أما آية الحديد فجاءت في مشهد الآخرة بعد أن صار العذاب حاضرًا قريبًا منهم، فقيل: ﴿هِيَ مَوْلَاكُمْ﴾؛ أي هي التي تليهم وتحيط بهم، لا مجرد مأوى مستقبل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «مأواه جهنم» و«هي مولاكم».؛ العنوان الجزئي: اختلاف «المأوى» و«المولى» باختلاف مقام الدنيا والآخرة.","url":""}]},{"id":"s3-853","number":853,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سر قوله في آل عمران: ﴿وَمَأْوَاهُ جَهَنَّمُ﴾، وفي الحديد: ﴿مَأْوَاكُمُ النَّارُ هِيَ مَوْلَاكُمْ﴾؟","answer":"آية آل عمران تتحدث عن فرد صيغ في صورة «من» فاتسق معها ضمير المفرد ومأواه، أما الحديد فخطاب لجماعة المنافقين والكافرين فناسبه الجمع. وزادت آية الحديد ﴿هِيَ مَوْلَاكُمْ﴾ لأن المقام مقام مواجهة مباشرة وقطع لما كانوا يرجونه من نصير.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف ختام آيتي آل عمران والحديد.؛ العنوان الجزئي: الإفراد والجمع وزيادة «هي مولاكم».","url":""}]},{"id":"s3-854","number":854,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما دلالة تقديم ﴿وَيُزَكِّيهِمْ﴾ على ﴿وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ﴾ في آل عمران، مع عكس الترتيب في دعاء إبراهيم؟","answer":"دعاء إبراهيم يصف ما يرجوه من بعثة الرسول، فذكر التعليم ثم التزكية. أما في مقام بيان بعثة الرسول واقعًا، فقدّمت التزكية؛ لأن القلب إذا لم يتهذب ولم يتهيأ لم ينتفع بالكتاب والحكمة على وجههما. فاختلاف الترتيب تابع لاختلاف مقام الدعاء عن مقام تحقق النعمة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف ترتيب التزكية والتعليم.؛ العنوان الجزئي: التقديم والتأخير بين التزكية والتعليم.","url":""}]},{"id":"s3-855","number":855,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سر افتتاح الآية بقوله: ﴿لَقَدْ مَنَّ اللَّهُ﴾، بينما افتتحت آية الجمعة بقوله: ﴿هُوَ الَّذِي بَعَثَ﴾؟","answer":"«لقد منّ» يصرّح بالنعمة ويستحضر أثرها في المؤمنين، ولذلك ناسب مقام التذكير بفضل الرسالة عليهم. أما «هو الذي بعث» فجاء في مقام التعريف بفاعل البعث وإثبات قدرته، فناسبه ضمير الفصل والإخبار عن فعل الله دون التركيز على تعداد المنن.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف مقام الامتنان عن مقام الإخبار بالبعثة.؛ العنوان الجزئي: «لقد منّ» و«هو الذي بعث» بحسب المقام.","url":""}]},{"id":"s3-856","number":856,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"ما سر اختيار الفعل ﴿فَادْرَؤُوا﴾ في قوله تعالى: ﴿فَادْرَؤُوا عَنْ أَنفُسِكُمُ الْمَوْتَ﴾ بدل «فاحموا أنفسكم»؟","answer":"الدرء هو الدفع، وفيه تصوير للموت خطرًا مباغتًا قويًا لا يملك الإنسان مقاومته متى جاء. أما الحماية فتناسب خطرًا منظورًا يستطيع المرء أن يراه ويتخذ له وقاية؛ لذلك جاء اللفظ موافقًا لمفاجأة الموت واستحالة دفعه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «فادرؤوا» في مواجهة الموت.؛ العنوان الجزئي: الدرء والدفع في تصوير مفاجأة الموت.","url":""}]},{"id":"s3-857","number":857,"surah":3,"verses":[169,171],"references":[{"surah":3,"verses":[169,171]}],"verseLabel":"آل عمران: 169، 171","question":"ما سر انتقال وصف الشهداء من النهي عن حسبانهم أمواتًا إلى أفعال الحياة: ﴿يُرْزَقُونَ﴾ و﴿فَرِحِينَ﴾ و﴿يَسْتَبْشِرُونَ﴾؟","answer":"لم يكتف النص بنفي الموت عنهم، بل ملأ صورة حياتهم بالحركة والرزق والفرح والبشارة. وبهذا تتحول الحقيقة الغيبية إلى مشهد حي يثبت المؤمنين، فلا تبدو الشهادة فقدًا مجردًا بل انتقالًا إلى كرامة متجددة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وصف الشهداء في سياق تثبيت السورة، ودلالة «من خلفهم».؛ العنوان الجزئي: بناء صورة الحياة بعد نفي الموت.","url":""}]},{"id":"s3-858","number":858,"surah":3,"verses":[170],"references":[{"surah":3,"verses":[170]}],"verseLabel":"آل عمران: 170","question":"ما سر جمع بشارة الشهداء لإخوانهم بين ﴿أَلَّا خَوْفٌ عَلَيْهِمْ﴾ و﴿وَلَا هُمْ يَحْزَنُونَ﴾؟","answer":"الخوف يتجه إلى ما يُستقبل، والحزن يتعلق بما فات؛ فجمعت البشارة الأمن من المستقبل والسلامة من أسى الماضي. وبذلك أحاطت الطمأنينة بزمني النفس كليهما، وهو أبلغ في تثبيت من بقي في طريق الجهاد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، استبشار الشهداء بمن خلفهم.؛ العنوان الجزئي: نفي الخوف والحزن عن اللاحقين.","url":""}]},{"id":"s3-859","number":859,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"ما وجه زيادة الإيمان بعد سماع خبر الخطر في قوله تعالى: ﴿فَزَادَهُمْ إِيمَانًا﴾؟","answer":"الخوف كشف مقدار اعتمادهم على الله، فلم يتحول الخبر عندهم إلى هلع، بل إلى يقين بقدرته وثقة بوعده. لذلك قابلوا التهديد بقولهم: ﴿حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾، فصار ما أراده المخوِّفون سببًا في تقوية الإيمان بدل إضعافه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الخوف المتوقع وأثره في زيادة الإيمان.؛ العنوان الجزئي: انقلاب التخويف إلى يقين وتوكل.","url":""}]},{"id":"s3-860","number":860,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"ما سر الجمع بين ﴿بِنِعْمَةٍ مِّنَ اللَّهِ وَفَضْلٍ﴾، مع أن المؤمنين لم يذكروا حصول غنيمة أو مكسب مادي؟","answer":"النعمة هنا سلامتهم من السوء، والفضل عناية الله التي ثبّتتهم وأبطل بها كيد عدوهم، ثم أضاف إليهما اتباع رضوانه. فليس الفضل مقصورًا على زيادة المال؛ قد يكون أعظم الفضل أن ينجو المؤمن ويحفظ دينه ويعود ثابت القلب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، النعمة والفضل في نجاة المؤمنين.؛ العنوان الجزئي: شمول النعمة والفضل للنجاة والهداية.","url":""}]},{"id":"s3-861","number":861,"surah":3,"verses":[176,178],"references":[{"surah":3,"verses":[176,178]}],"verseLabel":"آل عمران: 176، 178","question":"ما وجه اختلاف خواتيم الآيات بين ﴿عَذَابٌ عَظِيمٌ﴾ و﴿عَذَابٌ أَلِيمٌ﴾ و﴿عَذَابٌ مُّهِينٌ﴾؟","answer":"الذين يسارعون في الكفر ويُحرمون حظ الآخرة ناسبهم وصف العذاب بالعظيم لشدة ما ينتظرهم. والذين اشتروا الكفر بالإيمان خاسرون، فناسب الخسران وصف العذاب بالأليم. أما من أُمهل حتى يزداد إثمًا، فجزاء فعله عذاب مهين يفضح ما ظنه خيرًا لنفسه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف «عظيم» و«أليم» و«مهين».؛ العنوان الجزئي: مناسبة وصف العذاب لحال كل فريق.","url":""}]},{"id":"s3-862","number":862,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما سر زيادة اللام في ﴿لَقَدْ سَمِعَ اللَّهُ﴾ عند قولهم: ﴿إِنَّ اللَّهَ فَقِيرٌ﴾، مقابل ﴿قَدْ سَمِعَ اللَّهُ﴾ في شكوى المجادِلة؟","answer":"قولهم في حق الله افتراء بالغ الجسارة، وتلاه وعيد بالكتابة والعذاب؛ فناسبه توكيد السماع بلام القسم و«قد». أما شكوى المرأة فمقام رحمة وإجابة لا مقام إنكار لقول شنيع، فجاء التحقيق بـ«قد» من غير اللام.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «لقد سمع» و«قد سمع».؛ العنوان الجزئي: زيادة التوكيد بقدر فظاعة المقول.","url":""}]},{"id":"s3-863","number":863,"surah":3,"verses":[182],"references":[{"surah":3,"verses":[182]}],"verseLabel":"آل عمران: 182","question":"ما سر استعمال ﴿بِمَا قَدَّمَتْ أَيْدِيكُمْ﴾ في آل عمران والأنفال، واستعمال ﴿بِمَا كَسَبَتْ أَيْدِي النَّاسِ﴾ في مواضع أخرى؟","answer":"التقديم يلحظ ما يقدمه الإنسان لآخرته من عمل، ولا يلزم أن يكون في سياق الكسب والاستحواذ. أما «الكسب» فيناسب جمع الشيء والاستحواذ عليه، ولذلك جاء في سياقات تتعلق بما اكتسبه الناس من فساد أو سوء تصرف. فاختيار اللفظ تابع لطبيعة العمل وسياقه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «قدمت أيديكم» و«كسبت أيدي الناس».؛ العنوان الجزئي: التقديم للآخرة والكسب في سياق الاستحواذ.","url":""}]},{"id":"s3-864","number":864,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما دلالة جمعهم بين طلب ﴿قُرْبَانٍ تَأْكُلُهُ النَّارُ﴾، ثم تذكيرهم بأن الرسل جاءوا ﴿بِالْبَيِّنَاتِ وَبِالَّذِي قُلْتُمْ﴾؟","answer":"أعاد الرد عليهم علامتهم المقترحة نفسها، فلم يكتف بذكر البينات العامة؛ لقد جاء رسل سابقون بالدلائل وبالقربان الذي اشترطوه، ومع ذلك قتلوهم. فالتعبير يسقط عذرهم من داخله ويكشف أن المشكلة ليست نقص الآية بل رفض الحق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، آية القربان وصياغة الحجة.؛ العنوان الجزئي: إلزام المعترضين بشرطهم السابق.","url":""}]},{"id":"s3-865","number":865,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما سر تأنيث الفعل في ﴿تَأْكُلُهُ النَّارُ﴾، ثم تذكير الفعل في قوله: ﴿جَاءَكُمْ رُسُلٌ﴾؟","answer":"جاء كل فعل على مقتضى فاعله: النار مؤنثة لفظًا فأنث فعلها، والرسل جمع تكسير للعقلاء يغلب معه اعتبار معنى الجماعة المذكرة في هذا السياق. وليس الاختلاف شكليًا؛ فقد حافظ التعبير على الصورة الحية للنار الآكلة وعلى استقلال الرسل بالفعل والحجة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التذكير والتأنيث في آية القربان.؛ العنوان الجزئي: ملاءمة الفعل لفاعله في مشهد الحجة.","url":""}]},{"id":"s3-866","number":866,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما وجه الصلة بين ﴿فَمَن زُحْزِحَ عَنِ النَّارِ﴾ في آل عمران، و﴿سَيُجَنَّبُهَا الْأَتْقَى﴾ في سورة الليل؟","answer":"التعبيران يبرزان أن النجاة من النار ليست بقدرة الإنسان المستقلة؛ فالعبد يُزحزح عنها أو يُجنَّبها بفعل الله وتوفيقه. وفي ذلك تصحيح للتصور الذي يجعل التقوى وحدها سببًا مستقلًا للنجاة، مع كونها سببًا شرعيًا لا يستغني عن رحمة الله.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، النجاة من النار بين «زحزح» و«يجنبها».؛ العنوان الجزئي: إسناد النجاة إلى فعل الله تعالى.","url":""}]},{"id":"s3-867","number":867,"surah":3,"verses":[187,188,199],"references":[{"surah":3,"verses":[187,188,199]}],"verseLabel":"آل عمران: 187، 188، 199","question":"كيف تبني الآيات مقابلة متوازنة بين فعل أهل الكتاب وجزائهم؟","answer":"رتبت الصورة على طرفين متقابلين: نبذ الميثاق وشراء الثمن القليل ثم العذاب، في مقابل الإيمان والخشوع ورفض البيع ثم الأجر. هذا التوازي يجعل العاقبة امتدادًا للعمل، ويكشف أن الربح الظاهر في الدنيا هو عين الخسارة إذا كان ثمنه الحق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، التقابل بين العمل والعاقبة.؛ العنوان الجزئي: التناظر بين طريق البيع وطريق الوفاء.","url":""}]},{"id":"s3-868","number":868,"surah":3,"verses":[187,188,199],"references":[{"surah":3,"verses":[187,188,199]}],"verseLabel":"آل عمران: 187، 188، 199","question":"ما سر عودة الحديث عن أهل الكتاب في الآية 199 بعد ذم من نبذوا الميثاق في الآيتين 187–188؟","answer":"عادت الآية لتمنع تعميم الذم؛ فبعد عرض من كتموا الكتاب وباعوا آيات الله، ذكرت من آمنوا وخشعوا وحفظوا الوحي. وبذلك يقيم السياق ميزانًا عادلًا داخل الجماعة الواحدة، ويجعل الحكم تابعًا للموقف من الحق لا للاسم الموروث.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، مناسبة الآية 199 لما قبلها.؛ العنوان الجزئي: مقابلة الناكثين بالمؤمنين من أهل الكتاب.","url":""}]},{"id":"s3-869","number":869,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"كيف يجمع لفظ ﴿خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ﴾ بين التأمل في فعل الخلق والتأمل في المخلوقات نفسها؟","answer":"«الخلق» مصدر يحتمل معنى الإنشاء والإيجاد، ويستعمل كذلك بمعنى المخلوق. ولذلك تتسع الآية للتفكر في كيفية إبداع السماوات والأرض، وللتفكر في ذواتهما وصفاتهما وما أودع فيهما من عجائب؛ فتجتمع آيات الفعل وآيات المفعول في لفظ واحد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اتساع معنى «خلق السماوات والأرض».؛ العنوان الجزئي: «الخلق» بين المصدر والمخلوق.","url":""}]},{"id":"s3-870","number":870,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما الذي يضيفه وصف المتفكرين بأنهم ﴿أُولِي الْأَلْبَابِ﴾، لا مجرد «أصحاب عقول»؟","answer":"اللُّب هو خالص العقل وجوهره بعد تنقيته من الهوى وشوائب الوهم؛ فكل لُبّ عقل، وليس كل عقل لُبًّا. وجاء الوصف ليبين أن الانتفاع بآيات الكون يحتاج إلى عقل راجح زكي، لا إلى مجرد قدرة ذهنية قد تقودها الأهواء.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «أولي الألباب».؛ العنوان الجزئي: اللُّب بوصفه العقل الخالص من الشوائب.","url":""}]},{"id":"s3-871","number":871,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سر إسناد إدراك آيات الخلق إلى ﴿أُولِي الْأَلْبَابِ﴾ خاصة؟","answer":"مشاهد الكون متاحة للجميع، لكن تحويلها إلى دلائل على القدرة والحكمة يحتاج إلى عقل متحرر من الهوى والوهم. لذلك لم تجعل الآية مجرد الرؤية كافية، بل علقت الانتفاع بأصحاب العقول الزكية التي تنفذ من ظاهر المشهد إلى دلالته.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أولو الألباب والانتفاع بآيات الكون.؛ العنوان الجزئي: العقل الزكي شرط الانتفاع بالآيات.","url":""}]},{"id":"s3-872","number":872,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سر اختصار مشاهد الآيات في آل عمران، مقابل تفصيلها في آية البقرة 164؟","answer":"آية البقرة جاءت بعد تقرير وحدانية الله، فناسبها استقصاء الأدلة: الفلك والماء وإحياء الأرض والدواب والرياح والسحاب. أما آل عمران فجاءت في مقام إيقاظ أولي الألباب، فاكتفت بأصلين جامعَين: خلق السماوات والأرض واختلاف الليل والنهار، لأن المقصود تنبيه العقل إلى دلالة الخلق لا تعداد مظاهره.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف التفصيل بين آيتي البقرة وآل عمران.؛ العنوان الجزئي: التفصيل والإجمال بحسب سياق التوحيد والتفكر.","url":""}]},{"id":"s3-873","number":873,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سر ختم آية آل عمران بـ﴿لَآيَاتٍ لِّأُولِي الْأَلْبَابِ﴾، وختم آية البقرة بـ﴿لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ﴾؟","answer":"آية البقرة تسوق أدلة مفصلة تحتاج إلى تعقل ونظر في انتظامها، فناسبها وصف «يعقلون». أما آية آل عمران فتتجه إلى من تجاوز مجرد إدراك النظام إلى التفكر في غايته والاعتبار به، فناسبها وصف «أولي الألباب»؛ لأن اللب أعمق من مجرد استعمال العقل في الملاحظة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف «أولي الألباب» و«يعقلون».؛ العنوان الجزئي: تفاوت المخاطبين بين التعقل والتفكر.","url":""}]},{"id":"s3-874","number":874,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما المنهج الدعائي الذي يكشفه تقديم الذكر والتنزيه على قوله: ﴿فَقِنَا عَذَابَ النَّارِ﴾؟","answer":"الآية تعلم أن يحسن الداعي تقديم ذكر الله والثناء عليه قبل عرض حاجته، كما سبقت المحامد وعبادة الله طلبَ الهداية في الفاتحة. فالدعاء هنا ثمرة معرفة وتعظيم، لا طلبًا منفصلًا عن حضور القلب مع الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص32–35، الثناء على الله بين يدي الدعاء.؛ العنوان الجزئي: أدب تقديم الثناء قبل المسألة.","url":""}]},{"id":"s3-875","number":875,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما دلالة إطلاق الذكر في ﴿يَذْكُرُونَ اللَّهَ﴾ من غير تقييده باللسان أو القلب؟","answer":"الإطلاق يشمل ذكر اللسان وذكر القلب؛ فلا ينحصر وصف أولي الألباب في ألفاظ يرددونها، ولا في خواطر باطنة لا تظهر آثارها. إنما يجتمع حضور القلب مع نطق اللسان، فيكون الذكر شاملًا للباطن والظاهر.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص32–35، ذكر الله باللسان والقلب.؛ العنوان الجزئي: شمول الذكر للسان والقلب.","url":""}]},{"id":"s3-876","number":876,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما سر الجمع بين دوام الذكر والتفكر في الخلق في وصف أولي الألباب؟","answer":"الذكر يصل القلب بالخالق، والتفكر يقرأ آثار حكمته في الخلق؛ فإذا اجتمعا سلم النظر من الغفلة وسلم الذكر من الانفصال عن آيات الكون. ولذلك أثمر اجتماعهما تنزيه الله عن العبث، ثم التوجه إليه بالدعاء.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص32–35، الذكر والتفكر ثم التنزيه والدعاء.؛ العنوان الجزئي: تكامل معرفة الخالق والنظر في الخلق.","url":""}]},{"id":"s3-877","number":877,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما سر تعقيب ﴿مَا خَلَقْتَ هَذَا بَاطِلًا﴾ مباشرةً بقوله: ﴿سُبْحَانَكَ﴾؟","answer":"لما نفوا العبث عن الخلق أتبعوه بتنزيه الخالق عن كل ما لا يليق به؛ فـ«سبحانك» تقرر أن أفعاله كلها حق وحكمة. وبذلك لا تبقى نتيجة التفكر فكرة عقلية مجردة، بل تتحول إلى تعظيم وتنزيه لله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص32–35، التنزيه عن العبث والباطل.؛ العنوان الجزئي: انتقال التفكر إلى التنزيه.","url":""}]},{"id":"s3-878","number":878,"surah":3,"verses":[191,192],"references":[{"surah":3,"verses":[191,192]}],"verseLabel":"آل عمران: 191، 192","question":"ما سر الانتقال من طلب الوقاية: ﴿فَقِنَا عَذَابَ النَّارِ﴾ إلى تقرير عاقبة من يدخلها: ﴿فَقَدْ أَخْزَيْتَهُ﴾؟","answer":"بدأ الدعاء بطلب النجاة، ثم بيّنوا سبب شدة افتقارهم إليها: دخول النار خزي وفضيحة لا مجرد ألم عابر. فالجملة الثانية تعمق معنى الطلب الأول، وتكشف وعيهم بحقيقة المصير الذي يستعيذون منه.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص35–40، دخول النار خزي وإهانة.؛ العنوان الجزئي: تعليل سؤال الوقاية ببيان حقيقة الخزي.","url":""}]},{"id":"s3-879","number":879,"surah":3,"verses":[191,194],"references":[{"surah":3,"verses":[191,194]}],"verseLabel":"آل عمران: 191، 194","question":"ما أثر استقلال مطالب الدعاء المتتابعة المفتتحة بـ﴿رَبَّنَا﴾ من غير ربطها كلها بحروف العطف؟","answer":"استقلال الجمل يجعل كل مطلب قائمًا بنفسه عظيم الشأن: الوقاية، والمغفرة، والتكفير، وحسن الخاتمة، وإنجاز الوعد، والسلامة من الخزي. فلا تبدو المطالب توابع سريعة لمطلب واحد، بل مناجاة متجددة يتكرر فيها الافتقار.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص47–50، استقلال مطالب الدعاء وعلو شأنها.؛ العنوان الجزئي: تعدد المطالب واستقلال كل مناجاة.","url":""}]},{"id":"s3-880","number":880,"surah":3,"verses":[191,195],"references":[{"surah":3,"verses":[191,195]}],"verseLabel":"آل عمران: 191، 195","question":"ما الذي يكشفه جواب الدعاء عن الصلة بين الإيمان والعمل والثناء قبل المسألة؟","answer":"سبق الدعاء ذكرُ الله والتفكر والثناء، وصرح الداعون بإيمانهم، ثم جاء الجواب: ﴿لَا أُضِيعُ عَمَلَ عَامِلٍ﴾. فدل السياق على أن الاستجابة لم تُعرض بوصفها كلمات مجردة، بل ثمرة إيمان وعمل صالح وتعظيم لله قُدم بين يدي الدعاء.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص50–52، مدار الاستجابة على الإيمان والعمل والثناء.؛ العنوان الجزئي: الدعاء المؤيد بالإيمان والعمل.","url":""}]},{"id":"s3-881","number":881,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"كيف يكون نفي «الناصر» أقوى في الدلالة من نفي «النصير» مع أن «النصير» صيغة مبالغة؟","answer":"إذا نُفي أصل الناصر فقد انتفى النصير القوي من باب أولى؛ لأن نفي القليل يشمل الكثير، أما نفي الكثير فلا يلزم منه نفي القليل. لذلك يكون قولك «ما له من ناصر» أبلغ في استئصال كل قدر من النصرة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص35–40، قوة نفي الناصر والنصير.؛ العنوان الجزئي: نفي أصل النصرة ونفي المبالغة فيها.","url":""}]},{"id":"s3-882","number":882,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما الفرق البلاغي بين نفي ﴿أَنصَارٍ﴾ عن الظالمين، ونفي ﴿نَاصِرِينَ﴾ عن الكافرين في السورة نفسها؟","answer":"«الأنصار» تحتمل جمع ناصر وجمع نصير، أما «الناصرون» فهي جمع ناصر. وقد جاء نفي الناصرين في سياقات الكفر الشديد والضلال المستحكم، بينما جاء «أنصار» مع وصف الظلم الذي قد يكون كفرًا وقد يكون دونه؛ فاختير لكل مقام ما يلائمه.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص35–40، الفرق بين «أنصار» و«ناصرين».؛ العنوان الجزئي: تفاوت نفي النصرة بحسب شدة الوصف.","url":""}]},{"id":"s3-883","number":883,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما سر استعمال الجمع ﴿أَنصَارٍ﴾ في آل عمران، مقابل المفرد ﴿مِنْ نَصِيرٍ﴾ في سورة الحج؟","answer":"آية آل عمران تتحدث عن الظالمين على امتداد الأزمنة، فناسب كثرتهم وتعدد صور النصرة أن ينفى عنهم «أنصار». أما آية الحج فسياقها في جماعة مخصوصة في زمن الرسول، فناسبها المفرد «نصير». ويتبع اللفظ مقدار العموم والكثرة في السياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «أنصار» و«نصير».؛ العنوان الجزئي: المفرد والجمع في نفي النصرة.","url":""}]},{"id":"s3-884","number":884,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما سر التعبير عن المدخلين النار بقوله: ﴿لِلظَّالِمِينَ﴾؟","answer":"عُدل عن الضمير إلى وصف الظلم لإظهار علة دخول النار وذم أصحابها، ولتتسع الدلالة فتشمل كل ظالم، لا جماعة بعينها. فالاسم الظاهر هنا يحمل حكمًا أخلاقيًا وسببًا للعقوبة في الوقت نفسه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وضع «الظالمين» موضع الضمير.؛ العنوان الجزئي: إظهار الوصف بدل الإضمار للتعليل والذم.","url":""}]},{"id":"s3-885","number":885,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة الفاء في جوابهم: ﴿فَآمَنَّا﴾؟","answer":"الفاء تفيد التعقيب والسببية، فتصور أن الإيمان ترتب على سماع النداء من غير مهلة ولا تردد. وبذلك يمدح التعبير سرعة استجابتهم، لا مجرد وقوع الإيمان منهم في وقت لاحق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، الفاء في «فآمنا».؛ العنوان الجزئي: تعجيل القبول وتسبب الإيمان عن السماع.","url":""}]},{"id":"s3-886","number":886,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة حذف المفعول الصريح في قوله: ﴿يُنَادِي لِلْإِيمَانِ﴾؟","answer":"حذف من وُجه إليه النداء يفيد العموم، فكأن المنادي يدعو كل من يصل إليه صوته، لا فئة مخصوصة. وفي ذلك توسيع لرسالة الإيمان وإظهار أنها خطاب مفتوح للناس جميعًا.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، حذف مفعول «ينادي» للعموم.؛ العنوان الجزئي: عموم المدعوين إلى الإيمان.","url":""}]},{"id":"s3-887","number":887,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة قولهم: ﴿سَمِعْنَا مُنَادِيًا﴾ مع أن كثيرًا منهم لم يروا الرسول ﷺ؟","answer":"يبرز التعبير أنهم صدقوا الدعوة عن طريق السماع من غير اشتراط رؤية الرسول، وفي ذلك إظهار لصدق إيمانهم وسرعة قبولهم. كما يتسع المنادي للقرآن الباقي الذي يسمعه الناس على مر العصور.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، الإيمان بالسماع من غير رؤية.؛ العنوان الجزئي: فضل الاستجابة للرسالة المسموعة.","url":""}]},{"id":"s3-888","number":888,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة قولهم: ﴿وَتَوَفَّنَا مَعَ الْأَبْرَارِ﴾ بدل الاكتفاء بطلب الوفاة على الإيمان؟","answer":"لم يطلبوا سلامة الخاتمة منفردين فحسب، بل سألوا أن يكونوا معدودين في جملة الأبرار ومخصوصين بصحبتهم. فـ«مع» تضيف معنى الرفقة والمنزلة المشتركة، وتكشف شوقهم إلى جماعة الصالحين في المصير.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، صحبة الأبرار وحسن الخاتمة.؛ العنوان الجزئي: طلب الرفقة الصالحة في الآخرة.","url":""}]},{"id":"s3-889","number":889,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما سر اختيار ﴿مُنَادِيًا﴾ بدل «داعيًا» في وصف من دعاهم إلى الإيمان؟","answer":"النداء يشعر برفع الصوت والمبالغة في الإسماع، فيصور عناية المنادي بتبليغ الدعوة إلى القريب والبعيد. أما «الداعي» فلا يحمل وحده هذه الصورة القوية في الإبلاغ، فكان «المنادي» أليق بعظمة الرسالة وعمومها.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، إيثار المنادي على الداعي.؛ العنوان الجزئي: قوة الإسماع وعموم التبليغ.","url":""}]},{"id":"s3-890","number":890,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما سر التوكيد في ﴿إِنَّنَا سَمِعْنَا﴾ بآل عمران، مقابل ﴿إِنَّا سَمِعْنَا﴾ على لسان الجن؟","answer":"أُظهرت النون في ﴿إننا﴾ لزيادة التوكيد؛ لأنهم سمعوا مناديًا يرفع النداء، ولأن كلامهم جاء في مقام التضرع والتوسل وطلب المغفرة وحسن الخاتمة. أما الجن فذكروا سماع الكتاب، ولم يقع كلامهم في سلسلة المطالب الدعائية نفسها، فناسب التخفيف.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، «إننا سمعنا» و«إنا سمعنا».؛ العنوان الجزئي: زيادة التوكيد بحسب المسموع ومقام التضرع.","url":""}]},{"id":"s3-891","number":891,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما سر تقديم المغفرة والتكفير على قولهم: ﴿وَتَوَفَّنَا مَعَ الْأَبْرَارِ﴾؟","answer":"طلبوا أولًا أن يلقوا الله وقد غُفرت ذنوبهم وكُفرت سيئاتهم، ثم سألوا حسن الخاتمة؛ فالتطهير يسبق الوفاة في ترتيب الرجاء. وفي ذلك خوف من أن يدركهم الموت قبل إصلاح ما بينهم وبين الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، تقديم التطهير على طلب حسن الخاتمة.؛ العنوان الجزئي: الموت بعد المغفرة والتكفير.","url":""}]},{"id":"s3-892","number":892,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما سر وصل قولهم ﴿فَآمَنَّا﴾ بطلب المغفرة والتكفير؟","answer":"الإيمان هو الباب الذي تُرجى بعده المغفرة والتكفير؛ فالإسلام يجب ما قبله، ومن لم يؤمن لا يكون في مقام هذا الرجاء. لذلك قدموا إعلان الاستجابة، ثم بنوا عليه سؤال محو آثار الذنب والسيئة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، الإيمان مدعاة إلى المغفرة والتكفير.؛ العنوان الجزئي: بناء طلب المغفرة على تحقق الإيمان.","url":""}]},{"id":"s3-893","number":893,"surah":3,"verses":[193,195],"references":[{"surah":3,"verses":[193,195]}],"verseLabel":"آل عمران: 193، 195","question":"كيف استجمع سياق دعاء أولي الألباب أصول الإيمان قبل وعدهم بعدم إضاعة العمل؟","answer":"صرحوا بالإيمان بالله، وصدقوا الرسل وما جاء على ألسنتهم، ويلزم من ذلك الإيمان بالكتب والملائكة الذين يبلغون الوحي. وذكروا يوم القيامة والميعاد، وما في الكتب من القدر؛ فاجتمعت أصول الإيمان في السياق قبل ذكر العمل والجزاء.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص50–52، استكمال عناصر الإيمان في سياق الدعاء.؛ العنوان الجزئي: اكتمال الإيمان قبل الوعد بالجزاء.","url":""}]},{"id":"s3-894","number":894,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"كيف يجمع الدعاء بين طلب النصر في الدنيا وطلب السلامة من الخزي في الآخرة؟","answer":"إذا شمل الوعد النصر والثواب، صار الدعاء جامعًا لكرامة الدارين: ألا يُخزوا في الدنيا بغلبة العدو، وألا يُخزوا في الآخرة بسوء الحساب. فالثبات عندهم لا ينفصل عن حسن المصير، ولا يقتصر على نتيجة المعركة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص47–50، الجمع بين وعد النصر ووعد الثواب.؛ العنوان الجزئي: نفي خزي الدنيا والآخرة.","url":""}]},{"id":"s3-895","number":895,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما دلالة قولهم: ﴿وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ﴾ بعد سؤالهم إنجاز الوعد؟","answer":"طلبوا ألا يفضحهم الله بما صدر منهم من تقصير، بل يستر عليهم يوم ظهور الأعمال. فإيمانهم بالوعد لم يحملهم على الاغترار، وإنما جمعوا الرجاء في فضل الله مع الخوف من ذنوبهم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص47–50، معنى الخزي في دعاء يوم القيامة.؛ العنوان الجزئي: الرجاء في الوعد مع الخوف من الفضيحة.","url":""}]},{"id":"s3-896","number":896,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما الصورة المقابلة بين ﴿أُخْرِجُوا مِن دِيَارِهِمْ﴾ و﴿لَأُدْخِلَنَّهُمْ جَنَّاتٍ﴾؟","answer":"قابل الله إخراجهم القسري من مساكن الدنيا بإدخاله إياهم جنات الآخرة؛ فما فقدوه في سبيله عوضهم عنه دارًا خيرًا. وتمنح المقابلة المظلوم يقينًا بأن الإخراج ليس نهاية القصة، بل وراءه إدخال كريم من الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، الإخراج من الديار والإدخال إلى الجنات.؛ العنوان الجزئي: الجزاء من جنس الابتلاء على وجه أكرم.","url":""}]},{"id":"s3-897","number":897,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة العبارة الجامعة ﴿بَعْضُكُم مِّن بَعْضٍ﴾ بعد ذكر الذكر والأنثى؟","answer":"تؤكد العبارة وحدة الأصل الإنساني، وأن الذكر من الأنثى والأنثى من الذكر، فلا فضل في الجزاء بسبب الجنس أو النسب. وجاءت لتقرر شركة النساء مع الرجال في الوعد، وتردّ ما كان في أعراف الناس من احتقار المرأة أو جعل العمل الفاضل مقصورًا على الرجال.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «بعضكم من بعض».؛ العنوان الجزئي: وحدة الأصل وشمول الثواب للرجال والنساء.","url":""}]},{"id":"s3-898","number":898,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة بناء ﴿أُخْرِجُوا﴾ للمجهول، وإسناد ﴿لَأُدْخِلَنَّهُمْ﴾ إلى الله بصيغة المتكلم؟","answer":"طوى التعبير ذكر من أخرجهم لحقارته وعدم العناية به، ثم أبرز فاعل الإدخال وأكده؛ فالمخرجون من البشر عارضون، أما الذي يتولى الجزاء والإدخال فهو رب العزة. وبذلك تنتقل العناية من يد الظلم إلى يد الكرامة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، المبني للمجهول وإسناد الإدخال إلى الله.؛ العنوان الجزئي: إخفاء فاعل الظلم وإظهار فاعل الجزاء.","url":""}]},{"id":"s3-899","number":899,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة تقديم ﴿لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ﴾ على ﴿وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ﴾؟","answer":"دخول الجنة يكون بعد إزالة ما يحول دونه من السيئات، فقدم التكفير لأنه أسبق في ترتيب الجزاء. وجاء النظم موافقًا لمسار النجاة: تطهير من التبعة أولًا، ثم إدخال إلى دار النعيم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، تقديم التكفير على دخول الجنة.؛ العنوان الجزئي: ترتيب التطهير والنعيم.","url":""}]},{"id":"s3-900","number":900,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر التوكيد بالنون في ﴿لَأُكَفِّرَنَّ﴾ و﴿لَأُدْخِلَنَّهُمْ﴾، مقابل السين في ﴿سَنُدْخِلُهُمْ جَنَّاتٍ﴾؟","answer":"كلا الأسلوبين يدل على الاستقبال، لكن نون التوكيد الثقيلة تزيد الوعد قوة. وقد جاءت في آل عمران بعد أعمال شاقة من هجرة وإخراج وإيذاء وقتال وقتل، بينما جاءت السين في سياقات عامة للإيمان والعمل الصالح من غير تفصيل تلك المشاق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، نون التوكيد والسين في وعد الجنة.؛ العنوان الجزئي: قوة الوعد بحسب مشقة العمل.","url":""}]},{"id":"s3-901","number":901,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر ترتيب الأعمال في قوله تعالى: ﴿هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا ... وَقَاتَلُوا وَقُتِلُوا﴾؟","answer":"تدرجت الأفعال في الشدة: فالهجرة قد تكون اختيارًا، والإخراج أشد لأنه قهري، والإيذاء أشد من مجرد الخروج، ثم القتال، ثم القتل وهو غاية التضحية. فجاء الترتيب مصورًا لتصاعد البذل حتى يبلغ أعلى درجات الفداء.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ترتيب أعمال المهاجرين والمجاهدين.؛ العنوان الجزئي: التدرج من الهجرة إلى القتل.","url":""}]},{"id":"s3-902","number":902,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر حذف قيد ﴿وَهُوَ مُؤْمِنٌ﴾ في آل عمران، مع التصريح به في قوله بسورة غافر: ﴿وَمَنْ عَمِلَ صَالِحًا... وَهُوَ مُؤْمِنٌ﴾؟","answer":"سياق آل عمران سبق أن أثبت إيمانهم بقولهم: ﴿أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا﴾، ووصفهم بصفات المؤمنين؛ فلم يحتج إلى إعادة القيد. أما آية غافر فذكرت العمل في قاعدة عامة، فاحتيج إلى التصريح بشرط الإيمان.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص50–52، حذف «وهو مؤمن» لسبق إثبات الإيمان.؛ العنوان الجزئي: الاكتفاء بالسياق عن إعادة شرط الإيمان.","url":""}]},{"id":"s3-903","number":903,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر مقابلة ﴿دِيَارِهِمْ﴾ التي فقدوها بـ﴿جَنَّاتٍ﴾ يدخلونها؟","answer":"الديار مساكن محدودة في الدنيا أُبعدوا عنها، أما الجنات فدار واسعة باقية أعدها الله لهم. فانتقل التعبير من مفردات الفقد والغربة إلى مفردات الأمن والنعيم، ليظهر عظم العوض الإلهي.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، مقابلة الديار بالجنات.؛ العنوان الجزئي: من فقد الوطن إلى سعة دار الجزاء.","url":""}]},{"id":"s3-904","number":904,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما وجه المناسبة بين ثقل الأعمال المذكورة وثقل التوكيد في وعد أصحابها؟","answer":"لما ثقلت تضحياتهم بالهجرة والإخراج والأذى والقتال والقتل، قوبلت بوعد مؤكد بنون التوكيد الثقيلة في التكفير والإدخال. فازدادت قوة الوعد بمقدار ما عرض السياق من شدة الطريق وثقل التكليف.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، التوكيد مع مشاق الأعمال.؛ العنوان الجزئي: مقابلة مشقة العمل بتوكيد الجزاء.","url":""}]},{"id":"s3-905","number":905,"surah":3,"verses":[195,198],"references":[{"surah":3,"verses":[195,198]}],"verseLabel":"آل عمران: 195، 198","question":"ما الفرق البلاغي بين ﴿لَأُدْخِلَنَّهُمْ جَنَّاتٍ﴾ و﴿لَهُمْ جَنَّاتٌ﴾؟","answer":"الإدخال يثبت بلوغ الجنة، لكنه لا يدل في أصل العبارة على الملك، أما ﴿لَهُمْ جَنَّاتٌ﴾ فتفيد الاختصاص والتمليك. ولما كان وصف المتقين في الآية 198 أعم وأشمل، جاء لهم التعبير الأعلى الدال على أن الجنات صارت لهم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، الفرق بين الإدخال والتمليك في الآيتين 195 و198.؛ العنوان الجزئي: بلوغ الجنة وامتلاكها.","url":""}]},{"id":"s3-906","number":906,"surah":3,"verses":[195,198],"references":[{"surah":3,"verses":[195,198]}],"verseLabel":"آل عمران: 195، 198","question":"ما دلالة كون ﴿الَّذِينَ اتَّقَوْا رَبَّهُمْ﴾ أعم من الذين هاجروا وأُخرجوا وقاتلوا؟","answer":"المهاجرون والمخرجون والمجاهدون طائفة من المتقين، أما التقوى فتشمل فعل المأمورات واجتناب المنهيات وسائر أبواب البر. لذلك جاء وصف المتقين في الآية 198 جامعًا، ودخل فيه أصحاب الأعمال المذكورة في الآية 195 من غير أن يقتصر عليهم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، عموم المتقين وشمولهم أصحاب الهجرة والجهاد.؛ العنوان الجزئي: الخاص داخل في الوصف العام.","url":""}]},{"id":"s3-907","number":907,"surah":3,"verses":[195,198],"references":[{"surah":3,"verses":[195,198]}],"verseLabel":"آل عمران: 195، 198","question":"ما سر التعبير بـ﴿ثَوَابًا مِّنْ عِندِ اللَّهِ﴾ في الآية 195، وبـ﴿نُزُلًا مِّنْ عِندِ اللَّهِ﴾ في الآية 198؟","answer":"«الثواب» جزاء على عمل متميز، فجاء مع الذين هاجروا وأُخرجوا وأوذوا وقاتلوا. أما «النُّزُل» فهو ما يُهيأ للنازل من ضيافة وإقامة، فجاء مع المتقين في مقام أوسع، يصف الجنة ضيافةً مستقرة من عند الله، لا مجرد جزاء على عمل معين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «ثوابًا» و«نزلًا».؛ العنوان الجزئي: الثواب للجزاء، والنُّزُل للإقامة والضيافة.","url":""}]},{"id":"s3-908","number":908,"surah":3,"verses":[195,198],"references":[{"surah":3,"verses":[195,198]}],"verseLabel":"آل عمران: 195، 198","question":"ما سر ذكر ﴿خَالِدِينَ فِيهَا﴾ في الآية 198، وعدم ذكرها في الآية 195؟","answer":"المذكورون في الآية 195 فئة من المتقين، أما الآية 198 فتتناول المتقين على وجه أعم وأشمل، فناسب أن يذكر فيها الخلود. كما أن الآية 196 وصفت متاع الكافرين بالقلة والزوال، فجاء ذكر الخلود في الآية 198 مقابلاً لذلك المتاع المؤقت.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، سبب ذكر الخلود في الآية 198 دون الآية 195.؛ العنوان الجزئي: عموم المتقين ومقابلة الخلود بالمتاع القليل.","url":""}]},{"id":"s3-909","number":909,"surah":3,"verses":[195,198,200],"references":[{"surah":3,"verses":[195,198,200]}],"verseLabel":"آل عمران: 195، 198، 200","question":"كيف تلخص أوامر الخاتمة طريق المبتلين وجزاء المتقين في الآيات السابقة؟","answer":"يقابل الصبر الهجرة والإخراج، والمصابرة الأذى، والمرابطة القتال والقتل، ثم تقابل التقوى وصف المتقين أصحاب الجنات. وبذلك لا تأتي الخاتمة منفصلة، بل تختصر رحلة العمل والابتلاء والجزاء في أربعة أوامر جامعة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، مقابلة الخاتمة لما تقدمها.؛ العنوان الجزئي: الخاتمة خلاصة مسار السورة العملي.","url":""}]},{"id":"s3-910","number":910,"surah":3,"verses":[195,200],"references":[{"surah":3,"verses":[195,200]}],"verseLabel":"آل عمران: 195، 200","question":"ما وجه المقابلة بين ﴿اصْبِرُوا﴾ وذكر الذين ﴿هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ﴾؟","answer":"الهجرة والإخراج يقتضيان احتمال فراق الوطن وفقد الأمان، وهما من أشد مواطن الصبر. فجاء الأمر العام بالصبر كأنه يستخلص الخلق اللازم لمواجهة أول درجات الابتلاء المذكورة قبل الخاتمة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، اصبروا في مقابلة الهجرة والإخراج.؛ العنوان الجزئي: الصبر زاد الهجرة وفقد الديار.","url":""}]},{"id":"s3-911","number":911,"surah":3,"verses":[195,200],"references":[{"surah":3,"verses":[195,200]}],"verseLabel":"آل عمران: 195، 200","question":"ما وجه المقابلة بين ﴿رَابِطُوا﴾ وقوله: ﴿وَقَاتَلُوا وَقُتِلُوا﴾؟","answer":"القتال والقتل ذروة المواجهة، والمرابطة هي الاستعداد الدائم الذي يحفظ الثغور ويهيئ لها. فجاءت في الخاتمة بإزاء أشد مراحل البلاء، لتجعل الاستعداد المستمر خلقًا يحمي الجماعة قبل وقوع القتال وأثناءه.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، رابطوا في مقابلة القتال والقتل.؛ العنوان الجزئي: المرابطة سياج المواجهة الكبرى.","url":""}]},{"id":"s3-912","number":912,"surah":3,"verses":[195,200],"references":[{"surah":3,"verses":[195,200]}],"verseLabel":"آل عمران: 195، 200","question":"ما وجه المقابلة بين ﴿صَابِرُوا﴾ وقوله: ﴿وَأُوذُوا فِي سَبِيلِي﴾؟","answer":"الأذى في سبيل الله محاولة لكسر إرادة المؤمن وإرجاعه عن طريقه، والمصابرة هي أن يواجه تلك الإرادة بثبات أطول. فالأمر لا يكتفي بتحمل الألم، بل يطلب مغالبة من يصنعه بالصبر على الحق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، صابروا في مقابلة الأذى.؛ العنوان الجزئي: مقاومة الأذى بثبات أطول.","url":""}]},{"id":"s3-913","number":913,"surah":3,"verses":[196,197],"references":[{"surah":3,"verses":[196,197]}],"verseLabel":"آل عمران: 196، 197","question":"كيف يحول وصف ﴿مَتَاعٌ قَلِيلٌ﴾ صورة القوة والتمكن في البلاد إلى مشهد عابر؟","answer":"التقلب يوحي بالسعة والقدرة والاستقرار، لكن وصفه بالمتاع القليل ينزع عنه وهم الدوام؛ فهو انتفاع محدود زمانًا وقدرًا. ثم يأتي المأوى الأخير ليبين أن البلاد التي تقلبوا فيها لم تكن إلا محطات انتقال.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص56–57، التقلب متاع محدود والبلاد محطات انتقال.؛ العنوان الجزئي: تقليص المظهر الدنيوي أمام المصير الدائم.","url":""}]},{"id":"s3-914","number":914,"surah":3,"verses":[196,197],"references":[{"surah":3,"verses":[196,197]}],"verseLabel":"آل عمران: 196، 197","question":"ما وجه الصلة بين «التقلب» في البلاد وذكر ﴿مَأْوَاهُمْ﴾ بعده؟","answer":"المتقلب كثير الحركة لا بد له في النهاية من مكان يأوي إليه ويستقر فيه. فجاء «المأوى» بعد «التقلب» ليكشف نهاية حركتهم الواسعة: انتقالاتهم مؤقتة، أما مأواهم الأخير فجهنم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص56–57، من التقلب إلى المأوى.؛ العنوان الجزئي: نهاية الحركة في مستقر المصير.","url":""}]},{"id":"s3-915","number":915,"surah":3,"verses":[198,200],"references":[{"surah":3,"verses":[198,200]}],"verseLabel":"آل عمران: 198، 200","question":"ما وجه المقابلة بين ﴿وَاتَّقُوا اللَّهَ﴾ وذكر ﴿الَّذِينَ اتَّقَوْا رَبَّهُمْ﴾ قبلها؟","answer":"عرضت الآية 198 عاقبة المتقين، ثم جاءت الخاتمة بالأمر بالطريق الموصل إلى تلك العاقبة. فتحول وصف أهل الجنة إلى تكليف عملي للقارئ: إن أردتم منزلتهم فحققوا تقوى الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، الأمر بالتقوى ووصف المتقين.؛ العنوان الجزئي: تحويل وصف أهل الجزاء إلى منهج عمل.","url":""}]},{"id":"s3-916","number":916,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سر استعمال ﴿أُنزِلَ﴾ في وصف إيمان أهل الكتاب، وما الذي يضيفه البناء للمجهول هنا؟","answer":"المقام يعدد متعلق الإيمان لا كيفية التنزيل ولا زمنه، فبُني الفعل للمجهول لتتجه العناية إلى الوحي المنزل وإلى اجتماع الفريقين عليه. والفاعل معلوم من السياق، فحذفه لا يوقع لبسًا بل يركز الضوء على وحدة المصدر والمضمون.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أنزل ونزّل، وأُنزل إليك وأُنزل عليك.؛ العنوان الجزئي: توجيه العناية إلى الوحي المنزل.","url":""}]},{"id":"s3-917","number":917,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سر اقتران رفض ﴿ثَمَنًا قَلِيلًا﴾ بتوكيد سرعة الحساب في ختام الآية؟","answer":"من يبيع الآيات يطلب عاجل الدنيا، أما هؤلاء فتركوا ذلك العاجل وفاءً لله. فجاء توكيد سرعة الحساب وعدًا بألا يفوتهم الخير العاجل؛ يعجل الله لهم من فضله في الدنيا، مع ما ادخر لهم من أجر الآخرة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، تعجيل أجر من ترك الثمن القليل.؛ العنوان الجزئي: مقابلة العاجل المحرم بالعاجل الموهوب.","url":""}]},{"id":"s3-918","number":918,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سر توكيد سرعة الحساب في آل عمران، وعدم توكيدها في مشهد صاحب السراب في سورة النور؟","answer":"مشهد النور يصور فردًا واحدًا بلغ نهاية سعيه فوجد حسابه، فلا يثير السياق معنى كثرة المحاسَبين. أما آل عمران ففيها أجور جماعة ومراتب استحقاق، فكان المقام أدعى إلى التوكيد بأن كثرة الأعمال وأصحابها لا تبطئ الحساب.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، التوكيد مع الجماعة وتركه مع الفرد.؛ العنوان الجزئي: اختلاف التوكيد باختلاف سعة المشهد.","url":""}]},{"id":"s3-919","number":919,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما وجه التناسب بين توكيد سرعة الحساب في آل عمران، وتوكيدها بعد ﴿لِيَجْزِيَ اللَّهُ كُلَّ نَفْسٍ﴾ في إبراهيم؟","answer":"آية إبراهيم صرحت بشمول الجزاء لكل نفس، فناسب التوكيد دفع توهم أن العموم يطيل الحساب. وآية آل عمران وعدت جماعة المؤمنين بأجور متفاوتة يعلم الله مقاديرها؛ فالتوكيد في الموضعين يقرر أن كثرة المستحقين لا تؤخر تمام الجزاء.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، توكيد سرعة الحساب مع عموم الجزاء.؛ العنوان الجزئي: العموم سبب مناسب لتقوية خبر السرعة.","url":""}]},{"id":"s3-920","number":920,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"كيف تكون المرابطة نوعًا من الصبر، مع إفرادها بأمر مستقل؟","answer":"المرابط يصبر على طول الإقامة والترقب واحتمال الخطر، فهي صبر ممتد ذو وظيفة جماعية. وأُفردت بالذكر لأن دوامها وحراسة الثغور بها يجاوزان الصبر الفردي العام إلى التزام منظم يحمي الأمة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، المرابطة نوع من الصبر.؛ العنوان الجزئي: الصبر المنظم لحماية الجماعة.","url":""}]},{"id":"s3-921","number":921,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما أثر إحاطة الاستعداد العسكري بالتقوى في قوله: ﴿رَابِطُوا وَاتَّقُوا اللَّهَ﴾؟","answer":"المرابطة سبب قوة، لكن التقوى تضبط مقصدها ووسائلها؛ فلا تصبح القوة غاية مستقلة ولا ذريعة لتجاوز أمر الله. فالجمع بينهما يبني يقظة قادرة وضميرًا مراقبًا في آن واحد.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، التقوى عامة في جميع الأحوال.؛ العنوان الجزئي: ضبط القوة بالتقوى.","url":""}]},{"id":"s3-922","number":922,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما الذي تضيفه ﴿صَابِرُوا﴾ إلى الثبات في شدائد الحرب؟","answer":"المصابرة ليست تحمل الشدة منفردًا، بل الثبات أمام عدو يحاول أن يكون أطول نفسًا. فهي تطلب من المؤمن ألا يكون أقل صبرًا من خصمه، وأن يغلب مقاومته بثبات أشد.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، المصابرة في مواجهة الأعداء.؛ العنوان الجزئي: مغالبة الخصم في الصبر.","url":""}]},{"id":"s3-923","number":923,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما سر جعل الفلاح غايةً للصبر والمصابرة والمرابطة والتقوى مجتمعة؟","answer":"كل أمر يعالج جانبًا لا يغني عنه الآخر: ثبات النفس، ومغالبة الخصم، وحراسة الجماعة، ومراقبة الله. لذلك عُلّق الفلاح بالمجموع، حتى لا يظن أن النجاح يتحقق بقوة الميدان من غير صلاح القلب، أو بالتقوى المدعاة من غير أخذ بأسباب الثبات.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، الأوامر المجتمعة وطريق الفلاح.؛ العنوان الجزئي: تكامل أسباب الفلاح.","url":""}]},{"id":"s3-924","number":924,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما سر ختم سورة آل عمران بالأمر بـ﴿اصْبِرُوا وَصَابِرُوا﴾ بعد ما عرضته من محن وتمحيص؟","answer":"جاءت الخاتمة نتيجة عملية لما سبق من قضايا الإيمان والابتلاء والتمييز والنصر؛ فالإيمان لا يكتمل بالمعرفة والجدل، بل يحتاج إلى صبر ومصابرة وثبات. ولذلك ختمت السورة بهذا الأمر الجامع، ليظل المؤمن ثابتًا على الحق في نفسه ومع خصمه، مستحقًا طريق الفلاح.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ختام السورة بالأمر بالصبر والمصابرة.؛ العنوان الجزئي: مناسبة خاتمة السورة لمحورها في الثبات والتمحيص.","url":""}]},{"id":"s3-925","number":925,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما سعة المعنى التي يحملها الأمر ﴿اصْبِرُوا﴾ قبل ذكر المصابرة والمرابطة؟","answer":"الصبر هنا أصل جامع: صبر على المصيبة، وصبر على الطاعة، وصبر عن المعصية. فبدأت الخاتمة ببناء النفس في جميع أحوالها، قبل الانتقال إلى مواجهة الخصم وحراسة الثغور.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، أنواع الصبر في خاتمة السورة.؛ العنوان الجزئي: شمول الصبر للمصيبة والطاعة والمعصية.","url":""}]},{"id":"s3-926","number":926,"surah":3,"verses":[],"references":[{"surah":3,"verses":[]}],"verseLabel":"آل عمران: غير محدد","question":"ما سر انتقال خطاب التقوى من المؤمنين في ختام آل عمران إلى الناس جميعًا في افتتاح النساء؟","answer":"ختمت آل عمران ببناء جماعة الإيمان على الصبر والتقوى، ثم افتتحت النساء بالأصل الإنساني الجامع وخاطبت الناس كافة. فانتقل الخطاب من تربية الصف المؤمن إلى تذكير البشرية بوحدة المنشأ وربوبية الخالق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، تناسب خاتمة آل عمران وفاتحة النساء.؛ العنوان الجزئي: من خصوص المؤمنين إلى عموم الناس.","url":""}]},{"id":"s3-927","number":927,"surah":3,"verses":[],"references":[{"surah":3,"verses":[]}],"verseLabel":"آل عمران: غير محدد","question":"ما سر تعاقب اسمي ﴿رَبِّهِمْ﴾ و﴿اللَّهَ﴾ في ختام آل عمران، ثم ورودهما معًا في افتتاح النساء؟","answer":"قالت الخاتمة: ﴿اتَّقَوْا رَبَّهُمْ﴾ ثم ﴿اتَّقُوا اللَّهَ﴾، وافتتحت النساء بـ﴿اتَّقُوا رَبَّكُمُ﴾ ثم ﴿وَاتَّقُوا اللَّهَ﴾. هذا التناسب يصل السورتين: اسم الرب يستحضر الخلق والرعاية، واسم الله يستجمع معاني الألوهية والطاعة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، ذكر الرب ولفظ الجلالة بين السورتين.؛ العنوان الجزئي: التناسب الاسمي بين الخاتمة والافتتاح.","url":""}]},{"id":"s3-1021","number":1021,"surah":3,"verses":[3,199],"references":[{"surah":3,"verses":[3,199]}],"verseLabel":"آل عمران: 3، 199","question":"ما وجه الصلة بين افتتاح السورة بـ﴿نَزَّلَ عَلَيْكَ الْكِتَابَ... وَأَنزَلَ التَّوْرَاةَ وَالْإِنجِيلَ﴾، وختم حوار أهل الكتاب بالإيمان بـ﴿مَا أُنزِلَ إِلَيْكُمْ وَمَا أُنزِلَ إِلَيْهِمْ﴾؟","answer":"الافتتاح يقرر وحدة مصدر الكتب وتصديق القرآن لما قبله، والختام يعرض الثمرة البشرية الصحيحة لهذا التقرير: أهل كتاب آمنوا بالوحيين ولم يفرقوا بينهما. فصار آخر الحوار تطبيقًا لما أسسته بدايته من وحدة الوحي.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، صلة خاتمة البقرة وفاتحة آل عمران ومحور الكتب، والإيمان بما أُنزل إلى الفريقين.","url":""}]},{"id":"s3-928","number":928,"surah":3,"verses":[9,194],"references":[{"surah":3,"verses":[9,194]}],"verseLabel":"آل عمران: 9، 194","question":"ما وجه اختلاف خاتمة الدعاء في ﴿إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ﴾، عن خاتمة دعاء المؤمنين في ﴿إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ﴾؟","answer":"في الآية 9 جاء الكلام في سياق تقرير حقيقة عامة: الله لا يخلف ميعاده. أما في الآية 194 فجاءت العبارة ضمن دعاء مباشر يخاطبون الله فيه، فناسب الانتقال إلى ضمير الخطاب: «إنك». اختلاف الضمير هنا تابع لاختلاف المقام، لا لاختلاف المعتقد.","sources":[{"label":"فاضل السامرائي، قبسات من البيان القرآني، ص 47–50، في مقارنة الآيتين.","url":""}]},{"id":"s3-929","number":929,"surah":3,"verses":[10],"references":[{"surah":3,"verses":[10]}],"verseLabel":"آل عمران: 10","question":"ما دلالة العطف بالواو في ﴿وَأُولَئِكَ هُمْ وَقُودُ النَّارِ﴾ بعد نفي إغناء الأموال والأولاد؟","answer":"الواو تصل بين سقوط وسائل النفع في الدنيا وبين المصير الأخروي؛ فالأموال والأولاد لا يدفعون عنهم شيئًا، ثم ينتهون إلى أن يكونوا وقود النار. ولذلك يبرز السياق امتداد الخسران من الدنيا إلى الآخرة، لا مجرد نفي منفعة واحدة.","sources":[{"label":"فاضل السامرائي، قبسات من البيان القرآني، ص 139–144.","url":""}]},{"id":"s3-930","number":930,"surah":3,"verses":[10],"references":[{"surah":3,"verses":[10]}],"verseLabel":"آل عمران: 10","question":"ما أثر ضمير الفصل في ﴿أُولَئِكَ هُمْ وَقُودُ النَّارِ﴾؟","answer":"«هم» لا يكتفي بتوكيد الخبر، بل يقوّي اختصاص هؤلاء بهذا الوصف في مقام التهديد؛ فكأن الآية تجعل حقيقتهم التي انتهوا إليها هي كونهم وقود النار. وفي ذلك تصوير أشد من مجرد القول إنهم سيدخلون النار.","sources":[{"label":"فاضل السامرائي، ضمير الفصل في القرآن الكريم.","url":""}]},{"id":"s3-931","number":931,"surah":3,"verses":[11],"references":[{"surah":3,"verses":[11]}],"verseLabel":"آل عمران: 11","question":"لماذا ختمت آية آل عمران بـ﴿وَاللَّهُ شَدِيدُ الْعِقَابِ﴾، بينما ختمت آية الأنفال بـ﴿إِنَّ اللَّهَ قَوِيٌّ شَدِيدُ الْعِقَابِ﴾؟","answer":"سياق الأنفال أشد اتصالًا بالقوة والمواجهة والعقوبة الحاصلة في ميدان القتال، فناسبه وصف «قوي» مع التوكيد بـ«إن». أما سياق آل عمران فجاء بخاتمة شديدة الوعيد من غير الحاجة إلى هذا البناء الزائد، فناسبه الاقتصار على ﴿شَدِيدُ الْعِقَابِ﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، الجزء الثاني، ص 26.","url":""}]},{"id":"s3-1043","number":1043,"surah":3,"verses":[12,13],"references":[{"surah":2,"verses":[286]},{"surah":3,"verses":[12,13]}],"verseLabel":"آل عمران: 12–13","question":"كيف جاءت آيتا الغلبة في أول آل عمران جوابًا عمليًا لدعاء ختام البقرة: ﴿فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾؟","answer":"ختمت البقرة بطلب النصر، ثم افتتحت آل عمران بإنذار الكافرين: ﴿سَتُغْلَبُونَ﴾، وأتبعته بشاهد واقعي في الفئتين اللتين التقتا. فانتقل المعنى من الدعاء إلى الوعد ثم إلى الدليل المشهود، وكأن مطلع السورة التالية يجيب ختام السابقة قولًا وفعلًا.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، صلة خاتمة البقرة بمطلع آل عمران.","url":""}]},{"id":"s3-932","number":932,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"ما سر التعبير بـ﴿زُيِّنَ لِلنَّاسِ﴾، لا بلفظ يخص الرجال، مع ذكر النساء في أول الشهوات؟","answer":"«الناس» أعم، فيدخل فيه الرجال والنساء. وذكر البنين يلمّح إلى رغبة النساء في الذرية من غير تصريح بما قد يخدش الحياء، كما أن حب الذهب والفضة مشترك بين الجنسين؛ فاختير اللفظ العام ليشمل الجميع مع رعاية الأدب في التصوير.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، الجزء الثاني، ص 28.","url":""}]},{"id":"s3-933","number":933,"surah":3,"verses":[14],"references":[{"surah":3,"verses":[14]}],"verseLabel":"آل عمران: 14","question":"ما دلالة تقديم الأولاد على الأموال في سياق الشهوات، مع تقديم الأموال على الأولاد في سياق الإلهاء عن ذكر الله؟","answer":"في مقام الحب والزينة قُدّم الأولاد، لأنهم أشد تعلقًا بالقلوب في هذا المقام. أما في مقام الإلهاء، فقدّمت الأموال لأن الانشغال بها أكثر إلهاءً عن الذكر في ذلك السياق؛ فالتقديم يتبع الغرض الذي تتحدث عنه الآية، لا ترتيبًا ثابتًا.","sources":[{"label":"فاضل السامرائي، وقفة آية 14 من آل عمران.","url":""}]},{"id":"s3-1012","number":1012,"surah":3,"verses":[14,152],"references":[{"surah":3,"verses":[14,152]}],"verseLabel":"آل عمران: 14، 152","question":"ما وجه الصلة بين افتتاح السورة بذكر الشهوات في ﴿زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَوَاتِ﴾، وكشف الانقسام في أُحد: ﴿مِنكُم مَّن يُرِيدُ الدُّنْيَا وَمِنكُم مَّن يُرِيدُ الْآخِرَةَ﴾؟","answer":"عرضت الآية 14 أصل الفتنة في التعلق بمتاع الدنيا، ثم أظهر مشهد أُحد أثر هذا التعلق حين أثّر طلب الغنيمة في موقف بعض الرماة. فصار الحدث العملي تفسيرًا لما حذرت منه السورة في بدايتها، وربط بين فساد الرغبة وخلل الثبات.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الشهوات وعلاقتها بمعصية أُحد.","url":""}]},{"id":"s3-1023","number":1023,"surah":3,"verses":[22,56,91,192],"references":[{"surah":3,"verses":[22,56,91,192]}],"verseLabel":"آل عمران: 22، 56، 91، 192","question":"ما سر تكرر ﴿وَمَا لَهُم مِّن نَّاصِرِينَ﴾ مع صور الكفر الشديد، مقابل ﴿وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ﴾؟","answer":"المواضع التي نُفي فيها الناصرون وصفت كفرًا صريحًا، وقتلًا للأنبياء، وموتًا على الكفر، وضلالًا لا هداية بعده. أما «الظالمون» فوصف أوسع قد يدخل فيه الكافر وغيره؛ فناسب شدة المقامات الأولى التعبير الأقوى في استئصال النصرة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص35–40، سياقات «ناصرين» وسياقات «أنصار».","url":""}]},{"id":"s3-934","number":934,"surah":3,"verses":[26],"references":[{"surah":3,"verses":[26]}],"verseLabel":"آل عمران: 26","question":"ما دلالة الجمع بين ﴿مَالِكَ الْمُلْكِ﴾، و﴿تُؤْتِي الْمُلْكَ﴾، و﴿تَنْزِعُ الْمُلْكَ﴾ في آية واحدة؟","answer":"«مالك» يدل على التملك، و«الملك» يدل على السلطان والتصرف والحكم؛ فالله مالك السلطان كله، لا يقتصر ملكه على وجود الأشياء في حوزته، بل له التصرف المطلق فيها. لذلك جاء بعد ذلك إيتاء الملك ونزعه، ليظهر أن السلطان الذي يتداوله الناس إنما هو داخل في ملك الله وتدبيره.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «المُلك» و«المِلك».","url":""}]},{"id":"s3-935","number":935,"surah":3,"verses":[27],"references":[{"surah":3,"verses":[27]}],"verseLabel":"آل عمران: 27","question":"ما سر التعبير بالفعل ﴿تُخْرِجُ الْحَيَّ﴾ في آل عمران، مقابل ﴿وَمُخْرِجُ الْمَيِّتِ﴾ في الأنعام؟","answer":"الفعل يدل على الحدوث والتجدد، وهو أنسب بالحي الذي من أبرز صفاته الحركة والتجدد. أما الاسم فيوحي بالثبوت والسكون، فجاء مع الميت؛ كما أن سياق آل عمران كله قائم على التحولات المتتابعة، في حين يراعي سياق الأنعام مناسبة الوصف الاسمي للحال المذكورة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الصيغة الفعلية والاسمية في «يخرج» و«مخرج».","url":""}]},{"id":"s3-936","number":936,"surah":3,"verses":[27,37],"references":[{"surah":3,"verses":[27,37]}],"verseLabel":"آل عمران: 27، 37","question":"ما وجه الصلة بين ختام آية الرزق لمريم ﴿يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ﴾ وختام آية التحولات الكونية ﴿وَتَرْزُقُ مَن تَشَاءُ بِغَيْرِ حِسَابٍ﴾؟","answer":"آية 27 تقرر القاعدة العامة: الله يرزق من يشاء بلا عجز ولا نفاد في خزائنه، ولا يُحاسبه أحد على عطائه. ثم تأتي آية 37 بتطبيق تلك القاعدة في رزق مريم الذي يأتيها من غير الأسباب المعتادة؛ فالمشهد الخاص يؤكد القاعدة العامة ويجسّدها.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الرابط بين ختام آيتي 27 و37.","url":""}]},{"id":"s3-937","number":937,"surah":3,"verses":[29],"references":[{"surah":3,"verses":[29]}],"verseLabel":"آل عمران: 29","question":"ما دلالة تقديم ﴿تُخْفُوا﴾ على ﴿تُبْدُوهُ﴾ في آل عمران، مع تقديم ﴿تُبْدُوا﴾ على ﴿تُخْفُوهُ﴾ في البقرة؟","answer":"آية البقرة في سياق المحاسبة، فناسب أن يتقدم إبداء العمل؛ لأن إظهار الذنب والمجاهرة به أشد خطرًا في ذلك المقام. أما آية آل عمران ففي سياق العلم الإلهي الشامل، فقدم الإخفاء لأن الله يعلم السر وما هو أخفى منه، فلا يخفى عليه ظاهر ولا باطن.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم وتأخير «تخفوا» في البقرة وآل عمران.","url":""}]},{"id":"s3-938","number":938,"surah":3,"verses":[30],"references":[{"surah":3,"verses":[30]}],"verseLabel":"آل عمران: 30","question":"ما سر إفراد الرأفة عن الرحمة في ختام الآية: ﴿وَاللَّهُ رَؤُوفٌ بِالْعِبَادِ﴾؟","answer":"الرأفة أخص من الرحمة، وهي متعلقة بدفع المكروه وإزالة الضرر. وجاءت مفردة في هذا الموضع لأن السياق سياق تحذير وتهديد: ﴿وَيُحَذِّرُكُمُ اللَّهُ نَفْسَهُ﴾، فلا يناسبه الجمع بين الرأفة والرحمة كما يناسب مقامات أخرى؛ فاختيرت الرأفة مع بقاء معنى الشمول في «العباد».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الأول، ص 251، إفراد الرأفة عن الرحمة.","url":""}]},{"id":"s3-939","number":939,"surah":3,"verses":[32],"references":[{"surah":3,"verses":[32]}],"verseLabel":"آل عمران: 32","question":"ما وجه اختلاف صيغ الطاعة في ﴿أَطِيعُوا اللَّهَ وَرَسُولَهُ﴾، و﴿أَطِيعُوا اللَّهَ وَالرَّسُولَ﴾، و﴿أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ﴾؟","answer":"إضافة الرسول إلى الضمير في «ورسوله» تلائم مقام تبليغ القرآن، فالرسول يبلّغ عن الله. أما تعريفه بـ«الرسول» في آل عمران فيشير إلى طاعته في البيان والتفسير والتفصيل. وأما تكرار فعل الطاعة في «وأطيعوا الرسول» فيبرز استقلال طاعة الرسول في سنته وتشريعه، بحسب سياق الآية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، صيغ الأمر بطاعة الله والرسول.","url":""}]},{"id":"s3-1039","number":1039,"surah":3,"verses":[35],"references":[{"surah":3,"verses":[35]}],"verseLabel":"آل عمران: 35","question":"ما دلالة قول امرأة عمران: ﴿فَتَقَبَّلْ مِنِّي﴾، بينما جاء في موضع آخر: ﴿فَتَقَبَّلَ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا﴾؟","answer":"﴿مِنِّي﴾ توجه العناية إلى صاحبة النذر وصدق توجهها، فهي تسأل قبول ما صدر منها تقربًا. أما ﴿عنهم﴾ فالسياق فيه قبول الأعمال والتجاوز عن أصحابها، فتتجه العناية إلى العمل المقبول وما يرفع عن العامل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «تقبل مني» و«تقبل عنهم».","url":""}]},{"id":"s3-940","number":940,"surah":3,"verses":[37],"references":[{"surah":3,"verses":[37]}],"verseLabel":"آل عمران: 37","question":"ما دلالة تقديم شبه الجملة في ﴿كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا الْمِحْرَابَ﴾؟","answer":"التقديم ليس للتركيز على زكريا أو على المحراب، بل لأن الكلام في الآية وما قبلها عن مريم؛ فالمهم هو ما كان يُوجد عندها من الرزق كلما دخل عليها زكريا. لذلك تقدمت «عليها» محافظةً على محور القصة، ثم جاء ذكر الداخل والمكان تبعًا للسياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم «عليها زكريا» في آية مريم.","url":""}]},{"id":"s3-941","number":941,"surah":3,"verses":[37],"references":[{"surah":3,"verses":[37]}],"verseLabel":"آل عمران: 37","question":"ما اللمسة البيانية في قوله تعالى: ﴿وَأَنبَتَهَا نَبَاتًا حَسَنًا﴾، بدل «إنباتًا حسنًا»؟","answer":"«إنباتًا» كان سيجعل التركيز على فعل الله وحده، أما «نباتًا» فيجمع بين إنبات الله ونبات مريم وقبولها لهذا الإنبات؛ فيثبت لها فضلًا في معدنها واستجابتها للطاعة. فاختيار المصدر من مادة أخرى جمع معنيين في تركيب موجز: فعل الإنبات وحسن النبات.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، «أنبتها نباتًا» لا «إنباتًا».","url":""}]},{"id":"s3-942","number":942,"surah":3,"verses":[38],"references":[{"surah":3,"verses":[38]}],"verseLabel":"آل عمران: 38","question":"ما دلالة طلب زكريا ﴿ذُرِّيَّةً طَيِّبَةً﴾ في آل عمران، مع طلبه وليًّا في مريم، وعدم إفراده الذرية بذكر أو أنثى؟","answer":"سياق آل عمران بدأ بمشهد مريم ورزقها العجيب، فكان الطلب مناسبًا للمقام العام: ذرية طيبة من غير تحديد للجنس. أما سورة مريم فبسطت حال زكريا وبيّنت خوفه من ضياع أمره، فناسبها طلب الولي الوارث. وفي الأنبياء جاء الدعاء موجزًا: ألا يترك فردًا، فجاء كل تعبير على قدر سياقه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 205–207، مقارنة قصة زكريا في آل عمران ومريم والأنبياء.","url":""}]},{"id":"s3-943","number":943,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما دلالة ذكر زكريا في آل عمران ﴿وَهُوَ قَائِمٌ يُصَلِّي فِي الْمِحْرَابِ﴾، مقابل خروجه على قومه من المحراب في سورة مريم؟","answer":"ذكر القيام والصلاة في آل عمران يهيئ للمشهد الذي يناسب عِظم البشارة بيحيى، ويصوّر لحظة استجابة الدعاء في مقام عبادة. أما مريم فالسياق ينتقل إلى أثر الآية في قومه، لذلك ذُكر خروجه من المحراب وإيحاؤه إليهم بالتسبيح؛ فكل موضع أبرز المرحلة المناسبة من القصة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المقارنة البيانية بين قصة زكريا في آل عمران ومريم.","url":""}]},{"id":"s3-944","number":944,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما دلالة تفصيل بشارة يحيى في آل عمران بصفات ﴿مُصَدِّقًا بِكَلِمَةٍ مِنَ اللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِنَ الصَّالِحِينَ﴾، مقارنةً ببشارة الغلام في سورة مريم؟","answer":"بشارة آل عمران أعظم تفصيلًا؛ لأنها تذكر مكانة يحيى ووظيفته وصفاته، بينما اكتفت مريم بذكر اسمه وكونه غلامًا لم يجعل الله له من قبل سميًا. فزيادة الصفات في آل عمران تناسب عظم البشارة، ولذلك ترتب عليها ذكر الشكر والذكر الكثير في الآية التالية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، عظم البشارة في آل عمران مقارنة بمريم.","url":""}]},{"id":"s3-1030","number":1030,"surah":3,"verses":[39,125],"references":[{"surah":3,"verses":[39,125]}],"verseLabel":"آل عمران: 39، 125","question":"كيف يجمع التعبير عن الملائكة في ﴿فَنَادَتْهُ﴾ و﴿مُسَوِّمِينَ﴾ بين رقة البشارة وتصحيح التصور العقدي؟","answer":"سمح مقام البشارة بتأنيث الفعل مع جمع التكسير، لكنه أبقى أوصاف الملائكة وأوامرهم على التذكير؛ فلا تتحول رقة الأسلوب إلى إقرار لوهم المشركين بأن الملائكة إناث. وبهذا يجمع النظم بين مناسبة المقام ودقة التصور العقدي.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، الخط التعبيري والعقيدة في وصف الملائكة.","url":""}]},{"id":"s3-945","number":945,"surah":3,"verses":[40],"references":[{"surah":3,"verses":[40]}],"verseLabel":"آل عمران: 40","question":"ما سر اختلاف التعبير بين ﴿وَقَدْ بَلَغَنِيَ الْكِبَرُ﴾ في آل عمران، و﴿وَقَدْ بَلَغْتُ مِنَ الْكِبَرِ عِتِيًّا﴾ في مريم؟","answer":"في آل عمران صُوِّر الكِبَر كأنه هو الذي أدرك زكريا وبلغه، فجاء الكِبَر فاعلًا في التعبير. أما في مريم فصُوِّر زكريا هو الذي بلغ من الكِبَر غايته، فجاء الفعل مسندًا إليه. والاختلاف ينسجم مع اختلاف سياق السورتين ومقدار بسط حال الشيخوخة فيهما.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف التعبير في «بلغني الكبر» و«بلغت من الكبر».","url":""}]},{"id":"s3-946","number":946,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما سر تقديم ﴿الْعَشِيِّ﴾ على ﴿الْإِبْكَارِ﴾ في آل عمران، مع تقديم ﴿بُكْرَةً﴾ على ﴿عَشِيًّا﴾ في مريم؟","answer":"لما ذكر الليل في مريم، ناسبت «بكرة» ما يأتي بعد الليل مباشرة، ثم جاءت العشية. أما في آل عمران فالمذكور ثلاثة أيام، فلو قُدمت البكرة لفات أول النهار قبل أن يأتي الأمر بالعشي؛ لذلك قُدّم العشي ليشمل الأمر طرفي النهار على الوجه الأنسب للسياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم العشي والإبكار في آل عمران ومريم.","url":""}]},{"id":"s3-947","number":947,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما دلالة التعريف في ﴿بِالْعَشِيِّ وَالْإِبْكَارِ﴾، مقابل التنكير في ﴿بُكْرَةً وَعَشِيًّا﴾؟","answer":"التعريف في «العشي والإبكار» يفيد العموم والدوام، لا وقتًا عابرًا في أيام محددة؛ وهذا يناسب عظم البشارة في آل عمران وما يقتضيه من دوام الشكر. أما «بكرة وعشيًا» فأنسب بسياق وقت محدد في قصة مريم، ولذلك جاء اللفظان نكرتين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التعريف والتنكير في «العشي والإبكار».","url":""}]},{"id":"s3-948","number":948,"surah":3,"verses":[52],"references":[{"surah":3,"verses":[52]}],"verseLabel":"آل عمران: 52","question":"ما وجه المقابلة بين قول عيسى: ﴿مَنْ أَنصَارِي إِلَى اللَّهِ﴾، وقول الحواريين: ﴿نَحْنُ أَنصَارُ اللَّهِ﴾؟","answer":"يحتمل قول عيسى: من ينصر دين الله معه، أو من يكون معه في نصرة الله له وتأييده. أما الحواريون فنسبوا النصرة إلى الله مباشرة؛ ليعلنوا أن نصرتهم للرسالة لا تتوقف على بقاء عيسى بينهم، بل تستمر ما دام المقصود نصرة دين الله.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، «من أنصاري إلى الله» و«نحن أنصار الله».","url":""}]},{"id":"s3-949","number":949,"surah":3,"verses":[55],"references":[{"surah":3,"verses":[55]}],"verseLabel":"آل عمران: 55","question":"ما دلالة التعبير بـ﴿إِنِّي مُتَوَفِّيكَ﴾، وهل يلزم من التوفي هنا معنى الموت؟","answer":"التوفي أوسع من الموت؛ فقد يأتي بمعنى الأخذ والاستيفاء، أو القبض عن التصرف الاختياري كما في النوم، وقد يأتي بمعنى الموت في سياقات أخرى. لذلك لا تدل كلمة «متوفيك» وحدها على الموت ضرورة، بل يحدد السياق والقرائن المراد، مع بقاء معنى رفع عيسى ظاهرًا في تتمة الآية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «متوفيك».","url":""}]},{"id":"s3-992","number":992,"surah":3,"verses":[60],"references":[{"surah":3,"verses":[60]}],"verseLabel":"آل عمران: 60","question":"ما دلالة ختم تقرير قصة عيسى بقوله تعالى: ﴿الْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ الْمُمْتَرِينَ﴾؟","answer":"التعبير ينقل الكلام من عرض القصة إلى تثبيت مصدرها ونتيجتها: هذا هو الحق الصادر من ربك، لا رواية بشرية قابلة للشك. ثم جاء النهي عن الامتراء ليغلق باب التردد بعد قيام البيان، فناسب ختام البرهان ختامًا يقرر اليقين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الحجج والبراهين في قصة عيسى.","url":""}]},{"id":"s3-993","number":993,"surah":3,"verses":[61],"references":[{"surah":3,"verses":[61]}],"verseLabel":"آل عمران: 61","question":"ما سر الجمع في المباهلة بين ﴿أَبْنَاءَنَا وَأَبْنَاءَكُمْ﴾ و﴿نِسَاءَنَا وَنِسَاءَكُمْ﴾، مع أن المتجادلين كانوا رجالًا؟","answer":"إدخال الأبناء والنساء يجعل المباهلة أبلغ في إظهار اليقين؛ لأن الإنسان أشد حرصًا على أهله وأولاده من حرصه على نفسه أحيانًا. فمن كان مكابرًا يخاف على دنياه وأهله، فإذا دُعي إلى إحضارهم ظهر صدقه أو انكشاف كذبه، فلم تعد المواجهة مجرد جدال بين رجال.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أسلوب المباهلة وإحضار الأبناء والنساء.","url":""}]},{"id":"s3-994","number":994,"surah":3,"verses":[62],"references":[{"surah":3,"verses":[62]}],"verseLabel":"آل عمران: 62","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿إِنَّ هَذَا لَهُوَ الْقَصَصُ الْحَقُّ﴾؟","answer":"ضمير الفصل يقوّي الحكم ويفصل بين كون «القصص» خبرًا وبين احتمال كونه وصفًا أو بدلًا. ومع دخول اللام يتأكد أن هذا المعروض هو القصص الحق، لا رواية أخرى من الروايات التي تداولها أهل الكتاب. فاجتمع في التركيب التوكيد والتقرير والحصر السياقي.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة ضمير الفصل في «لهو القصص الحق».","url":""}]},{"id":"s3-995","number":995,"surah":3,"verses":[64],"references":[{"surah":3,"verses":[64]}],"verseLabel":"آل عمران: 64","question":"ما دلالة وصف الكلمة بأنها ﴿سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ﴾، وما الذي يحققه القيد «بيننا وبينكم»؟","answer":"«سواء» تعني أمرًا عدلًا مستويًا لا يختص بفريق دون فريق. ثم جاء «بيننا وبينكم» ليؤكد أن أصل التوحيد ليس مطلبًا خاصًا بالمسلمين في الحوار، بل أصلًا مشتركًا تقوم عليه الحجة على الجميع. فإذا رفضوه بعد ذلك ظهر أن الخلاف ليس في غموض الأصل، بل في الإعراض عنه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الكلمة الجامعة في حوار أهل الكتاب.","url":""}]},{"id":"s3-950","number":950,"surah":3,"verses":[68],"references":[{"surah":3,"verses":[68]}],"verseLabel":"آل عمران: 68","question":"ما سر التعبير بـ﴿لَلَّذِينَ اتَّبَعُوهُ﴾ بدل «للذين آمنوا به» في بيان أولى الناس بإبراهيم؟","answer":"لو قيل «الذين آمنوا» لادعى اليهود والنصارى أنهم أولى بإبراهيم؛ لأن كل فريق يصف نفسه بالإيمان. أما «اتبعوه» فتربط الأولوية باتباع منهجه وحنيفـيته، فتخرج الدعوى المجردة وتثبت القرب لمن وافق طريقه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، «الذين اتبعوه» لا «الذين آمنوا به».","url":""}]},{"id":"s3-996","number":996,"surah":3,"verses":[71],"references":[{"surah":3,"verses":[71]}],"verseLabel":"آل عمران: 71","question":"ما الصورة التي يرسمها التعبير بـ﴿تَلْبِسُونَ الْحَقَّ بِالْبَاطِلِ﴾، ولماذا عُطف عليه ﴿وَتَكْتُمُونَ الْحَقَّ﴾؟","answer":"اللبس خلط الحق بالباطل حتى يشتبه أحدهما بالآخر، أما الكتمان فإخفاء الحق بعد معرفته. فذكر الفعلان مرحلتين من التحريف: تشويه الحق بإدخال الباطل فيه، ثم حجبه عن الناس. وهذا أبلغ من الاقتصار على وصف واحد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، لبس الحق بالباطل وكتمانه.","url":""}]},{"id":"s3-997","number":997,"surah":3,"verses":[73],"references":[{"surah":3,"verses":[73]}],"verseLabel":"آل عمران: 73","question":"ما سر ورود قوله تعالى: ﴿أَن يُؤْتَى أَحَدٌ مِّثْلَ مَا أُوتِيتُمْ﴾ في سياق حسد أهل الكتاب؟","answer":"يكشف التعبير أن اعتراضهم ليس قائمًا على برهان، بل على خوف أن يُعطى غيرهم مثل ما أوتوا من الكتاب والعلم. فجاء الرد بتحويل الأمر إلى يد الله: الفضل ليس ملكًا لجماعة تحتكره، بل يؤتيه الله من يشاء، وبذلك يُبطل أساس الحسد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفضل بيد الله في الآية 73.","url":""}]},{"id":"s3-998","number":998,"surah":3,"verses":[76],"references":[{"surah":3,"verses":[76]}],"verseLabel":"آل عمران: 76","question":"ما سر مجيء التصحيح بقوله: ﴿بَلَى مَنْ أَوْفَى بِعَهْدِهِ وَاتَّقَى﴾ بعد دعوى ﴿لَيْسَ عَلَيْنَا فِي الْأُمِّيِّينَ سَبِيلٌ﴾؟","answer":"«بلى» ترد دعواهم من أصلها، ثم ينقل الميزان من الانتماء إلى الوفاء والتقوى. فليس المعيار كون الإنسان من أهل الكتاب أو من غيرهم، بل حفظ العهد ومراقبة الله؛ ولذلك ختم بمحبة الله للمتقين، لا بمحبة طائفة بعينها.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الوفاء بالعهد والتقوى.","url":""}]},{"id":"s3-951","number":951,"surah":3,"verses":[78],"references":[{"surah":3,"verses":[78]}],"verseLabel":"آل عمران: 78","question":"ما دلالة اختيار ﴿وَمَا هُوَ مِنَ الْكِتَابِ﴾ و﴿وَمَا هُوَ مِنْ عِندِ اللَّهِ﴾، بدل أداة نفي أخرى؟","answer":"«ما» تأتي في الغالب ردًّا على قول أو دعوى سابقة. وهؤلاء قالوا: «هو من الكتاب» و«هو من عند الله»، فجاء النفي بـ«ما» ليبطل دعواهم مباشرة، لا ليقرر نفيًا مجردًا منفصلًا عن كلامهم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «ما» في رد الدعوى.","url":""}]},{"id":"s3-999","number":999,"surah":3,"verses":[79],"references":[{"surah":3,"verses":[79]}],"verseLabel":"آل عمران: 79","question":"ما دلالة نفي أن يقول النبي للناس: ﴿كُونُوا عِبَادًا لِّي مِن دُونِ اللَّهِ﴾ قبل الأمر بـ﴿كُونُوا رَبَّانِيِّينَ﴾؟","answer":"بدأ بالنفي ليقرر استحالة أن تكون النبوة طريقًا إلى عبادة الأشخاص، ثم أقام البديل الصحيح: أن يصير الناس ربانيين، أي أهل علم بالله وعبادة وتعليم للكتاب. فالمقابلة تميز بين تربية الناس على التعلق بالبشر وتربيتهم على العلم بالله.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، كونوا ربانيين.","url":""}]},{"id":"s3-1040","number":1040,"surah":3,"verses":[84],"references":[{"surah":3,"verses":[84]}],"verseLabel":"آل عمران: 84","question":"ما سر اجتماع إسماعيل وإسحاق في قائمة الأنبياء بالآية 84، وذكر إسماعيل دون إسحاق في رفع قواعد البيت؟","answer":"مقام آل عمران مقام الإيمان بجميع الوحي والأنبياء، فذُكر ابنا إبراهيم في سلسلة واحدة. أما بناء الكعبة فحدث شارك فيه إسماعيل مع أبيه ولم يكن لإسحاق تعلق به؛ فاختار كل سياق من الأسماء ما يتصل بموضوعه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، مواضع ذكر إسماعيل وإسحاق.","url":""}]},{"id":"s3-1000","number":1000,"surah":3,"verses":[85],"references":[{"surah":3,"verses":[85]}],"verseLabel":"آل عمران: 85","question":"ما دلالة التعبير بـ﴿غَيْرَ الْإِسْلَامِ دِينًا﴾، وما الذي يفيده تنكير «دينًا»؟","answer":"التعبير يجعل الإسلام هو المنهج المقبول، ويجعل ما عداه جنسًا آخر من الاعتقاد لا يحقق المطلوب. وتنكير «دينًا» يفيد العموم: أي طريق ديني غير الإسلام، فلا يختص الرفض بمذهب بعينه. ثم جاء ختام الآية بالخسران ليبين أن القضية عاقبتها عملية وليست جدلًا لفظيًا.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ومن يبتغ غير الإسلام دينًا.","url":""}]},{"id":"s3-952","number":952,"surah":3,"verses":[88],"references":[{"surah":3,"verses":[88]}],"verseLabel":"آل عمران: 88","question":"ما سر التعبير بـ﴿وَلَا هُمْ يُنظَرُونَ﴾ في آل عمران، مقابل ﴿وَلَا هُمْ يُنصَرُونَ﴾ في البقرة؟","answer":"آية البقرة 86 سبقت بذكر القتال والقتل، فناسبها نفي النصرة. أما آية آل عمران وآية البقرة 162 فسبقهما ذكر اللعنة والطرد، فناسبهما «ينظرون» بمعنى لا يُمهلون ولا يُنظر إليهم نظر رحمة؛ فاختار كل ختام ما يلائم سياقه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، «ينصرون» و«ينظرون» بحسب السياق.","url":""}]},{"id":"s3-1001","number":1001,"surah":3,"verses":[90,91],"references":[{"surah":3,"verses":[90,91]}],"verseLabel":"آل عمران: 90–91","question":"ما سر مجيء الواو في ﴿وَأُولَئِكَ هُمُ الضَّالُّونَ﴾، والفاء في ﴿فَلَنْ يُقْبَلَ مِنْ أَحَدِهِمْ﴾؟","answer":"الآية 90 تتحدث عن قوم ما زال باب التوبة في الدنيا مفتوحًا لهم، فجاء العطف بالواو لمطلق الجمع. أما الآية 91 فذكرت الموت على الكفر، فانتهى العمل وأصبح عدم القبول نتيجة مترتبة مباشرة، فجاءت الفاء لتصوير التعقيب واللزوم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الواو والفاء في الآيتين 90–91.","url":""}]},{"id":"s3-1002","number":1002,"surah":3,"verses":[94],"references":[{"surah":3,"verses":[94]}],"verseLabel":"آل عمران: 94","question":"ما سر تعريف لفظ ﴿الْكَذِبَ﴾ في قوله تعالى: ﴿فَمَنِ افْتَرَى عَلَى اللَّهِ الْكَذِبَ﴾؟","answer":"التعريف هنا للعهد، أي الكذب المتعلق بالمسألة المحددة التي سبق ذكرها: نسبة تحريم الطعام إلى الله. أما إذا أريد جنس الكذب على وجه العموم جاء منكّرًا في مواضع أخرى. فالتعريف يربط الجريمة بالافتراء المحدد الذي أقيمت عليه الحجة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تعريف «الكذب» وتنكيره.","url":""}]},{"id":"s3-1003","number":1003,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سر التعبير بـ﴿وَلَا تَفَرَّقُوا﴾ في آل عمران، مقابل ﴿وَلَا تَتَفَرَّقُوا﴾ في سورة الشورى؟","answer":"آل عمران تخاطب الأمة المسلمة في موقف خاص، فناسب حذف التاء الدال على الإيجاز وقلة الحدث، مع إرادة النهي عن أي تفرق ولو كان قليلاً. أما الشورى فتتحدث عن وصية ممتدة من نوح إلى خاتم الأنبياء، فناسب الفعل الأطول الممتد مع عموم الأزمنة والأمم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تفرقوا وتتفرقوا.","url":""}]},{"id":"s3-1004","number":1004,"surah":3,"verses":[105],"references":[{"surah":3,"verses":[105]}],"verseLabel":"آل عمران: 105","question":"ما سر مجيء الفعل في قوله تعالى: ﴿مَا جَاءَهُمُ الْبَيِّنَاتُ﴾ مذكرًا، مع وروده مؤنثًا في مواضع أخرى؟","answer":"ليست المسألة مجرد جواز نحوي، بل مناسبة للمعنى. فـ«البينات» هنا بمعنى الأوامر والنواهي والدين، فجاء الفعل مذكرًا، بينما تؤنث في المواضع التي يراد بها الآيات والمعجزات والعلامات الظاهرة. فاختلاف التذكير والتأنيث مرتبط بتغير الدلالة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، جاءهم البينات وجاءتهم البينات.","url":""}]},{"id":"s3-1005","number":1005,"surah":3,"verses":[106,107],"references":[{"surah":3,"verses":[106,107]}],"verseLabel":"آل عمران: 106–107","question":"ما سر تقديم ﴿تَبْيَضُّ وُجُوهٌ﴾ على ﴿تَسْوَدُّ وُجُوهٌ﴾ في الإجمال، ثم تقديم أصحاب الوجوه السوداء عند التفصيل؟","answer":"عند الإجمال كان الخطاب مستمرًا للمؤمنين، وهم أصحاب الوجوه البيضاء، فقدم ما يناسب المخاطبين. وعند التفصيل بدأ بأصحاب الوجوه السوداء لأن الكلام اتجه إليهم بالعتاب: ﴿أَكَفَرْتُم بَعْدَ إِيمَانِكُمْ﴾، ثم انتقل إلى أصحاب الوجوه البيضاء بصيغة الغيبة. فترتيب الطرفين تابع لتحول المخاطب والسياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم بياض الوجوه وسوادها.","url":""}]},{"id":"s3-1017","number":1017,"surah":3,"verses":[109,180],"references":[{"surah":3,"verses":[109,180]}],"verseLabel":"آل عمران: 109، 180","question":"ما وجه الانتقال من ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ إلى ﴿وَلِلَّهِ مِيرَاثُ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"الأولى تقرر ملك الله القائم لكل ما في الكون، والثانية تواجه البخل بإظهار مآل ما يتداوله الناس: يرجع كله إلى الله ويبقى له وحده. فلفظ الميراث يضيف إلى أصل الملك معنى زوال أيدي الخلق وبطلان احتباسهم لما أوتوا.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ملك السماوات والأرض، وميراث السماوات والأرض.","url":""}]},{"id":"s3-953","number":953,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سر التعبير بـ﴿وَأَكْثَرُهُمُ الْفَاسِقُونَ﴾ في آل عمران، مقابل ﴿كَثِيرٌ مِّنْهُمْ فَاسِقُونَ﴾ في الحديد؟","answer":"«أكثر» اسم تفضيل، ويناسب مقامًا طال فيه تعداد صفات أهل الكتاب ومساوئهم، كما في سياق آل عمران. أما «كثير» فجاء في سياق أقصر لم يسترسل في تعداد تلك الصفات، فاختار التعبير الأقل مبالغة بحسب مقدار التفصيل في السياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، «أكثرهم الفاسقون» و«كثير منهم فاسقون».","url":""}]},{"id":"s3-957","number":957,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما دلالة فصل المسكنة عن الذلة في آل عمران بعد قوله: ﴿وَبَاءُوا بِغَضَبٍ مِنَ اللَّهِ﴾؟","answer":"ترتيب الآية يصور تتابع آثار الانحراف: ذلة تحيط بهم، ثم غضب إلهي بسبب كفرهم وعدوانهم، ثم مسكنة تلحق بهم. فالفصل لا يفيد مجرد تنويع لفظي، بل يجعل العقوبات كأنها حلقات متتابعة تزداد إحاطةً بهم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفصل بين الذلة والمسكنة بذكر الغضب.","url":""}]},{"id":"s3-1006","number":1006,"surah":3,"verses":[113,199],"references":[{"surah":3,"verses":[113,199]}],"verseLabel":"آل عمران: 113، 199","question":"ما وجه الصلة بين ﴿لَيْسُوا سَوَاءً﴾ في أول الثناء على أهل الكتاب، و﴿وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ﴾ قرب ختام السورة؟","answer":"الموضع الأول ينفي التسوية الجائرة ثم يصف الطائفة الصالحة، والموضع الأخير يعيد تقرير وجود المؤمنين منهم بعد عرض طويل للمواقف والصراعات. وبذلك يظل ميزان السورة عادلًا من أول الحوار إلى آخره، فلا يطغى وصف الأكثرية على حق الأقلية المؤمنة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، العدل في النظرة إلى أهل الكتاب، والمؤمنون من أهل الكتاب.","url":""}]},{"id":"s3-958","number":958,"surah":3,"verses":[114],"references":[{"surah":3,"verses":[114]}],"verseLabel":"آل عمران: 114","question":"ما وجه المقابلة بين ﴿يُسَارِعُونَ فِي الْخَيْرَاتِ﴾ و﴿يُسَارِعُونَ فِي الْكُفْرِ﴾؟","answer":"في الموضعين يصور التعبير حالًا قائمة في أصحابها؛ فأهل الصلاح متمكنون في عمل الخير، وأهل الكفر متمادون في الكفر. لم يقل «إلى الكفر» لأن الكلام عن قوم استقر الكفر فيهم، كما استقر الخير في الفريق الأول.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المقابلة بين المسارعة في الخيرات والمسارعة في الكفر.","url":""}]},{"id":"s3-1007","number":1007,"surah":3,"verses":[120,200],"references":[{"surah":3,"verses":[120,200]}],"verseLabel":"آل عمران: 120، 200","question":"ما سر ختم القسم الأول من السورة بشرط ﴿وَإِنْ تَصْبِرُوا وَتَتَّقُوا﴾، وختم السورة كلها بالأمر ﴿اصْبِرُوا وَصَابِرُوا... وَاتَّقُوا اللَّهَ﴾؟","answer":"نهاية القسم الأول تقدم الصبر والتقوى علاجًا للكيد الخارجي، أما خاتمة السورة فتوسع العلاج إلى الصبر والمصابرة والمرابطة بعد عرض الابتلاء الداخلي في أُحد. فتتكرر الركيزتان، لكن الخاتمة تحول المعنى إلى برنامج جماعي دائم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، بناء السورة على الثبات وخاتمتا قسميها.","url":""}]},{"id":"s3-1008","number":1008,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"ما الذي تضيفه ﴿قَدْ﴾ إلى قوله: ﴿وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ﴾؟","answer":"«قد» مع الماضي لا يفارقها التحقيق، فجعلت النصر حقيقة مقررة لا مجال للشك فيها. وفي هذا الموضع يصاحب التحقيق معنى التوقع والتقريب؛ لأن الله كان قد وعد المؤمنين، ثم وقع النصر قريبًا شاهدًا يثبت قلوبهم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «قد» في نصر بدر.","url":""}]},{"id":"s3-1009","number":1009,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"ما أثر اجتماع اللام و«قد» في ﴿وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ﴾ في مقام مواساة المؤمنين؟","answer":"اللام تقوي الخبر و«قد» تحققه، فيستحضر المؤمنون نصر بدر كحقيقة ثابتة لا كذكرى محتملة. وهذا التوكيد مناسب لمن أصابهم القرح في أُحد؛ إذ يعيدهم إلى شاهد سابق على أن النصر من عند الله وليس بكثرة العدد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، «قد» والتحقيق في آية بدر.","url":""}]},{"id":"s3-1010","number":1010,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"ما سر الجمع بين تحقق النصر في ﴿وَلَقَدْ نَصَرَكُمُ اللَّهُ﴾ ووصف الحال ﴿وَأَنْتُمْ أَذِلَّةٌ﴾؟","answer":"ذكر الضعف مع النصر يقطع تعلق القلب بالأسباب المجردة؛ فقد تحقق النصر يوم قلة العدد والعدة. ولذلك أعقب المشهد بالتقوى والشكر، حتى تتحول ذكرى بدر من باعث على الغرور إلى دليل على افتقار المؤمنين إلى ربهم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، نصر بدر في سياق تثبيت المؤمنين.","url":""}]},{"id":"s3-959","number":959,"surah":3,"verses":[124,125],"references":[{"surah":3,"verses":[124,125]}],"verseLabel":"آل عمران: 124–125","question":"ما دلالة اختلاف أوصاف الملائكة بين ﴿مُنْزَلِينَ﴾ و﴿مُسَوِّمِينَ﴾ و﴿مُرْدِفِينَ﴾؟","answer":"«منزلين» يبرز إنزالهم بأمر الله، و«مسومين» يبرز علامتهم وتمييزهم في القتال، و«مردفين» يصور مجيئهم متتابعين بعضهم إثر بعض. فكل وصف يلتقط جانبًا من مشهد الإمداد، ولا يؤدي أحدها وظيفة الآخر.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، منزلين ومسومين ومردفين.","url":""}]},{"id":"s3-1029","number":1029,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"ما دلالة وصف الملائكة بصيغة التذكير في ﴿مِنَ الْمَلَائِكَةِ مُسَوِّمِينَ﴾، مع مجيء ﴿فَنَادَتْهُ الْمَلَائِكَةُ﴾ مؤنث الفعل؟","answer":"الوصف الاسمي للملائكة يجري في القرآن على التذكير، ولذلك قيل ﴿مُسَوِّمِينَ﴾. أما تأنيث الفعل في ﴿فنادته﴾ فمراعاة لجمع التكسير في مقام البشارة؛ ففرّق النظم بين وصف حقيقتهم وصفًا ثابتًا، وبين اختيار صيغة فعل تلائم جو الحدث.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، أوصاف الملائكة الاسمية.","url":""}]},{"id":"s3-1011","number":1011,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]}],"verseLabel":"آل عمران: 126","question":"ما دلالة مجيء طمأنينة القلوب غايةً للإمداد في قوله: ﴿وَلِتَطْمَئِنَّ قُلُوبُكُمْ بِهِ﴾؟","answer":"لم يجعل الإمداد آلة قتال مستقلة، بل جعله أولًا بشرى وسببًا لطمأنينة القلوب. فالانكسار النفسي بعد الابتلاء يحتاج إلى إعادة الثقة بوعد الله، وحين تطمئن القلوب تستقيم الطاعة ويؤخذ بالأسباب من غير اضطراب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المقام مقام مسح على القلوب.","url":""}]},{"id":"s3-954","number":954,"surah":3,"verses":[132],"references":[{"surah":3,"verses":[132]}],"verseLabel":"آل عمران: 132","question":"ما دلالة مجيء ﴿أَطِيعُوا اللَّهَ وَالرَّسُولَ﴾ في آل عمران، مقابل تكرار فعل الطاعة في مواضع أخرى؟","answer":"إذا لم يتكرر فعل الطاعة يكون السياق قد جمع طاعة الله وطاعة الرسول في نسق واحد، كما في آل عمران. أما تكرار «أطيعوا» فيأتي حين يكون للرسول حضور مستقل في السياق أو تكون طاعته مقصودة بجهة مستقلة؛ فالتكرار يبرز استقلال الجهة، والحذف يحقق الجمع والاقتصاد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، صيغ الأمر بطاعة الله والرسول.","url":""}]},{"id":"s3-1013","number":1013,"surah":3,"verses":[132],"references":[{"surah":3,"verses":[132]}],"verseLabel":"آل عمران: 132","question":"ما دلالة عدم تكرار فعل الطاعة في قوله: ﴿وَأَطِيعُوا اللَّهَ وَالرَّسُولَ﴾؟","answer":"إذا لم يتكرر فعل الطاعة كان الأمر واحدًا في مصدره ومقصده، لأن طاعة الرسول فيما يبلغ هي طاعة لله. أما تكرار الفعل فيأتي في سياقات يُراد فيها إبراز ما حُمِّل الرسول من أمر أو بيان استقلال جهة طاعته فيما فوضه الله إليه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تكرار فعل الطاعة وحذفه.","url":""}]},{"id":"s3-960","number":960,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما دلالة تنكير ﴿مَغْفِرَةٍ﴾ في قوله: ﴿وَسَارِعُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ﴾؟","answer":"التنكير يفتح معنى التعظيم والتفخيم، فلا يحدد المغفرة بمقدار ضيق أو صورة واحدة، بل يتركها واسعة عظيمة في تصور السامع. ثم زادها شرفًا بإضافتها إلى الرب سبحانه في قوله «من ربكم».","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تنكير مغفرة ووصلها بـ«من ربكم».","url":""}]},{"id":"s3-961","number":961,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما دلالة الجمع في ﴿السَّمَاوَاتِ﴾ والإفراد في ﴿السَّمَاءِ﴾ بين آل عمران والحديد؟","answer":"جمع السماوات في آل عمران يوافق مقام التحديد والتفصيل، كما يوافق وصف الجنة المعدة للمتقين. أما إفراد السماء في الحديد فيتسع لمعنى ما علا وشمل السماوات وغيرها، فناسب سياق التوسعة والفضل العام.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، السماوات والسماء في آيتي الجنة.","url":""}]},{"id":"s3-962","number":962,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما دلالة وصف الجنة في آل عمران بأنها ﴿أُعِدَّتْ لِلْمُتَّقِينَ﴾، وفي الحديد بأنها ﴿أُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ﴾؟","answer":"سبق آل عمران تكرار الأمر بالتقوى والنهي عن الربا واتقاء النار، فناسب أن يذكر المتقين ثم يصفهم بالإنفاق وكظم الغيظ والعفو. أما الحديد فسبق فيه ذكر الإيمان بالله ورسله، فجاء الوصف موافقًا لذلك السياق الأوسع.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المتقون والذين آمنوا بالله ورسله.","url":""}]},{"id":"s3-963","number":963,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما دلالة تكرر الحديث عن التقوى قبل قوله: ﴿أُعِدَّتْ لِلْمُتَّقِينَ﴾؟","answer":"تكرر الأمر بالتقوى في النهي عن الربا واتقاء النار، ثم جاءت الجنة معدة للمتقين، فبُني السياق من التكليف إلى الجزاء. بذلك لا تبدو كلمة «المتقين» وصفًا عابرًا، بل نتيجة طبيعية لما سبق من أوامر ونواهٍ.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تكرر التقوى ومناسبة «للمتقين».","url":""}]},{"id":"s3-973","number":973,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما سر الجمع بين التنكير في «مغفرة» وذكر الجنة بعدها في قوله: ﴿وَجَنَّةٍ عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ﴾؟","answer":"بدأ السياق بمغفرة عظيمة غير محدودة، ثم أتبعها بجنة يضخم سعتها بذكر عرض السماوات والأرض. فاجتمع في الوصف تعظيم الجزاء بالكيف في المغفرة، وبالتصوير المكاني في الجنة، ليقوى باعث المسارعة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التعظيم في المغفرة والجنة.","url":""}]},{"id":"s3-964","number":964,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"ما وجه الصلة بين ذكر صفات المتقين في الآية 134، وبين النهي السابق عن أكل الربا أضعافًا مضاعفة؟","answer":"الربا استغلال لحاجة المضطر وزيادة في أعبائه، فجاء وصف المتقين بالإنفاق في السراء والضراء ليضع البديل الأخلاقي: إعانة المحتاج بدل استغلاله. ثم تتسع الصورة إلى ضبط الغضب والعفو والإحسان، فتكتمل ملامح التقوى العملية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، صلة آيات التقوى بآية الربا.","url":""}]},{"id":"s3-965","number":965,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"ما دلالة جمع ﴿الْكَاظِمِينَ الْغَيْظَ وَالْعَافِينَ عَنِ النَّاسِ﴾ بعد وصف الإنفاق؟","answer":"ينتقل السياق من إحسان المتقي في المال إلى إحسانه في التعامل مع الناس؛ فكظم الغيظ ضبط لبداية الانفعال، والعفو تجاوز عن أثره بعد وقوع الإساءة. وبهذا تتكامل التقوى في المال والنفس والعلاقة بالآخرين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أوصاف المتقين بعد الإنفاق.","url":""}]},{"id":"s3-955","number":955,"surah":3,"verses":[140,141],"references":[{"surah":3,"verses":[140,141]}],"verseLabel":"آل عمران: 140–141","question":"ما سر ذكر اللام في ﴿وَلِيَعْلَمَ﴾ و﴿وَلِيُمَحِّصَ﴾، وعدم تكرارها قبل ﴿يَتَّخِذَ﴾ و﴿يَمْحَقَ﴾؟","answer":"اللام المذكورة تقوي الغرض وتؤكده، وجاءت مع «يعلم» و«يمحص» لأن العلم بإيمان المؤمنين وتمحيصهم هو الأظهر والأوسع في المقام. أما اتخاذ الشهداء ومحق الكافرين فتابعان لذلك الغرض، فجاءا بعده من غير إعادة اللام.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ذكر اللام وحذفها في آيتي 140 و141.","url":""}]},{"id":"s3-966","number":966,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"ما سر اختلاف التعبير بين ﴿وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ﴾ و﴿وَسَنَجْزِي الشَّاكِرِينَ﴾؟","answer":"في الآية 144 صُرّح باسم الجلالة لأن الفعل السابق «ينقلب» مسند إلى شخص آخر، فاحتيج إلى إظهار الفاعل الذي يجزي. أما الآية 145 فالسياق كله بضمير المتكلم: «نؤته»، فناسب أن يأتي الجزاء بالضمير نفسه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، سيجزي الله وسنجزي.","url":""}]},{"id":"s3-1014","number":1014,"surah":3,"verses":[144,145],"references":[{"surah":3,"verses":[144,145]}],"verseLabel":"آل عمران: 144–145","question":"ما سر التصريح باسم الله في ﴿وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ﴾، ثم العدول إلى ضمير المتكلم في ﴿وَسَنَجْزِي الشَّاكِرِينَ﴾؟","answer":"في الآية الأولى سبق ذكر من ينقلب على عقبيه وأنه لن يضر الله، فالفاعل في فعل الضرر غير فاعل الجزاء؛ لذلك صُرح باسم الله لرفع الالتباس. وفي الثانية توالت أفعال المتكلم: ﴿نُؤْتِهِ﴾ ثم ﴿وَسَنَجْزِي﴾، فناسب الإضمار لاتحاد الفاعل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «سيجزي» و«سنجزي».","url":""}]},{"id":"s3-967","number":967,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"ما دلالة المضارع في ﴿مَن يُرِدْ ثَوَابَ الدُّنْيَا﴾ و﴿مَن يُرِدْ ثَوَابَ الْآخِرَةِ﴾، مقابل الماضي في ﴿مَنْ أَرَادَ الْآخِرَةَ﴾ بسورة الإسراء؟","answer":"إرادة الثواب تتجدد مع كل عمل، فجاء المضارع الدال على التكرر والاستمرار. أما الآخرة فغاية واحدة يقصدها العبد في أصل توجهه، فجاء الماضي في الإسراء مناسبًا لإرادة مستقرة محددة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المضارع والماضي في إرادة الثواب والآخرة.","url":""}]},{"id":"s3-968","number":968,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"ما سر تكرار قوله: ﴿وَمَن يُرِدْ ...﴾ مرتين في ثواب الدنيا وثواب الآخرة؟","answer":"التكرار يفصل بين مقصدين لا ينبغي خلطهما: ثواب الدنيا وثواب الآخرة. كما أن كل عمل متجدد قد يطلب صاحبه ثوابه، فناسب تكرار الفعل الدال على تجدد الإرادة، ثم جاء لكل إرادة جزاؤها المناسب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تكرر إرادة الثواب في الآية 145.","url":""}]}]);
